# 路径拼装又回到入口、两平台各写一遍）；②"只写一份"被"顺手再写个 sh 版本"绕过。故把三件可判定
# 的事（薄壳三件事、参数与退出码原样传递、不得在另一平台重写逻辑）与语言取舍一并钉住。
