#   ② 作为跨环境入口时的薄壳三件事与 `exit /b %errorlevel%`（不写则退出码是最后一条命令的）；
#   ③ 批处理**自身语言**的坑：`@echo off`、块语句延迟展开（`%var%` 在解析期展开）、
#      路径加引号、`%~1` 去引号判空、未定义变量当错误、`^` 续行不留尾随空格、不混写 PowerShell 语法。
