# 『精炼性（同一描述只写一处）』防线：用户本轮点名的两条要求——"精炼性规范应该在 review
# 及重构时强制生效""依旧有很多相同的描述在不同的地方，不满足精炼性的要求"。
# **判据本体**（不是轴名）：真源落点可核对的那几句——① 重复面是**必查项**（L1）且与
# "没发现重复"分得清；② 判定标准（任一命中即为重复描述）；③ 收敛形态＝**一处完整定义 +
# 其余一行引用**；④ 与 P3 的边界（删的只能是重复表述、须留引用、不确定的一律保留）；
# ⑤ 两类形态不得被当成重复收敛（最高关注项与其引用、各自的承接）；⑥ "篇幅大"≠"重复"。
# 另钉两处**动作落点**：改完即审的固定动作里要真的核重复面；两个提示词（review/refactor）
# 都通过 `delivery` 片段带上"重复面的处理"——否则"精炼性"只是通用层里的一段文字，
# 在 review 与重构任务里不会被执行（正是用户说的"应该在 review 及重构时强制生效"）。
