# 且**如实标注它没规定"必须合并"**：官方材料给的是语法能力与代价说明，本条属本集合的
# 判据化取舍。缺它则读者无法区分「MySQL 要求」与「本集合取舍」）。
ALTER_MERGE_LIBRARY = "library/sources.adoc"
