# **不在这里核**——与那两条写法同理：判据本体已在别处，依据再各钉一份属第二处真源。
# 只留 ALTER 合并的依据（本 PR 新增的那条）与全局的同义性标注。
ALTER_MERGE_LIBRARY_ANCHORS = (
    ("MySQL 官方文档条目（ALTER TABLE 与 Online DDL）", "MySQL 官方文档", "alter_option"),
    ("语义差异与取舍归属（同义性）", "并未规定", "本集合"),
)


def _subsection_text(text: str, keyword: str):
    """按**节标题关键词**取某个三级节的正文（`=== ` 起、到下一个同级或更高级标题止）。

    与 `_section_text`（二级节）互补：`=== ` 及更深层在 `_split_adoc_sections` 里归入
    所属二级节，故"某三级小节是否自成一体"用二级节取法判不出来（整段二级节都算命中）。
    代码块（`----` 定界）内的伪标题同样不计入。
    """
    lines = text.split("\n")
    start, in_block = None, False
    for idx, line in enumerate(lines):
        if line.strip() == "----":
            in_block = not in_block
        if in_block:
            continue
        m = re.match(r"^(=+)\s+(\S.*)$", line)
        if not m:
            continue
        if start is None:
            if len(m.group(1)) == 3 and keyword in m.group(2):
                start = idx
            continue
        if len(m.group(1)) <= 3:      # 同级或更高级标题：本小节结束
            return "\n".join(lines[start:idx])
    return "\n".join(lines[start:]) if start is not None else ""


def _section_anchor_check(rel, section_title, anchors):
    """公共实现：某文件某节的要点锚点须齐（三节共用，避免三份各自漂移）。"""
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {rel}——「{section_title}」的判据无处承载", rel)
        return False
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = _section_text(text, section_title)
    if not section:
        err(f"{rel} 缺少「{section_title}」节——该条失去落点"
            "（缺条目时执行者按「能跑就行 / 能省则省」收敛）", rel)
        return False
    for name, tokens, why in anchors:
        for token in tokens:
            if token not in section:
                err(f"「{section_title}」节缺少要点：{name}（应含 `{token}`）——{why}", rel)
    return True


def check_quality_guard():
    """『代码质量（新产出即高质）』防线：十项下限、判定标准与依据不得被删或降级。

"""
    phase("代码质量防线检查")
    _section_anchor_check(QUALITY_SPEC, QUALITY_SECTION, QUALITY_ANCHORS)
    with open(os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc"), encoding="utf-8") as fh:
        generic = fh.read()
    # 核的是**触发特征**（何时命中「写代码」这件事），不是条目名本身——
    # 原先要求调度器行里出现 `代码质量（新产出即高质）` 这一**节标题**（条目本体），
    # 属把本体的名抄进调度器（`terminology.adoc`「数据字典」的反膨胀）；已改为按
    # 「写/改代码 + 评审」这类可判读的触发特征定位该行。
    disp = next((ln for ln in generic.splitlines()
                 if "specs/general/coding.adoc" in ln
                 and "新代码" in ln and "代码评审" in ln), "")
    if not disp:
        err(f"加载调度器缺少「{QUALITY_SECTION}」的加载项与识别特征——"
            "缺则改代码时永远不会被触发加载、判据实际失效", "AGENTS_COMMON.adoc")
    else:
        for token in ("新代码", "代码评审"):
            if token not in disp:
                err(f"加载调度器代码质量条目缺少识别特征 `{token}`——"
                    "触发特征不全时，执行者会「没想到要按质量下限自查」", "AGENTS_COMMON.adoc")
    lpath = os.path.join(REPO_ROOT, *QUALITY_LIBRARY.split("/"))
    if not os.path.isfile(lpath):
        err(f"缺少 {QUALITY_LIBRARY}——代码质量与生成开销的依据无处承载"
            "（「十项逐条自检」「坏味道清单」将无从核对，也会被误读成标准规定）",
            QUALITY_LIBRARY)
    else:
        with open(lpath, encoding="utf-8") as fh:
            ltext = fh.read()
        for token in ("当初要解决的失效（本项目实证）",
                      "同义性差异与覆盖点（本集合自己承认的）",
                      "Martin Fowler《Refactoring", "Clean Code",
                      "SEI CERT Coding Standards", "未逐字取回", "ISO/IEC 25010"):
            if token not in ltext:
                err(f"{QUALITY_LIBRARY} 缺少依据锚点 `{token}`——"
                    "依据被压成名称后，读者无法区分「外部材料要求」与「本集合自己的取舍」",
                    QUALITY_LIBRARY)
    phase_done()


def check_generation_efficiency_guard():
    """『生成效率 / token 纪律』防线：两条判据、边界条与调度器登记不得被删或降级。

"""
    phase("生成效率与 token 纪律防线检查")
    _section_anchor_check(CONTEXT_SPEC, GEN_EFF_SECTION, GEN_EFF_ANCHORS)
    _section_anchor_check(CONTEXT_SPEC, TOKEN_SECTION, TOKEN_ANCHORS)
    with open(os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc"), encoding="utf-8") as fh:
        generic = fh.read()
    disp = next((ln for ln in generic.splitlines()
                 if "specs/general/context.adoc" in ln and GEN_EFF_SECTION in ln), "")
    if not disp:
        err(f"加载调度器缺少「{GEN_EFF_SECTION}」的加载项与识别特征——"
            "缺则它永远不会被触发加载、判据实际失效", "AGENTS_COMMON.adoc")
    else:
        for token in ("token 纪律", "生成效率", "安排取舍", "多次往返"):
            if token not in disp:
                err(f"加载调度器生成效率条目缺少识别特征 `{token}`——"
                    "触发特征不全时，执行者会「没想到这里还有可省的一步」", "AGENTS_COMMON.adoc")
    phase_done()


def check_after_change_review_guard():
    """『改动后复核』防线：五件事的固定动作、干净子 agent 与三态台账不得被删或降级。

"""
    phase("改动后复核防线检查")
    _section_anchor_check(VERIFY_SPEC, AFTER_REVIEW_SECTION, AFTER_REVIEW_ANCHORS)
    _section_anchor_check(REVIEW_SPEC, CHANGE_REVIEW_SECTION, CHANGE_REVIEW_ANCHORS)
    for rel, keys, desc in (
        ("specs-project-maintainer/verify.adoc",
         (AFTER_REVIEW_SECTION, "有了就忽略、没有就加", "check_specs_test.py",
          "check_effective_test.py"),
         "维护方侧须给出五件事的落点与「已有则忽略、没有就加」的归属口径"
         "（否则公共要求与本地动作之间断链）"),
        ("AGENTS.adoc",
         (AFTER_REVIEW_SECTION, "机械手段", "子 agent"),
         "维护方入口须登记该要求（缺则执行者不知道本仓库已有这份要求）"),
    ):
        fp = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(fp):
            err(f"缺少 {rel}——改动后复核在该处的落点无从核对", rel)
            continue
        with open(fp, encoding="utf-8") as fh:
            body = fh.read()
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"改动后复核防线被破坏：{rel} 缺失 {missing}——{desc}", rel)
    phase_done()


def check_refinement_guard():
    """『精炼性（同一描述只写一处）』防线：判据本体与两处动作落点不得被删或降级。

    用户点名（本轮）："精炼性规范应该在 review 及重构时强制生效""依旧有很多相同的描述
    在不同的地方，不满足精炼性的要求"。故本防线钉两件事：
      * **判据本体**在通用层一处（`specs/general/review.adoc`「精炼性」）——判定标准、
        收敛形态、与 P3 的边界、两类不得被当成重复的形态；
      * **动作落点**在改完即审的固定动作里（`specs/general/review.adoc`）与提示词公共片段
        `delivery`（review/refactor 两个提示词都 include，故改一处即两处生效）。
    """
    phase("精炼性防线检查（同一描述只写一处）")
    _section_anchor_check(REVIEW_SPEC, REFINEMENT_SECTION, REFINEMENT_ANCHORS)
    # 动作落点①：改完即审的固定动作里须真的核重复面（否则"精炼性"于每次改动都不生效）
    path = os.path.join(REPO_ROOT, *REVIEW_SPEC.split("/"))
    if os.path.isfile(path):
        text = open(path, encoding="utf-8").read()
        action = _section_text(text, CHANGE_REVIEW_SECTION)
        for token in ("固定动作", "重复面"):
            if token not in action:
                err(f"{REVIEW_SPEC} 的「{CHANGE_REVIEW_SECTION}」未把重复面纳入固定动作"
                    f"（缺 `{token}`）——「精炼性」在每次改动时就不会被执行，"
                    "只在专门做重构/评审的任务里才想起来", REVIEW_SPEC)
    # 动作落点②：提示词公共片段（review/refactor 共用）。
    # 路径**现场推导**（不引用可能被单测重定向的模块常量）：本函数只读 `REPO_ROOT` 下的
    # 这一个文件，写成常量路径时用例改了 `REPO_ROOT` 却读到了真实仓库的那一份、判据空转
    # ——正是本函数要防的"读的不是被校验的那一份"（本仓库实测：夹具下不报红）。
    rel_common = "prompts/_common.txt"
    path = os.path.join(REPO_ROOT, *rel_common.split("/"))
    if not os.path.isfile(path):
        err(f"缺失 {rel_common}——提示词的公共片段不在，"
            "「重复面的处理」这条动作无从在两处提示词里生效", rel_common)
    else:
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        for token, why in REFINEMENT_DELIVERY_ANCHORS:
            if token not in text:
                err(f"精炼性防线被破坏：{rel_common} 缺失 `{token}`——{why}", rel_common)
    phase_done()


# ---- 『逐字重复扫描』防线（同一件事不得两处逐字重复）----
# 用户要求（本轮）："全局检查下重复项，并处理"。
#
# 缺它时的失效：`specs/general/review.adoc`「精炼性」把"重复面"列为**必查项**，但此前
# **只有语义复核、没有机械抓手**——"同一件事只在一处给真源"于是靠自觉（本仓库实证：
# 同一段判据在 `verify.adoc` 与 `specs-project-maintainer/context.adoc` 各存一份；
# 两个提示词的公共步骤逐字重复、却不在公共片段里；git 侧与平台侧的推送口径逐字重复）。
#
# 本条**只做可逐字判定的事**：把文档切成语义实体（bullet 一级项含其续行 / 单行），做
# **全对**最长公共子串检测，再按**句子**扫一遍（拦"一处折叠、一处展开"与"成分被重组"）。
# 它是**下界**——阈值以下、或换了说法的重复核不出来，那是语义复核的事；把下界当上界
# （"机械全绿 ⇒ 没有重复"）与本条的初衷相反。
def check_duplicate_scan_guard():
    """『逐字重复扫描』防线：同一件事被两处逐字重复即报红（规则见 `specs-rules/duplicate.toml`）。

    落点与阈值一律在规则数据里；本函数只负责开阶段、接线与收尾——规则数据外置后，
    改判据（加一处落点、调阈值）不必动脚本（判据见 `specs/general/script.adoc`
    「规则与脚本的隔离（规则数据外置）」）。
    """
    phase("逐字重复扫描（同一件事不得两处逐字重复）")
    run_rule_guard("check_duplicate_scan_guard")
    phase_done()


