# 『登记处只做索引、不复述片段正文』防线。
# 背景（本轮重构实测）：`PROMPTS.adoc` 的"公共约定"曾把 `prompts/_common.txt` 各片段的
# 要点**逐条复述一遍**——同一约束有第二份正文，片段一改这里就漂移（规范的既有失效之一）。
# 本轮把它改为**索引**（只写"有哪几个片段、每个片段管哪条边界、正文唯一落点在片段里"）。
# 但"索引"也有反向失效：把某条边界从索引里**整条删掉**，读者就再也找不到它。
# 故本防线钉住**每条的落点必须能从登记处走到**（两种允许形态之一，逐条可核对）：
#   ① 登记处**自己写出**该边界的要点；或
#   ② 登记处**同时**写明该点**所归片段的名字**与"正文在 `_common.txt`"这一指向。
# 只认"要点文本还在登记处"会误判合规的索引形态；只认"片段名出现过"会漏掉"整条被删"。
_PROMPTS_INDEX_ENTRIES = (
    (("baseline-and-compat", "compat"), "基线与兼容（先查现状/最佳方案/先定基线、老用例不得改判）"),
    (("scope-boundary",), "改动范围边界（只改当前工作空间/当前项目）"),
    (("delivery",), "交付边界（交付即汇报、按环境区分、不合并）"),
    (("self-dispatch",), "不得自行发评论唤起自己"),
)
# ② 形态的必需指向语：登记处须显式说明"正文在片段里、此处只作索引"（否则读者以为这就是全文）
_PROMPTS_INDEX_POINTERS = ("不复述正文", "正文只写在", "一处维护、两处生效")

def check_declarative_rule_guard():
    """『以对象定义规则、不给具体操作』防线：规则只写到取值形态为止（写规范的写法口径）。

    失效形态（用户指出）：写规则时**顺手把"怎么取"也写进规范**——于是规范里给读者的
    是一个随环境变的操作流程，而不是一条判据；换个执行者、换台机器，同一句话读出的动作
    就不一样。用户给的判据形态是"定义 `mvn -T <核心数>` 就好了，不要在规范里写如何去拿核心数"。

    本条钉**判据本体**（条目正文本身、而非"这一节在不在"），并核两处已按新口径收敛的
    落点（Maven 栈规范与提示词公共片段）。只核文本形态——"某条新写的规则里到底算不算
    多写了取法"是否越过"消除歧义所需"这一层，属语义判断，交人/子 agent 复核。
    """
    phase("以对象定义规则、不给具体操作防线检查")
    rel_life = "specs-project-maintainer/spec-lifecycle.adoc"
    path = os.path.join(REPO_ROOT, *rel_life.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {rel_life}——『以对象定义规则、不给具体操作』的判据本体无处承载"
            "（缺则写规则时又会把取法一并写进规范）", rel_life)
    else:
        text = open(path, encoding="utf-8").read()
        if not _subsection_text(text, "以对象定义规则、不给具体操作"):
            err(f"{rel_life} 缺少「{DECLARATIVE_RULE_SUBSECTION}」小节——"
                "「规则只写到取值形态为止」失去落点：新写的规则会带着取数流程一起进规范",
                rel_life)
        else:
            run_rule_guard("check_declarative_rule_guard")
            run_rule_guard("check_declarative_rule_guard")
    phase_done()


def check_alter_merge_guard():
    """『ALTER 同类操作合并』防线：判据本体与判定标准不得被删或降级。

    用户要求（Issue #154）："调整规范 sql 下 alter 的同类操作（移动、新增等）可以合并为
    一条 sql（支持的情况下，mysql 就支持），优先合并，不要每个字段写一条"。

    本轮补充（用户在同一评论里追加的三点）**只钉其中一条**：DML 合并 + **用户主动写的
    除外、不告警**（例外**只适用于 DML**，DDL 一定会锁表故无例外）。另两点——SQL
    **须单独建文件**、写 SQL **须带库名（DDL/DML 强制）**——的判据本体已由
    `check_external_script_guard` 钉住（通用层「跨语言执行脚本的落点」的 L1 与 Java
    落点关键词），此处再各钉一份即**同一条规范的第二处真源**（口径见
    `specs-project-maintainer/spec-lifecycle.adoc`「新增规范的提案校验」的
    「同一事项不得留两处真源」与「一条规范何时该拆分」的「同一事项只有一个真源」）。

    落点（本轮调整，用户追加要求："应该要有个单独的 sql 规范文件"）取
    **`specs/general/sql.adoc`「SQL 写法」一个节**——SQL 是**跨语言写法**，不是 Java 的
    专属事实（判据对 Java 项目的 MySQL 与项目里的 `.sql` 迁移脚本同样成立），埋在某个
    技术栈文件的跨语言脚本条下会让非 Java 的 SQL 落不到判据；节级拆分而非文件级，是
    `specs-project-maintainer/spec-lifecycle.adoc`「一条规范何时该拆分」的取向——**判据
    形态相同（同一组文本判据）、加载时机相同，故共处一个节**，只为承载与可发现性单建文件。

    本函数还**核这条真源真的被加载得到**（本轮实测的失效形态：文件建对了、判据也齐，
    但登记与引用两处都没接上——执行者改 SQL 时根本走不到这个文件，等于没写）。

    本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "有没有这条 DDL 条"属防线空转——"同类操作"的定义、可核对的判定标准、合并不了的例外
    与存量边界任一被抽走时照样全绿。故逐条核 `ALTER_MERGE_ANCHORS`（每项要求「规则 +
    判定标准 + 边界」里的**可核对那句话**），并核调度器的识别特征（缺则改 DDL 时永远不会
    被触发加载、判据实际失效）。「某条迁移到底该不该合并」属语义判断（见 GUARD_CHECK_LIMITS）。
    """
    phase("SQL 写法（ALTER/DML 合并、独立成文件、库名）防线检查")
    path = os.path.join(REPO_ROOT, *ALTER_MERGE_SPEC.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {ALTER_MERGE_SPEC}——「SQL 写法（ALTER/DML 合并、独立成文件、库名）」"
            "的判据无处承载", ALTER_MERGE_SPEC)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = _section_text(text, ALTER_MERGE_SECTION)
    if not section:
        err(f"{ALTER_MERGE_SPEC} 缺少「{ALTER_MERGE_SECTION}」节——该条失去落点"
            "（缺条目时生成脚本会按字段逐条生成 ALTER、每条各自按一次表；"
            "SQL 也会被内联回 Java 字符串、表名不带库名）", ALTER_MERGE_SPEC)
    else:
        for name, tokens, why in ALTER_MERGE_ANCHORS:
            for token in tokens:
                if token not in section:
                    err(f"「{ALTER_MERGE_SECTION}」缺少要点：{name}（应含 `{token}`）——{why}",
                        ALTER_MERGE_SPEC)
    # 加载调度器（通用层）须登记该文件 + 识别特征：缺则改 SQL 时**永不触发加载**
    gate = os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc")
    disp = ""
    if os.path.isfile(gate):
        with open(gate, encoding="utf-8") as fh:
            generic = fh.read()
        # 判"有没有登记这一项"时**按文件名**认（登记行可能把路径写成别的形态：
        # `sql.adoc`、加链接、或漏一层目录——正是下面那条判据要抓的），故这里不能
        # 只按完整路径匹配，否则"路径写错了"会被报成"没登记"、真正的成因看不出来。
        base_name = ALTER_MERGE_SPEC.rsplit("/", 1)[-1]
        disp = next((ln for ln in generic.splitlines()
                     if ALTER_MERGE_SPEC in ln or base_name in ln), "")
        if not disp:
            err(f"加载调度器未登记 `{ALTER_MERGE_SPEC}`——该文件不会被加载、其条目实际失效"
                "（判据齐备但没有入口，执行者改 SQL 时走不到它）", "AGENTS_COMMON.adoc")
        else:
            # 四点识别特征缺任一即"该条永不触发加载"：`ALTER TABLE` 是改 DDL 的入口，
            # `.sql` 是"SQL 须独立成文件"，库名是"须带库名"，`INSERT` 是 DML 合并那条。
            # 只核**触发特征**（要写/改 SQL 语句时即命中）：`ALTER TABLE`/`.sql`/`INSERT`
            # 是"要写 SQL"这类触发面（保留），`库名` 是 sql.adoc 的条目本体取值
            # （"须带库名"），抄进调度器即第二真源，故去掉。
            for token in ("ALTER TABLE", ".sql", "INSERT"):
                if token not in disp:
                    err(f"加载调度器 `{ALTER_MERGE_SPEC}` 登记项缺少 `{token}` 识别特征——"
                        "触发特征不全时该条永不触发加载（改 SQL 的执行者会"
                        "「没想到这里还有可合并的一条」）", "AGENTS_COMMON.adoc")
    # 真源**须能从加载入口按路径取回**（本轮实测的失效形态：文件与登记都在，但登记里的
    # 路径取不回——`fetch-specs.py` 按 `specs/*.adoc` 解析入口里的路径来批量取副本，
    # 路径漂一个字符（层级写错、少一层目录）时站点回落成首页、取到的"说明文件"其实是 HTML，
    # 引用方读到的是死引用。判据即取回脚本用的那条正则，机械可核对）。
    if disp and not re.search(r"specs/[A-Za-z0-9_./-]+\.adoc", disp):
        err(f"加载调度器里的 `{ALTER_MERGE_SPEC}` 未写成可被取回脚本解析的仓库内路径"
            "（取回脚本按 `specs/….adoc` 解析入口清单）——副本取不回，引用方读到死引用",
            "AGENTS_COMMON.adoc")
    # 技术栈侧一跳引用：Java 项目读「跨语言执行脚本（SQL / Lua 等）」时须被指向真源
    java_path = os.path.join(REPO_ROOT, *ALTER_MERGE_JAVA_SPEC.split("/"))
    if not os.path.isfile(java_path):
        err(f"缺少 {ALTER_MERGE_JAVA_SPEC}——SQL 写法的 Java 落点丢失", ALTER_MERGE_JAVA_SPEC)
    else:
        with open(java_path, encoding="utf-8") as fh:
            jtext = fh.read()
        jsec = _section_text(jtext, ALTER_MERGE_JAVA_SECTION)
        if not jsec:
            err(f"{ALTER_MERGE_JAVA_SPEC} 缺少「{ALTER_MERGE_JAVA_SECTION}」节——"
                "Java 项目执行 SQL 时没有落点可循", ALTER_MERGE_JAVA_SPEC)
        elif ALTER_MERGE_SPEC not in jsec:
            err(f"{ALTER_MERGE_JAVA_SPEC}「{ALTER_MERGE_JAVA_SECTION}」未指向 `{ALTER_MERGE_SPEC}`"
                "——Java 项目读该节时不知道 SQL 写法另有真源（判据一处、其余一跳引用）",
                ALTER_MERGE_JAVA_SPEC)
        elif "src/main/resources/" not in jsec or ".sql" not in jsec:
            err(f"{ALTER_MERGE_JAVA_SPEC}「{ALTER_MERGE_JAVA_SECTION}」缺少 Java 落点"
                "（`.sql` 放 `src/main/resources/`）——引用到了真源，却没给 Java 怎么写",
                ALTER_MERGE_JAVA_SPEC)
    # 图书馆依据落点：依据须可逐字核对，且须如实标注"官方材料未规定必须合并"
    # （否则读者会把本集合的取舍当成 MySQL 的要求）。
    lib_path = os.path.join(REPO_ROOT, *ALTER_MERGE_LIBRARY.split("/"))
    if not os.path.isfile(lib_path):
        err(f"缺少 {ALTER_MERGE_LIBRARY}——正文里的 MySQL 官方文档依据无处逐字核对"
            "（依据只剩名称）", ALTER_MERGE_LIBRARY)
    else:
        with open(lib_path, encoding="utf-8") as fh:
            lib_text = fh.read()
        for name, tokens, why in ALTER_MERGE_LIBRARY_ANCHORS:
            for token in tokens:
                if token not in lib_text:
                    err(f"{ALTER_MERGE_LIBRARY} 缺少 `{name}` 的要点（应含 `{token}`）——{why}",
                        ALTER_MERGE_LIBRARY)
    phase_done()


def check_java_serial_guard():
    """『Java 序列化 / 局部变量推断 / 链式调用换行』防线：判据本体不得被删或降级。

    三处用户要求（本轮，见上方常量区的原文）共用一个性质：**它们要治的都是「留了裁量点」**——
    `serialVersionUID` 要不要加/加多少、`val` 与 `var` 哪个都行、链短就不换行。裁量点留给临场
    发挥时，同一项目里会并存两种形态、读代码的人无法预期（与「先例优先」同源）。

    故本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：
    只核「这三节在不在」属防线空转——把「不得为未实现者补字段」「用 `var` 却没重新赋值即违规」
    「长度不是判据」这些**可核对的那句话**抽走时照样全绿。逐条核 `JAVA_SERIAL_ANCHORS` /
    `JAVA_VAL_VAR_ANCHORS` / `CHAIN_CALL_ANCHORS`，并核三处依据行与调度器登记。
    「某个类该不该算『已实现 Serializable』」属语义判断，交人/子 agent 复核。
    """
    phase("Java 序列化 / 局部变量推断 / 链式换行防线检查")
    java_path = os.path.join(REPO_ROOT, *JAVA_SPEC.split("/"))
    if not os.path.isfile(java_path):
        err(f"缺少 {JAVA_SPEC}——「{JAVA_SERIAL_SECTION}」与局部变量推断的判据无处承载", JAVA_SPEC)
        phase_done()
        return
    with open(java_path, encoding="utf-8") as fh:
        java_text = fh.read()
    java_section = _section_text(java_text, JAVA_SERIAL_SECTION)
    if not java_section:
        err(f"{JAVA_SPEC} 缺少「{JAVA_SERIAL_SECTION}」小节——该条失去落点"
            "（未显式声明时 UID 由类结构推导、结构一变即 InvalidClassException）", JAVA_SPEC)
    else:
        for name, tokens, why in JAVA_SERIAL_ANCHORS:
            for token in tokens:
                if token not in java_section:
                    err(f"「{JAVA_SERIAL_SECTION}」缺少要点：{name}"
                        f"（应含 `{token}`）——{why}", JAVA_SPEC)
    for name, tokens, why in JAVA_VAL_VAR_ANCHORS:
        for token in tokens:
            if token not in java_text:
                err(f"{JAVA_SPEC}「编码」缺少要点：{name}（应含 `{token}`）——{why}", JAVA_SPEC)

    coding_path = os.path.join(REPO_ROOT, *CODING_SPEC.split("/"))
    if not os.path.isfile(coding_path):
        err(f"缺少 {CODING_SPEC}——「链式调用一律换行」的判据无处承载", CODING_SPEC)
    else:
        with open(coding_path, encoding="utf-8") as fh:
            coding_text = fh.read()
        for name, tokens, why in CHAIN_CALL_ANCHORS:
            for token in tokens:
                if token not in coding_text:
                    err(f"{CODING_SPEC}「表达式与调用写法」缺少要点：{name}"
                        f"（应含 `{token}`）——{why}", CODING_SPEC)

    # 调度器：三条都必须能被触发加载（缺识别特征＝永不加载、规则实际失效）
    rel_common = "AGENTS_COMMON.adoc"
    common_path = os.path.join(REPO_ROOT, *rel_common.split("/"))
    if not os.path.isfile(common_path):
        err(f"缺少 {rel_common}——三条规则的加载触发特征无处登记", rel_common)
    else:
        common_text = open(common_path, encoding="utf-8").read()
        # 这里**只核识别特征**（触发该条所需的字样），不要求把条目本体的判据正文
        # 抄进调度器——调度器抄正文即第二真源（`terminology.adoc`「数据字典」的反膨胀）。
        # 原先逐字要求 `链式调用一律换行`、`优先 `val`、可变才 `var`` 都是**条目本体的取值**，
        # 已按同口径放宽为「命中该主题所需的最短特征」：`链式调用`、`val`/`var`。
        for token, why in (
            ("链式调用", "通用层条目缺该识别特征时，写非 Java 项目代码也不会加载本条"
                         "（用户明确要求『所有语言』）"),
            ("serialVersionUID", "Java 栈条目缺该识别特征时，该条永远不会被触发加载"),
            ("`val`", "Java 栈条目缺该识别特征时，局部变量推断口径不会被加载"),
            ("`var`", "Java 栈条目缺该识别特征时，局部变量推断口径不会被加载"),
        ):
            if token not in common_text:
                err(f"Java 序列化防线被破坏：{rel_common} 缺 `{token}`——{why}", rel_common)

    # 图书馆：依据须有可逐字核对的落点（否则「依据只存名称」）
    for rel, tokens in (
        ("library/sources.adoc",
         ("Java Object Serialization Specification", "`java.io.Serial`", "同义性", "未逐字取回")),
        ("library/adoption.adoc",
         ("serialVersionUID", "本集合自己的判据化取舍", "没实现不自动加 Serializable 实现")),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少 {rel}——本轮三条取舍的依据无处核对", rel)
            continue
        text = open(path, encoding="utf-8").read()
        missing = [t for t in tokens if t not in text]
        if missing:
            err(f"Java 序列化防线被破坏：{rel} 缺少要点 {missing}——"
                "依据只存名称时，日后无从核对『它今天还成立吗』", rel)
    phase_done()


# AsciiDoc 处理器的两个实现（按次序探测；**探测不到即报错，不跳过**）：
#   ① `asciidoctor`（Ruby 实现）——支持 `--failure-level=WARN`，WARNING 也能返回非 0；
#   ② `asciidoc`（Python 实现，PyPI 包名 `asciidoc`）——**无 `--failure-level`**（传了会
#      `illegal command options`），缺 `include::` 目标时只 WARNING、仍返回 0，
#      故这条效力边界须显式记下（本仓库实测），不得假装它能拦 WARNING。
# 两个实现都探测不到时**报错**：语法验证是"确定项"（文件能否编译、include 目标在不在，
# 二值可判），跳过它等于把已声明的校验手段变成摆设——用户口径：**不得省略**。
# 空串是"未指定"：默认取仓库根（REPO_ROOT 现场推导，见 _detect_asciidoc_processor）。
ASCIIDOC_PROCESSORS = _RULES_TOKENS["ASCIIDOC_PROCESSORS"]
ADOC_ROOTS = _RULES_TOKENS["ADOC_ROOTS"]


def _collect_adoc_files(root_dir):
    """收集 `root_dir` 下的全部 `.adoc`（递归 + 仓库/目录根），返回**该根相对** POSIX 路径。

    单一实现：`collect_adoc_files` 用仓库根调用、语法编译段用 `ADOC_ROOTS` 里的每个根
    调用——两处若各写一份"哪些目录算维护范围"，改一处必漏另一处。
    """
    result = []
    root_dir = os.path.abspath(root_dir)
    for sub in ("specs", "specs-project-maintainer", "library", "prompts"):
        for dirpath, _, files in os.walk(os.path.join(root_dir, sub)):
            for f in files:
                if f.endswith(".adoc"):
                    result.append(os.path.join(dirpath, f))
    if os.path.isdir(root_dir):
        for f in sorted(os.listdir(root_dir)):
            if f.endswith(".adoc"):
                result.append(os.path.join(root_dir, f))
    return [os.path.relpath(f, root_dir).replace("\\", "/") for f in result]




def _detect_asciidoc_processor():
    """探测本机的 AsciiDoc 处理器，返回 (命令名, 可执行路径) 或 (None, None)。

    探测次序由 `ASCIIDOC_PROCESSORS` 给定（先 Ruby 的 `asciidoctor`、再 Python 的
    `asciidoc`）——**两个都按"命令能否在 PATH 里找到"判**，不按包名/版本猜。
    """
    for cmd in ASCIIDOC_PROCESSORS:
        found = shutil.which(cmd)
        if found:
            return cmd, found
    return None, None


def _adoc_compile_cmd(proc, path, exe=None):
    """拼一次语法编译的命令行；`--failure-level=WARN` 只发给认它的 `asciidoctor`。

    Ruby 版 `asciidoctor` **默认对 WARNING/ERROR 仍返回 0**，故必须显式带
    `--failure-level=WARN`，否则 `include::` 目标缺失、`image::` 找不到这类"只告警不报错"
    的问题必然漏报、防线形同虚设。Python 版 `asciidoc`（PyPI）**没有**这个开关（实测传了
    整批命令都会以 `illegal command options` 失败），故对它**不发**并如实把效力降级告警。

    `exe`＝探测器给到的**可执行文件路径**（形参给默认值只为兼容既有调用）。Windows 上
    RubyInstaller 的 gem 入口是 **`.bat`/`.cmd` 外壳**，`CreateProcess` **不能直接执行**它
    ——本轮实测：本机装上 Ruby 版 `asciidoctor` 后，语法段整段抛
    `FileNotFoundError: [WinError 2] 系统找不到指定的文件`（连"缺工具"那条报错都走不到，
    因为探测器确实找到了它）。故这类外壳一律经 `cmd /c` 调用；非 Windows 或直接可执行的
    路径照旧按 argv 调。
    """
    if proc == "asciidoctor":
        args = ["--failure-level=WARN", "-o", "-", path]
    else:
        args = ["-o", "-", path]
    target = exe or proc
    if os.name == "nt" and target.lower().endswith((".bat", ".cmd")):
        return ["cmd", "/c", target, *args]
    return [target, *args]


def _adoc_env():
    """跑 AsciiDoc 处理器时的子进程环境：**统一按 UTF-8 收发**，不随本机 locale 变。

    为什么需要它（本轮实测）：本仓库全部 `.adoc` 是 UTF-8，而处理器**按本机默认编码读
    文件**——在中文 Windows（默认 GBK）上，Python 版 `asciidoc` 一遇到非 ASCII 内容就抛
    解码异常、以 `unexpected error` 退出。**这不是文档的问题，却会一次刷出十几条
    "语法/告警"报红**（实测：59 份里 10 份报这种红；同一批文件设 `PYTHONUTF8=1` 后
    59 份全部编译通过）。判据是"文件能否编译"，不该随执行者的机器变，故由脚本统一给定。

    同时给父进程侧的解码：`subprocess.run(..., encoding="utf-8")`——否则子进程写回的
    中文会被父进程按 GBK 解、报 `UnicodeDecodeError`（与前面 NPC 那道防线踩过的是同一个坑）。

    边界：只解决"编码"这一半，**不改处理器、不改本仓库声明的运行环境**；也**不掩盖**
    真实语法问题——编码正确后仍编译不过的文件照样报红。
    """
    env = dict(os.environ)
    env["PYTHONUTF8"] = "1"
    env["PYTHONIOENCODING"] = "utf-8"
    return env


# CI 步骤里"执行了哪条命令"的判据用语：`run:` 的内容（含 `|`/`>` 块）与
# `uses:` 的 action 名。步骤名不计入——名字里写 `gem install asciidoctor` 而步骤实际
# 跑的是 `echo skip` 时，按"整段文本包含关键字"判会假绿（名字比命令更容易写）。
_WF_RUN_KEY = re.compile(r"^\s*(?:-\s+)?run:\s*(.*)$")
_WF_USES_KEY = re.compile(r"^\s*(?:-\s+)?uses:\s*(\S+)\s*$")
# YAML 块标量的续行判定：`run: |` / `run: >` / `run: |-` 及其它 `|`/`>` 变体。
# AsciiDoc 文档里会有大量 `|` 表格行，故**只在"步骤内的 run 键之后"调用本函数**。
_WF_BLOCK_SCALAR = re.compile(r"^[|>][+-]?\d*\s*$")


def _workflow_runs(text):
    """从 workflow 文本里取**每步实际执行的命令**，返回 `[步骤名, 命令…]` 的列表。

    形态判据（不是"整段文本里出现过某个词"）：
      * 只取 `run:` 键的值（含 `|`/`>` 块标量的续行）与 `uses:` 的 action 名——
        **步骤名 `name:` 不计**（名字比命令更容易写，按名字判会把"名字里写了安装命令、
        实际什么都不装"判成装过了）；
      * 块标量的续行由"缩进比 run 键更深"判定，遇到同缩进或更浅的行即结束；
      * 步骤仍按 `- ` 起行切分，缩进深浅（列表项内联键 / `- name:` 后换行写键）都收。
    """
    steps, cur, key_indent = [], None, None
    for raw in text.split("\n"):
        if raw.lstrip().startswith("#"):
            continue                      # 注释不参与（注释里写命令不算执行了它）
        stripped = raw.strip()
        m_key = _WF_RUN_KEY.match(raw)
        m_uses = _WF_USES_KEY.match(raw)
        if m_key or m_uses:
            if cur is None and (m_key or m_uses):
                cur = []
            if cur is None:
                continue
            key_indent = len(raw) - len(raw.lstrip(" "))
            value = (m_key.group(1) if m_key else m_uses.group(1)).strip()
            if m_uses:
                cur.append(value)
                key_indent = None
                continue
            if _WF_BLOCK_SCALAR.match(value):
                key_indent = key_indent + 1  # 块体只在"比键更深"的缩进里
                continue
            if value:
                cur.append(value)
            key_indent = None
            continue
        if key_indent is not None:
            # 正在收集块标量：缩进比键更深的行是块体，否则块结束
            if stripped and (len(raw) - len(raw.lstrip(" "))) >= key_indent:
                cur.append(stripped)
                continue
            key_indent = None
        if stripped.startswith("- ") or stripped == "-":
            if cur:
                steps.append(cur)
            cur = []
    if cur:
        steps.append(cur)
    return steps


def check_toolchain_present_guard():
    """『校验工具链齐备防线』：校验手段依赖的工具须装齐、**不得因缺工具而静默跳过**。

    实证失效（本仓库）：`script/check_specs.py` 里写着 AsciiDoc 语法编译段，但本环境
    长期没有 `asciidoctor`，该段于是走"跳过"分支、脚本始终报 OK——**声明的校验手段
    从未执行，而输出看起来是绿的**。用户口径：**没有环境就要安装环境，不得省略**。

    故本条钉住三处落点（缺一即"工具链要求"只活在某一份文件里）：
      ① `specs/general/ci-cd.adoc`「校验链完整（定义未执行防线）」的条文本体与 L1 标注、
         **判定标准**（可逐条核对：跑之前先探测工具、缺则装齐，装不上如实标"未执行 +
         原因"、不得记作通过）、**安装方式**（含本仓库要用的处理器与命令）；
      ② `AGENTS.adoc` 的本仓库落点：点名 `check_asciidoctor_syntax`、处理器探测次序、
         **缺工具即报错**与安装命令；
      ③ `.github/workflows/check-specs.yml` 的安装步骤与**装后校验**（`asciidoctor --version`）。
    安装步骤被删或只"装"不校验时，CI 会退回"缺工具也绿"；文本一条不落时，下一位
    执行者才知道该装什么。
    """
    phase("校验工具链齐备防线检查")
    # ① 公共规范：条文本体 + L1 + 判定标准 + 安装方式 + 探测次序
    rel_ci = "specs/general/ci-cd.adoc"
    ci_path = os.path.join(REPO_ROOT, *rel_ci.split("/"))
    if not os.path.isfile(ci_path):
        err(f"缺少 {rel_ci}——校验工具链齐备的要求失去公共落点", rel_ci)
    else:
        with open(ci_path, encoding="utf-8") as fh:
            ci = fh.read()
        run_rule_guard("check_toolchain_present_guard")
    # ② 本仓库落点：AGENTS.adoc 须点名脚本、探测次序与安装命令
    rel_own = "AGENTS.adoc"
    own_path = os.path.join(REPO_ROOT, *rel_own.split("/"))
    if not os.path.isfile(own_path):
        err(f"缺少 {rel_own}——校验工具链要求失去本仓库落点", rel_own)
    else:
        with open(own_path, encoding="utf-8") as fh:
            own = fh.read()
        run_rule_guard("check_toolchain_present_guard")
    # ③ CI：安装步骤 + **装后校验**（只"装"不校验时，装失败仍会退回"缺工具也绿"）。
    # 判据按**每步实际执行的命令**取值（见 `_workflow_runs`）：教程式注释、步骤名、
    # 排在安装之前的版本输处、以及"装与校验分成两步"都会被拦下——这几种形态下
    # 装失败都不会让 action 失败，等于 CI 上又有了第二条"跳过"路径。
    rel_wf = ".github/workflows/check-specs.yml"
    wf_path = os.path.join(REPO_ROOT, *rel_wf.split("/"))
    if not os.path.isfile(wf_path):
        err(f"缺少 {rel_wf}——校验工具链在 CI 侧的落点丢失", rel_wf)
    else:
        with open(wf_path, encoding="utf-8") as fh:
            wf = fh.read()
        steps = _workflow_runs(wf)
        install_at = next((i for i, cmd in enumerate(steps)
                           if any("install" in line and proc in line
                                  for line in cmd for proc in ASCIIDOC_PROCESSORS)),
                          None)
        # 装后校验：真调用处理器（`--version` / `--help` 两类"证明它在"的调用），
        # 且**必须与安装同一步**——分成两步时，第二步失败后后续步骤照跑，装失败仍会绿。
        verify_at = None
        if install_at is not None:
            for line in steps[install_at]:
                parts = line.split()
                if parts and parts[0] in ASCIIDOC_PROCESSORS \
                        and any(a in ("--version", "--help", "-v", "-h") for a in parts[1:]):
                    verify_at = install_at
                    break
        if install_at is None:
            err(f"校验工具链齐备防线被破坏：{rel_wf} 没有**安装步骤**"
                f"（须有一条实际执行 `install` 且点名处理器的命令：{ASCIIDOC_PROCESSORS}）"
                "——缺则语法段在 CI 上同样走不到；只写在注释或步骤名里不算执行了它",
                rel_wf)
        elif verify_at is None:
            err(f"校验工具链齐备防线被破坏：{rel_wf} 的安装步骤里没有**装后校验**"
                "（须在同一步骤内真的调用处理器，如 `asciidoctor --version`）——"
                "只『装』不调用时装失败静默通过；调用若被拆到另一步，该步失败后"
                "后续步骤照跑、CI 仍会绿（两种都等于留了第二条跳过路径）", rel_wf)
    phase_done()


def check_asciidoctor_stub_guard():
    """『AsciiDoc 语法段不得只剩壳』：脚本里那个编译段必须真的编译，且 CI 必须真的跑它。

    为什么单靠 `check_toolchain_present_guard` 不够（**本轮 main 上实测的绕过路径**）：
    那道防线钉的是"探测不到处理器即报错"这段**代码**（`_asciidoc_processor` 探测 + 缺
    即 `err()`）与 CI 的安装步骤**文本**；但**"真的编译过每一份 .adoc"这件事本身**
    没有任何 CI 级断言——实测：把 `check_asciidoctor_syntax` 的函数体换成
    `phase(...); phase_done(); return 0`（既不探测、也不编译），
    `check_specs.py` **仍然报 OK**（那一节写着"✓ 完成"），`check_toolchain_present_guard`
    照样全绿（探测代码不在这个函数里），CI 里也没有任何步骤去核对"这次到底编了几份、
    有没有一份报错"。于是**声明的校验手段变成了壳**，而台账上仍写着"有抓手"。

    故本条把两件事变成可核对的（都在 CI 里、纯本地、幂等）：
      ① 脚本里 `check_asciidoctor_syntax` 的**函数体**须真的（a）探测处理器、
         （b）缺处理器即 `err(`、（c）对 `ADOC_ROOTS` 收集到的文件逐个真的调用处理器；
         三者缺一即报红（"只剩壳"的三种形态：不探测 / 探测了但缺工具只告警 / 探测后不编译）。
      ② CI 里须有一条**真的执行了** `python3 script/check_specs.py` 的命令——语法段挂在
         这个脚本里，脚本不被 CI 调用时，上面三条再全也只是"写在文件里"。
         判据按**每步实际执行的命令**取值（见 `_workflow_runs`），不看步骤名与注释。

    力所不及（如实记下、交人/子 agent）：**"某次 CI 里那 N 份 .adoc 真的都被编译了"
    属运行时事实**，本仓库不可见（脚本输出被 `phase()` 折叠成一行"✓ 完成"）——
    这里只能证明"编译这件事的代码还在、且 CI 会跑到它"。要更强的留证须让 `check_specs.py`
    把编译份数打出来并断言，属另一件事（本轮未做）。
    """
    phase("AsciiDoc 语法段不得只剩壳检查")
    src = _read_script_src("script/check_specs.py")
    if src is None:
        err("缺失 script/check_specs.py——AsciiDoc 语法段本体不在，无从核对",
            "script/check_specs.py")
        phase_done()
        return
    body = _module_level_fn_body(src, "check_asciidoctor_syntax")
    if not body:
        err("script/check_specs.py 里找不到模块级函数 `check_asciidoctor_syntax`——"
            "AsciiDoc 语法编译验证这一道手段整个不见了（`CHECKS` 序列里仍点名它时，"
            "脚本会在运行到它时直接抛 `NameError`；若连序列也一起删了，则没有任何判据"
            "会报『语法验证没了』）", "script/check_specs.py")
    else:
        if "_detect_asciidoc_processor(" not in body:
            err("`check_asciidoctor_syntax` 的函数体里**没有探测处理器**——"
                "不探测就没有『缺工具即报错』这条路径，语法段会静默变成空转"
                "（本仓库实测：整段换成 `phase(...); phase_done(); return 0` 后 "
                "`check_specs.py` 仍报 OK）", "script/check_specs.py")
        if "err(" not in body:
            err("`check_asciidoctor_syntax` 的函数体里**没有 `err(`**——缺工具或编译失败时"
                "不再报红，这一节无论编没编成功都会显示『✓ 完成』",
                "script/check_specs.py")
        if "_collect_adoc_files(" not in body or "_adoc_compile_cmd(" not in body:
            err("`check_asciidoctor_syntax` 的函数体里**没有真的逐个编译**"
                "（须同时出现 `_collect_adoc_files(` 与 `_adoc_compile_cmd(`）——"
                "收集规则与编译命令两处都不可省：少了前者就不知道编哪些文件、"
                "少了后者就没真的调处理器（本仓库实测的『只剩壳』形态）",
                "script/check_specs.py")
        if "ADOC_ROOTS" not in body:
            err("`check_asciidoctor_syntax` 的函数体里**没有按 `ADOC_ROOTS` 覆盖全部维护根**"
                "——只编仓库根时，被点名的子树一份都不会被真的编译，而检查照样显示完成",
                "script/check_specs.py")

    rel_wf = ".github/workflows/check-specs.yml"
    wf_path = os.path.join(REPO_ROOT, *rel_wf.split("/"))
    if not os.path.isfile(wf_path):
        err(f"缺少 {rel_wf}——AsciiDoc 语法段在 CI 侧的落点丢失（脚本再对也没人跑它）", rel_wf)
    else:
        with open(wf_path, encoding="utf-8") as fh:
            wf = fh.read()
        steps = _workflow_runs(wf)
        runs_check = any(
            any("check_specs.py" in line for line in cmd) for cmd in steps)
        if not runs_check:
            err(f"校验手段变成摆设：{rel_wf} 里**没有任何一步真的执行 **`script/check_specs.py`**"
                "——AsciiDoc 语法编译段挂在这个脚本里，脚本不被 CI 跑到时，"
                "『探测处理器 + 缺即报错 + 逐个编译』三条再全也只是写在文件里"
                "（本仓库实测的绕过形态：CI 步骤名仍写着 AsciiDoc，命令却换成了 `echo`）",
                rel_wf)
    phase_done()


def check_asciidoctor_syntax():
    """AsciiDoc 语法编译验证：**环境缺工具即报错，不得跳过**。

    效力：把"本仓库维护范围内的全部 `.adoc`"逐份编译一次，编译失败即报错——
    这是**确定项**（文件能否编译、`include::` 目标在不在，二值可判），故不设
    "环境没有就跳过"的旁路（用户口径：没有环境就要安装环境，不得省略）。

    工具探测与效力边界：
      * `asciidoctor`（Ruby）：带 `--failure-level=WARN`，WARNING（含 `include::`
        目标缺失）也返回非 0；
      * `asciidoc`（Python 实现）：**没有** `--failure-level`，缺 `include::` 目标时
        只 WARNING、仍返回 0——故这一半效力降级，但"编译是否失败"仍被真正拦住；
      * **两个都没有 → 报错**：安装方式见 `.github/workflows/check-specs.yml`
        与 `specs/general/ci-cd.adoc`「校验链完整（定义未执行防线）」。
    """
    phase("AsciiDoc 语法编译验证")
    proc, proc_path = _detect_asciidoc_processor()
    if proc is None:
        err("本机探测不到任何 AsciiDoc 处理器（按次序试过 "
            + "、".join(f"`{c}`" for c in ASCIIDOC_PROCESSORS) + "）——"
            "语法编译验证是**确定项**、不得跳过：请先装齐工具再跑本脚本"
            "（Ruby：`gem install asciidoctor`；只需 Python 时：`pip install asciidoc`；"
            "CI 的安装步骤见 `.github/workflows/check-specs.yml`）",
            "script/check_specs.py")
        phase_done()
        return
    detail(f"  处理器: {proc}（{proc_path}）")
    if proc != "asciidoctor":
        log(f"  警告: 本机处理器是 `{proc}`（Python 实现），它不支持 `--failure-level`，"
            "WARNING 级问题（含 `include::` 目标缺失）本次无法拦截；"
            "要拦住这一半请改装有 `--failure-level` 的 `asciidoctor`（Ruby 实现，>= 1.5.7）")
    # 覆盖**全部维护根**（`ADOC_ROOTS`，默认仓库根）：只编仓库根时，被点名的子树
    # （独立的规范集合/产物目录）一份都不会被真的编译，而检查照样显示"完成"。
    files = []
    for root in ADOC_ROOTS:
        root_dir = os.path.join(REPO_ROOT, *root.split("/")) if root else REPO_ROOT
        if not os.path.isdir(root_dir):
            err(f"ADOC_ROOTS 点名的根不存在：{root or '.'}——语法编译验证的覆盖范围"
                "不能停在不存在的位置（等于该子树一份都没编）", "script/check_specs.py")
            continue
        files.extend([os.path.join(root, rel) if root else rel
                      for rel in _collect_adoc_files(root_dir)])
    for i, rel in enumerate(files, 1):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        detail(f"  [{i}/{len(files)}] 检查 {rel}")
        try:
            r = subprocess.run(_adoc_compile_cmd(proc, path, proc_path),
                               capture_output=True, text=True, timeout=30,
                               encoding="utf-8", errors="replace", env=_adoc_env())
        except subprocess.TimeoutExpired:
            err(f"{proc} 超时 (30s)，文件可能过大或处理器卡死: {rel}")
            continue
        if r.returncode != 0:
            err(f"{proc} 语法/告警: {r.stderr.strip()}", rel)
    phase_done()


def _is_dir_ref(ref: str) -> bool:
    """判断一个引用是否为**目录型引用**（以 `/` 结尾，如 `specs/`、`script/`）。

    目录型引用**不再整体跳过**——它有确定的判据（该目录是否存在），跳过会让
    "目录被改名/删除后引用悬空"完全无人发现（原实现把目录型与占位符混为一类跳过，
    等于把"可能误报"换成了"必然漏报"）。存在性由 check_refs_exist / check_library_guard
    按 os.path.isdir 核对。
    """
    return ref.endswith("/")


def _is_placeholder_ref(ref: str) -> bool:
    """判断一个引用是否为**占位符/示例**（非真实具体文件，无法核对存在性）。

    只含真正的占位形态：`...` 省略、**通配**（`*`/`**`，如 `specs/*.adoc`、`specs/**`）、
    `<...>` 尖括号占位。**目录型引用（`specs/`）不在此列**——见 _is_dir_ref（它有确定的判据）。

    **通配算占位（本轮修）**：`specs/*.adoc` 这类**通配清单**不是具体路径，存在性无从核对
    （拿它去 `os.path.isfile` 必然为假）。本仓库实证：`guards.adoc` 里写"登记路径须能被取回
    脚本的 `specs/*.adoc` 清单解析命中"，被 `check_refs_exist` 报成"引用了不存在的文件"，
    于是这条**假红长期留在本仓库**（本机跑一次就报一次）；改正那句措辞只是把一句**真实存在
    的**规则描述改掉，问题会在下一个提到通配的地方重现——故在判据侧修：通配不是具体引用。
    """
    return (ref.endswith("...")
            or "*" in ref                  # 通配（`*`/`**`）：不是具体路径，存在性无从核对
            or "<" in ref or ">" in ref)


def _ref_base(f: str) -> str:
    """某规范文件内 `link:` 引用的解析基准（相对仓库根目录，根文件为空串）。

    **基准口径与渲染者一致（单一说明，不留第二套说法）**：本仓库的 `.adoc` 由站点
    `index.html` 用 **Asciidoctor.js（浏览器端现渲染）** 渲染，其 `link:` 目标按
    **文档源所在目录**解析。站点渲染的文档在**仓库根**，故 `link:` 相对仓库根解析——
    即 `link:AGENTS_COMMON.adoc[]` 在站点上解析为 `/AGENTS_COMMON.adoc`（仓库根的该入口）。
    本函数对**仓库根文件**返回空串（基准=仓库根）正是为与之一致。

    为何"根文件约定按仓库根书写"：AsciiDoc 的 `link:` 没有"仓库根"概念，只有"文档
    所在目录"；对位于仓库根的文件两者恰好等价（`../` 会越出仓库根、无法表达"根级
    相对"），故根级跨文件引用统一按仓库根基准书写。**其余文件**（`specs/`、`library/`
    等）按其所在目录解析（与 IDE/浏览器相对语义一致）；图书馆内的引用由
    `_lib_resolve` 按"仓库根优先、再本文件目录"解析，与本节同为**仓库根基准**。

    记录性风险（已随本节说明消解）：若有人把此处的基准“修正”成"一律按本文件目录"，
    会去把 `README.adoc` 里的根级 `link:` 改成 `../` 形态——那反而把**站点上的链接**
    弄死（站点渲染的文档就在仓库根，`../` 会越出站点根）。故改动基准前须先改渲染者。
    """
    if os.path.isabs(f):
        rel = _rel_of(f)  # 绝对路径 → 仓库根相对
    elif os.path.dirname(f) == "":
        rel = f  # 已是仓库根相对形式（collect_adoc_files 的返回值）
    else:
        # 既非绝对、也非仓库根相对：按"相对 REPO_ROOT"解释（调用方偶有这种写法）
        rel = _rel_of(os.path.join(REPO_ROOT, f))
    d = os.path.dirname(rel)
    if d in ("", "."):
        return ""  # 仓库根文件：引用按从仓库根开始的路径解析
    return d.replace("\\", "/")


def extract_specs_refs(text: str, base_dir: str = ""):
    """提取文中所有指向仓库内具体文件的引用，归一化为从仓库根开始的相对路径。

    `base_dir` 为当前文件所在目录（相对仓库根，POSIX 分隔，根文件为空串），用于
    解析 link: 的相对目标。兼容两类写法：

      * 反引号包裹：`` `specs/general/coding.adoc` `` / `` `specs-project-maintainer/priority.adoc` ``
        ——按**从仓库根开始**的相对路径解析（AGENTS_COMMON.adoc 加载调度 / 正文里惯例用这种写法）。
      * AsciiDoc 超链接：`link:xxx[]`——按**相对当前文件所在目录**解析（IDE 与
        浏览器相对语义一致），目标可能是 `../general/x.adoc` 等含 `../` 的形式。

    排除：占位符、外部 scheme 链接、页内锚点、根绝对路径及越出仓库根的相对路径。
    **目录型引用（以 `/` 结尾）保留**（不是"排除"）：它由调用方按 os.path.isdir 核对
    存在性——原实现把目录型一并跳过，导致 `link:../script/[]` 这类目录被改名后无人发现。
    """
    refs = []
    # 反引号：根目录相对（含目录型 `specs/`、`script/`；占位形态除外）
    for r in re.findall(r"`((?:specs(?:-project)?|library|script|prompts)/[^`\s]*)`", text):
        if _is_placeholder_ref(r):
            continue
        refs.append(r)
    # link:：相对当前文件目录
    for raw in re.findall(r"\blink:([^\[]+)\[", text):
        t = raw.strip()
        if not t or t.startswith("#"):
            continue
        if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", t):  # 外部 scheme 链接
            continue
        if t.startswith("/"):  # 根绝对路径，格式检查单独报告，此处不参与存在性
            continue
        is_dir = t.endswith("/")
        resolved = posixpath.normpath(posixpath.join(base_dir, t))
        if resolved == ".." or resolved.startswith("../"):
            continue  # 越出仓库根，格式检查单独报告
        if _is_placeholder_ref(resolved):
            continue
        if is_dir and not resolved.endswith("/"):
            resolved += "/"  # 保留目录型标记，供调用方按目录核对
        refs.append(resolved)
    # 去重并保持顺序
    seen, out = set(), []
    for r in refs:
        if r not in seen:
            seen.add(r)
            out.append(r)
    return out


def check_refs_exist():
    """校验所有 spec 文件（含 AGENTS_COMMON.adoc）中的 `specs/...` 引用真实存在。

    覆盖两类引用：
      * AGENTS_COMMON.adoc 加载调度器登记/引用的文件；
      * 各 spec 文件之间互相引用的文件（此前只查 AGENTS_COMMON.adoc，
        会漏掉 spec 间交叉引用悬空，如 java-testing.adoc 引用已不存在的
        specs/stack/testing.adoc）。
    """
    phase("引用文件存在性检查")
    files = collect_adoc_files()
    for i, rel in enumerate(files, 1):
        base = _ref_base(rel)
        detail(f"  [{i}/{len(files)}] 检查 {rel}")
        if _is_historical(rel):
            continue  # 变更历史按定义保留旧路径，存在性检查对它不适用
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            text = fh.read()
        refs = extract_specs_refs(text, base)
        for ref in refs:
            # 维护方自查层（specs-project-maintainer/）不是公共入口的加载项：
            # 其中指向 `specs/` 的引用在引用方可能不存在（引用方并未引入这些文件），
            # 属设计预期而非悬空；故只校验其指向本层自身的引用（见 check_dispatcher_registry
            # 的登记口径）。这些文件**在本仓库内**的引用仍由 check_link_refs /
            # check_section_refs 逐条核对。
            if rel.startswith("specs-project-maintainer" + os.sep) \
                    and not ref.startswith("specs-project-maintainer/"):
                continue
            # 图书馆（仓库根 library/，不在默认引用面内）引用公共内容/维护方落点属正常，
            # 反向引用（公共内容引用图书馆）已由 check_public_content_is_self_contained
            # 拦下；故图书馆自身的非 library 引用不在此重复报错。
            if rel.startswith("library" + os.sep) \
                    and not ref.startswith("library/"):
                continue
            if _is_dir_ref(ref):
                # 目录型引用：核对**目录**是否存在（不再整体跳过——目录被改名/删除
                # 同样是引用悬空，且原实现正因跳过而对它完全无覆盖）
                d = os.path.join(REPO_ROOT, *ref.rstrip("/").split("/"))
                if not os.path.isdir(d):
                    err(f"引用了不存在的目录: {ref}", rel)
                continue
            target = os.path.join(REPO_ROOT, *ref.split("/"))
            if not os.path.isfile(target):
                err(f"引用了不存在的文件: {ref}", rel)
            else:
                # 检查被引用文件是否真的存在且可读
                try:
                    open(target, encoding="utf-8").close()
                except Exception as e:  # noqa
                    err(f"文件无法读取: {ref} ({e})", rel)
    phase_done()


def check_stack_consistency():
    """AGENTS_COMMON.adoc 技术栈层登记 vs specs/stack/ 实际文件，双向一致。"""
    phase("技术栈一致性检查")
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        text = fh.read()
    # 提取登记的技术栈文件：specs/stack/xxx.adoc（AGENTS_COMMON.adoc 内部 specs/... 从仓库根解析，base_dir=""）
    registered = set(extract_specs_refs(text, ""))
    registered_stack = {r for r in registered
                        if r.startswith("specs/stack/") and not r.endswith("/")}

    actual = set()
    stack_dir = os.path.join(SPECS_DIR, "stack")
    if os.path.isdir(stack_dir):
        for f in os.listdir(stack_dir):
            if f.endswith(".adoc"):
                actual.add(f"specs/stack/{f}")

    log(f"  已登记: {len(registered_stack)} 个, 实际存在: {len(actual)} 个")

    # 登记了但不存在（已被上一项覆盖，这里再明确提示栈语义）
    for r in registered_stack - actual:
        err(f"技术栈层登记了不存在的栈文件: {r}", "AGENTS_COMMON.adoc")
    # 实际存在但未登记（防止漏加载）
    for a in actual - registered_stack:
        err(f"specs/stack/ 存在但未在技术栈层登记（可能漏加载）: {a}", "AGENTS_COMMON.adoc")
    phase_done()


def check_dispatcher_layers():
    """『加载调度器分层结构防线』：五个加载层（+项目自身维护层）的层头与各自条目不得被删。

"""
    phase("加载调度器分层结构检查")
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        text = fh.read()
    m = re.search(r"== 分类与懒加载（加载调度器）(.*?)== 技术栈扩展约定", text, re.S)
    if m is None:
        err("AGENTS_COMMON.adoc 未找到「分类与懒加载（加载调度器）」节——"
            "分层结构防线失去抓手", "AGENTS_COMMON.adoc")
        phase_done()
        return
    sec = m.group(1)
    lines = sec.splitlines()
    # 层头 → 下一层头之间的条目须 ≥ 1
    for layer in ("必加载层", "通用层", "技术栈层", "项目类型层", "平台层", "维护方层"):
        pat = re.compile(r"^=== " + re.escape(layer) + r"[（(]")
        idx = next((i for i, ln in enumerate(lines) if pat.match(ln)), None)
        if idx is None:
            err(f"加载调度器缺失「{layer}」层头行（形如 `=== {layer}（…）`）——"
                "层头定义该层的加载触发语义（涉及即加载 / 具备该技术特征 / 按平台），"
                "层头被吞掉后其条目会挂到上一层、触发条件随之出错（本仓库实证）",
                "AGENTS_COMMON.adoc")
            continue
        # 该层的条目数：从层头下一行起，到下一个同级层头或节尾
        count = 0
        for ln in lines[idx + 1:]:
            if re.match(r"^=== ", ln):
                break
            if ln.startswith("* "):
                count += 1
        if count == 0:
            err(f"加载调度器「{layer}」层头下没有任何条目（空壳层头）——"
                "要么补条目、要么删掉空层头", "AGENTS_COMMON.adoc")
    phase_done()


def check_dispatcher_registry():
    """调度器登记完整性：被引用的规范文件必须都在调度器中登记。

"""
    phase("调度器登记完整性检查")
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        registered = set(extract_specs_refs(fh.read(), ""))
    referenced = set()
    for rel in collect_adoc_files():
        # 只统计**公共规范内容**（`AGENTS_COMMON.adoc` + `specs/`）内部文件的引用：
        # 调度器是公共规范内容的登记处。非公共入口登记的落点（`specs-project-maintainer/`、
        # 根 `library/`、`PUBLIC.adoc`、根 `README.adoc`/`PROMPTS.adoc`/`CHANGELOG.adoc`、
        # `prompts/`）**不在公共内容里、也不由公共调度器登记**（各由 `AGENTS.adoc` 登记），
        # 把它们的引用算进来即为误报。
        if rel != "AGENTS_COMMON.adoc" and not rel.startswith("specs/"):
            continue
        base = _ref_base(rel)
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            referenced |= set(extract_specs_refs(fh.read(), base))
    # 只核对**公共规范内容**（`specs/`）的目标：非 `specs/` 的引用（根文档、`prompts/`、
    # `library/` 等）不由公共调度器登记，报"未登记"即为误报。`specs-project-maintainer/`
    # 虽在 `specs-project/…` 命名空间之外，但其 §登记由 AGENTS.adoc 单独承担，此处一并排除。
    non_public = ("specs-project-maintainer/", "library/")
    missing = sorted(r for r in referenced - registered
                     if r.startswith("specs/")
                     and not r.endswith("/")   # 目录型引用不是"待登记文件"
                     and not r.startswith(non_public))
    log(f"  调度器登记 {len(registered)} 个, 被引用 {len(referenced)} 个")
    for m in missing:
        err(f"规范文件被引用但未在加载调度器登记（不会被加载、其中规则实际失效）: {m}",
            "AGENTS_COMMON.adoc")
    phase_done()


def check_forbidden_patterns():
    """检查是否误导入私有强约束约定。"""
    phase("私有约定误导入检查")
    files = collect_adoc_files()
    checked = 0
    total_lines = 0
    for i, rel in enumerate(files, 1):
        # AGENTS_COMMON.adoc 作为加载器允许出现中性示例路径，跳过其私有约定命中
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            lines = fh.readlines()
        total_lines += len(lines)
        found_in_file = False
        for j, line in enumerate(lines, 1):
            for pat, desc in FORBIDDEN_PATTERNS:
                if re.search(pat, line):
                    if not found_in_file:
                        detail(f"  [{i}/{len(files)}] 检查 {rel}")
                        found_in_file = True
                    err(f"{desc}", rel, j)
        checked += 1
    log(f"  扫描 {checked} 个文件, 共 {total_lines} 行")
    phase_done()


def check_historical_notes():
    """检查『不保留无用的历史来源声明』是否被遵守（机械抓手）。

    规范要求：不得添加指向旧文件/旧命名/旧位置的历史来源注记（旧文件可能已无法
    追溯、会让引用悬空），引用一律直接指向当前有效的地址。本检查扫描所有规范文件，
    拦截描述"之前是什么、后来改成什么"的变更来源/历史来源陈述（早期版本、原位于…
    迁移至此、真正的 agents.md 等），使该条规范真正有可执行抓手、而非仅靠自觉。
    """
    phase("历史来源声明检查")
    files = collect_adoc_files()
    checked = 0
    for i, rel in enumerate(files, 1):
        if _is_historical(rel):
            continue  # 变更历史本身就是历史陈述，本检查对它不适用
        found_in_file = False
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                for pat, desc in HISTORICAL_NOTE_PATTERNS:
                    if re.search(pat, line):
                        if not found_in_file:
                            detail(f"  [{i}/{len(files)}] 检查 {rel}")
                            found_in_file = True
                        err(f"{desc}（『不保留无用的历史来源声明』），应删除或改为直接指向当前有效表述", rel, j)
        checked += 1
    log(f"  扫描 {checked} 个文件")
    phase_done()


# ----------------------------------------------------------------------------
# 行段核对基建（把"关键词存在性"升级为"键落在某条可执行行段内"）
#
# 背景（本仓库实测复现的三桩失效）：旧实现把文件 `readlines()` 后 `"".join()` 成
# 一整段做关键词匹配，**结构信息在拼接时就丢了**——于是
#   * `.bat` 只探 `python3`、不探 `py` 启动器也能过（`where py` 只被整个文件的文本满足，
#     连写在注释里都算）；
#   * `.sh` 探测次序写反也能过（次序按 `text.find()` 判先手，把注释提到函数顶就变）；
#   * 文档里把整节删掉也能过（只核"全文有没有这几个词"）。
# 本基建的做法：**先把注释与 docstring 去掉，再逐行核对**——键必须与同一条可执行行
# 同时命中（`_code_lines`），次序也只在候选代码行之间比较（`_order_violation`）。
# 这不是"更严"，而是把原本想表达的判据真正实现出来（"这段代码里有没有这个分支"）。
REPO_SCRIPT_SRC_CACHE: dict = {}


def _read_script_src(rel: str):
    """读仓库内某个脚本/文本文件的原文（读不到返回 None）——多处防线共用的读入口。

    带缓存：同一轮校验里同一文件可能被多道防线读（解释器兜底 / 落点 / 薄壳），
    重复读取无意义。缓存的键是**仓库根相对路径**，故 REPO_ROOT 变化时调用方须清缓存
    （单测已统一在 setUp/tearDown 里清）。
    """
    if rel not in REPO_SCRIPT_SRC_CACHE:
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        try:
            with open(path, encoding="utf-8", newline="") as fh:
                REPO_SCRIPT_SRC_CACHE[rel] = fh.read()
        except OSError:
            REPO_SCRIPT_SRC_CACHE[rel] = None
    return REPO_SCRIPT_SRC_CACHE[rel]


def _strip_comment(text: str, comment: str = "#") -> str:
    """去掉一行里的注释部分。

    **大小写不敏感**：cmd.exe 的内建命令不区分大小写（`REM` / `rem` 同义），
    `.bat` 里两种写法都会出现；按大小写敏感匹配会把以 `REM` 起头的整行当成代码，
    于是注释里写一句 `rem 先探 py 启动器` 就能骗过"分支存在"的核对。
    只认**词首**（前面是行首或空白）的注释符号，避免误伤 `%~dp0`、`a#b` 一类字面串。
    """
    m = re.search(r"(^|\s)" + re.escape(comment), text, re.IGNORECASE)
    return text[:m.start()] if m else text


def _code_lines(text: str, comment: str = "#", block_comment: str = '"') -> list:
    """取出"候选可执行行"：`[(行号, 去注释并折叠空白后的正文)]`。

    两道过滤：
      * **三引号块**（Python 的块字符串，`block_comment` 给引号字符）——文档字符串里的
        示例代码不算分支（本仓库大量防线文档里引用脚本文本，不排掉会互相兜底）；
      * **行首注释**（`#` / `.sh` 的 `#` / `.bat` 的 `rem`）——注释里写的键不算代码。

    行内注释一并去掉（保留行内空白折叠，便于 "command -v" + "python3" 落在
    同一条行上判定——这正是"这条分支真的存在吗"的机械表述）。
    """
    out = []
    in_block = False
    for i, raw in enumerate(text.splitlines(), 1):
        line = raw.rstrip()
        stripped = line.strip()
        if block_comment and stripped.count(block_comment * 3) % 2 == 1:
            in_block = not in_block
            continue
        if in_block:
            continue
        low = stripped.lower()
        if low.startswith(comment) or low.startswith("rem "):
            continue
        body = _strip_comment(line, comment)
        body = " ".join(body.split())
        if body:
            out.append((i, body))
    return out


def _order_violation(text: str, order, comment: str = "#") -> bool:
    """在**候选可执行行**的顺序上判"任一 key 缺位时后面的 key 先出现"。

    参数 `order` 是一串"逐级降级的探测分支"的关键键（每个 key 可由若干个片段组成）：
    某个 key 在整份文本里都找不到，却排在另一个存在的 key 之前，即说明写反了——
    后面那条分支被前面的分支永久遮住，等于没有兜底。

    与旧实现的关键差别：位置取自**去注释后的代码行**（`_code_lines`），不取原始文本的
    `find()`——注释里提一句同样的话不再影响次序判定。
    """
    positions = []
    for key in order:
        frags = (key,) if isinstance(key, str) else tuple(key)
        pos = None
        for lineno, code in _code_lines(text, comment):
            if all(f in code for f in frags):
                pos = lineno
                break
        positions.append(pos)
    # 缺失优先于错序：先判"有没有哪一级根本没出现"——一级不在时，次序无从谈起
    # （只判 `positions != sorted(positions)` 会被 None 当成最小位置而漏报）。
    if any(p is None for p in positions):
        present = [p for p in positions if p is not None]
        return bool(present)
    return positions != sorted(positions)


def check_install_codeblock():
    """校验入口文档模板代码块逐字保留 + 入口文件名规则与 `AGENTS.md` 兼容。

    **落点已并入公共入口**（`AGENTS_COMMON.adoc`「安装与更新」）：安装文档此前是独立文件，
    用户口径是"把它的内容压进入口前部、删除源文件、以后直接引用入口"——故模板与模板所在
    文档合成一处，本检查只改**读哪个文件**，判据本体一条不动。

    背景一（模板逐字）：AI 照着入口文档里的模板在目标项目创建入口文档时，若代码块内的
    换行/空行被折叠、行被合并，会导致生成文档样式改变。为让『逐字原样保留』成为
    可执行约束而非靠自觉，本检查扫描该模板代码块，逐一确认每段必备行都各自独立成行
    （未被合并/折叠），且必备行之间的空行分隔完好。

    背景二（兼容 `AGENTS.md`）：平台与生态对 agent 规范文档的**默认命名是 `AGENTS.md`**
    （CodeBuddy、Cursor 等平台的固有约定），只认 `AGENTS.adoc` 会让安装规则在既有
    `AGENTS.md` 的项目上落不了地（重命名会打断平台识别、删旧建新会丢内容）。故把"默认
    `AGENTS.adoc`、已存在 `AGENTS.md` 时就地融合且不重命名、不另建"钉成机械可核对的判据。
    """
    phase("入口模板代码块检查（公共入口「安装与更新」）")
    if not os.path.isfile(INSTALL_FILE):
        log(f"  未找到 {INSTALL_REL}，跳过")
        phase_done()
        return
    with open(INSTALL_FILE, encoding="utf-8") as fh:
        lines = fh.readlines()

    # 定位模板代码块定界：**先定位「安装与更新」节**，再取其内第一对 `----`——公共入口里
    # 可能还有别的代码块，按"全文首个 `----`"取会在入口新增示例时静默改盯另一个块。
    sec_i = _section_line_index(lines, "安装与更新（引用方接入与取回口径）")
    if sec_i is None:
        err(f"{INSTALL_REL} 未找到「安装与更新（引用方接入与取回口径）」节——"
            "入口文档模板无处承载（安装口径已并入公共入口，该节被删即等于安装流程丢失）",
            INSTALL_REL)
        phase_done()
        return
    delim = [i for i, l in enumerate(lines) if i > sec_i and l.strip() == "----"]
    if len(delim) < 2:
        err(f"{INSTALL_REL} 的「安装与更新」节未找到完整的模板代码块定界符 `----`（需一对）",
            INSTALL_REL)
        phase_done()
        return
    open_i, close_i = delim[0], delim[1]
    body = lines[open_i + 1:close_i]

    # 必备内容：每行必须各自独立成行（不得与其它行合并/折叠）。
    # **不再要求模板里出现"安装文档路径"**：安装文档已并入本入口，新实例按规范入口地址
    # 即读到安装与取回口径（模板里那一行仍指向本入口，故它对老安装形态继续成立）。
    # 不含 `= Agent 规范入口` 这类可精炼的标题/小节——入口文档的"最小集"由
    # `specs/general/entry-doc.adoc` 作真源（用户口径：模板以用户手工编辑的形态为准，
    # 不因机械判据往回补标题与三节）。
    REQUIRED_LINES = [
        "本项目的 agent 执行规范入口为：",
        "https://agent.c332030.com/AGENTS_COMMON.adoc",
        "https://agent.c332030.com/script/fetch-specs.py",
        "读取该入口及其引用的 specs/ 规范，并持续遵守其全部要求。",
        "规范属强制约束：**开工前必须先读取规范再执行**，不得因未读取/记不全而跳过或放宽任何条款。",
    ]
    found = {s: False for s in REQUIRED_LINES}
    for raw in body:
        line = raw.rstrip("\n").rstrip("\r")
        if line in found:
            found[line] = True
    for s, ok in found.items():
        if not ok:
            err(f"{INSTALL_REL} 模板代码块缺失或行被合并/改写：未找到独立成行的『{s}』"
                "（模板须逐字原样保留，不得折叠换行）", INSTALL_REL)

    # 同一路径不得在模板里出现两次（**用户点名**：入口模板里
    # `https://agent.c332030.com/AGENTS_COMMON.adoc` 重复出现）。成因是本仓库实测的
    # 一次合并：安装口径并入公共入口、`INSTALL.adoc` 被删后，模板里原来指向安装文档的
    # 那一行被改成入口自己的地址——于是同一个 URL 出现两次、对外两个不同名目
    # （"规范入口"与"安装与更新的文档入口"）指向同一份文件，读的人以为有两个落点。
    # 判据按**逐字相同的路径行**核：取同一路径的重复次数，>1 即报。
    path_lines: dict[str, int] = {}
    for raw in body:
        line = raw.rstrip("\n").rstrip("\r")
        if line.startswith("http://") or line.startswith("https://"):
            path_lines[line] = path_lines.get(line, 0) + 1
    for path, n in path_lines.items():
        if n > 1:
            err(f"{INSTALL_REL} 模板代码块里同一路径重复出现 {n} 次：『{path}』——"
                "模板是给新实例照抄的『下一站地址表』，同一地址挂两个名目（如既作规范入口、"
                "又作安装文档入口）会让读的人以为有两个不同落点；安装口径已并入本入口时，"
                "那一行就是多余的第二真源，须删（判据见 specs/general/review.adoc「精炼性」）",
                INSTALL_REL)

    # 入口文件名规则：默认 AGENTS.adoc，且兼容已存在的 AGENTS.md（就地融合、不重命名/不另建）
    with open(INSTALL_FILE, encoding="utf-8") as fh:
        install_text = fh.read()
    # 取规范脚本路径须在模板正文里（缺它时新实例不知道如何去下载规范）
    for key, desc in (
            ("https://agent.c332030.com/script/fetch-specs.py",
             "取规范脚本路径须写进入口模板——缺它时新实例不知道如何去下载规范"),):
        if key not in install_text:
            err(f"{INSTALL_REL} 入口模板缺『{key}』——{desc}", INSTALL_REL)

    for key, desc in (
            ("AGENTS.adoc", "默认入口文件名"),
            ("AGENTS.md", "平台默认命名须被兼容（已存在时就地融合）"),
            ("不重命名", "已存在 AGENTS.md 时不得重命名/迁移成 AGENTS.adoc（会打断平台识别）"),
            ("不另建", "已存在 AGENTS.md 时不得再另建一个 AGENTS.adoc（双入口会分叉）")):
        if key not in install_text:
            err(f"{INSTALL_REL} 入口文件名规则被破坏：缺失『{key}』（{desc}）——"
                "只认单一扩展名会让安装规则在已有其他命名的项目上落不了地", INSTALL_REL)

    # **空行须逐字保留**：只核"行在不在"拦不住空行被吞——被吞的行会与上/下一段粘成一块，
    # 而"空行被吞导致样式变化"正是本条要拦的形态。
    #
    # 判据取**段落结构**：模板体里凡"非空行紧接非空行"处即报（正常模板的每一段之间都有空行，
    # 段内不会两行紧贴）。**不比"相邻必备行之间的行距"**：模板里相邻必备行之间本就隔着说明段
    # （实测两个 URL 之间隔 4 行、最后两行之间隔 6 行），删掉中间那处空行后行距仍 ≥ 2、
    # 防线全绿；也不给"哪些行必须空行"开例外清单——模板以用户手工编辑的形态为准，
    # 例外清单会随措辞调整失效（实测某版按"必备行 + 括注续行"给例外，仍漏掉说明段前后的空行）。
    # **唯一例外**：以全角括号起头的**括注续行**（如入口地址下一行的
    # `（重装、更新、要完整的取法与退路…）`）——它与上一行是同一条信息的延续，
    # 模板里本就紧贴（见 `AGENTS_COMMON.adoc` 模板体），要求它俩之间留空行等于把正确写法判红。
    # 例外只认"括注"这一种形态：它本身是**续行**（不独立成段），与"两段之间被吞掉空行"
    # 的形态在文本上可分（后者不会以全角左括号起头）。
    for i in range(len(body) - 1):
        cur, nxt = body[i].rstrip("\n\r"), body[i + 1].rstrip("\n\r")
        if not (cur.strip() and nxt.strip()):
            continue
        if nxt.lstrip().startswith("（"):
            continue
        err(f"{INSTALL_REL} 模板代码块中『{cur}』与『{nxt}』之间缺少空行"
            "（两行紧贴＝空行被吞、两段会粘成一块，新实例照抄出来的入口文档样式随之改变；"
            "模板须逐字原样保留，段与段之间一律留空行）", INSTALL_REL)
    phase_done()


def _section_line_index(lines, title: str):
    """返回 `== <title>` 节标题所在的行号（找不到返回 None）。"""
    for i, line in enumerate(lines):
        if line.strip() == "== " + title:
            return i
    return None


# 解释器兜底的**逐条行段判据**（键须与同一条可执行行同时命中——见 `_code_lines`）。
# 每个 entry = (文件, 描述, 要点组, 降级次序, 注释符)
#   * 要点组：[(说明, 键组…)]，键组里的片段须落在**同一条**候选代码行上；
#     `.bat` 的探测写法是一行一分支，故 `where` 与 `py` 落在同一行；
#     `.sh` 的 `if command -v python3 …; then` 同样一行一分支；
#   * 降级次序：逐级探测的关键键（先探的在先）；写反即后面的分支被永久遮住；
#   * 注释符：`.bat` 用 `rem`（`_strip_comment` 对大小写不敏感）。
INTERPRETER_FALLBACK_LINE_SPECS = (
    ("script/fetch-specs.sh", "Linux/macOS 入口", "#",
     (("须**按次序探测解释器**（先 python3、再 python）——不得把 python3 直接写死成前提"
       "（本仓库实证：机器上只有 python、没有 python3 时，装不上规范）",
       (("command -v python3", ">/dev/null"), ("command -v python ", ">/dev/null"))),
      ("须**用探测到的那个解释器**调用同目录的逻辑代码（`exec` 原样转交参数）",
       (("exec", "$runtime", "fetch-specs.py", "$@"),)),
      ("两者都没有时须**报错并退出非 0**（不静默继续）",
       (("未找到解释器",), ("exit 127",)))),
     (("command -v python3", ">/dev/null"), ("command -v python ", ">/dev/null"))),
    ("script/fetch-specs.bat", "Windows 入口", "rem",
     (("须**按次序探测解释器**（py -3 → python3 → python）——不得把 python3 直接写死成前提；"
       "Windows 上最常见的是 py 启动器，只探 python3 等于把大半个 Windows 装机量挡在门外",
       (("where py ",), ("where python3 ",), ("where python ",))),
      ("须**用探测到的那个解释器**调用同目录的逻辑代码并原样透传参数",
       (("%FETCH_SPECS_RUNTIME%", "%~dp0fetch-specs.py", "%*"),)),
      ("都没有时须**报错并退出非 0**（不静默继续）",
       (("exit /b 127",),))),
     (("where py ",), ("where python3 ",), ("where python ",))),
)


def _check_interpreter_fallback_entry_lines():
    """『解释器兜底』：两个入口的探测分支**逐条落在可执行行上**、且次序正确。

    本条只核文本形态（"某台机器上到底有没有解释器"属运行时事实）。
    **用户点名/实证失效**与逐项覆盖见 `script/check_effective.py` 的机制登记表。

    判据的表述：每个要点给出若干「键组」，键组里的片段须**同一条可执行行**同时命中——
    这是「这条分支真的写出来了」的机械表述。只核全文关键词时，注释里写一句、或把分支
    删掉只留另一条，都能骗过（本仓库实测复现）。
    """
    phase("解释器兜底防线检查（入口逐条行段）")
    for rel, role, comment, groups, order in INTERPRETER_FALLBACK_LINE_SPECS:
        text = _read_script_src(rel)
        if text is None:
            err(f"缺失 {rel}——{role}不在，「没有解释器的机器上装不上规范」这条兜底无从核对",
                rel)
            continue
        code_lines = _code_lines(text, comment)
        for group_desc, key_groups in groups:
            for keys in key_groups:
                hit = any(all(f in code for f in keys) for _, code in code_lines)
                if not hit:
                    err(f"解释器兜底防线被破坏：{rel} 没有任何一条**可执行行**同时命中 "
                        f"{list(keys)}——{group_desc}；注释/文档字符串里写过不算"
                        "（本仓库实测：把该分支从文件里删掉、只在注释里留一句，旧实现仍报绿）",
                        rel)
        if _order_violation(text, order, comment):
            err(f"解释器兜底防线被破坏：{rel} 的探测次序不对——按次序探测才不会让后面的分支"
                "被前面的分支永久遮住（缺的写在前、存在的写在后的形态即报此错）", rel)
    phase_done()


# 解释器兜底与取回口径要点须齐备的**承载文件**（键组同样按**同一行**核——这些要点是"遇到这种
# 情况按什么次序处置"的清单，被折叠成一句话就会被读漏一条）。
#
# **本轮改动（用户口径：入口那一节与脚本头部注释重复）**：入口「取规范到本地副本」与
# `script/fetch-specs.py` 的头部注释描述了同一件事（探测次序、处置次序、脚本开关）。
# 同一件事实写两处即两处漂移，故收敛为**一处完整定义 + 其余回指**：
#   * 工序侧真源（怎么取、怎么更新、探测与处置次序、脚本开关）＝ `script/fetch-specs.py` 头部注释；
#   * 公共入口那一节只留**落点那一处事实**，其余回指脚本头部注释。
# 跟随该收敛，本防线**不得再要求入口复述那些句子**（要求复述＝把重复判成合规，
# 正是用户点名的形态）——它改为核**真源那一侧**写全、入口**给回指**。
INSTALL_FETCH_SOURCE_REL = "script/fetch-specs.py"
# **真源在文件里的哪一处**：只给文件名而不给部位时读者仍不知道读哪一段，
# 故入口的回指须点名"头部注释"（本仓库实测：去掉这四字，只点名文件的旧判据仍报绿）。
INSTALL_FETCH_SOURCE_POINT = "头部注释"
# 入口里承载落点与回指的那一节（落点那一处事实与回指都落在它头上，故先定位再核）
INSTALL_FETCH_SECTION = "取规范到本地副本"
# 副本落点：同一条要点可以有多种等价写法，故按**要点**核、不核某一种写法的字面值——
# 『用户家目录』与『用户路径』同指用户家目录（`~` 的写法亦然）；核字面值时一次措辞精炼
# 就会让判据空转（本仓库实测：那句话被压成 `~/.cache/agent-specs` 后旧字面判据报红，
# 而"落点只有一处"这条要求本身并未被削弱）。
HOME_WORDINGS = ("用户家目录", "用户路径", "家目录", "~")
LANDING_NAME = ".cache/agent-specs"
INSTALL_NO_PYTHON_POINTS = (
    (("装一个 python 3",), "须给第一条处置：按本平台既有的软件分发方式装一个 python 3（并说明"
                        "脚本自身**不得代为安装**）"),
    (("退出码", "非 0"), "须写明「取不到就是取不到」：脚本报错、退出码非 0，"
                        "**不得静默继续**（静默继续会把『没取到规范』混进『取到了』）"),
    (("**人**的一步", "不得**代为安装"), "须写明这条处置是**人**的一步、入口不得代为安装运行时"
                                     "（改系统状态、要权限、对调用方不可预期）"),
    (("curl", "python3"), "须点名 `curl … | python3 -` 那条远程执行形态**同样要 python**——"
                          "只写'本脚本要 python'会让使用者以为换成官方那条管道命令就不用装"),
    (("python2",), "须写清「一个都没有」的边界：**只装 python2 的发行版不算**（CentOS/RHEL 8 及更早、"
                   "老 macOS 上 `python` 就是 python2），上一条的次序会取到它、脚本照样跑——"
                   "缺这句时这些机器会被误判成「必须先去装 python3」"),
    (("一次取全",), "须写明一次取全（入口与其 `specs/` 一起取回，不用手拼逐条下载命令）——"
                   "缺则『怎么取』只剩入口模板里一行地址"),
    (("清单从入口自身解析",), "须写明清单从入口自身解析（按加载调度器登记自动解析），"
                          "故新增一份规范不必改脚本、也不会漏取——缺则执行者会另拼一份文件清单，"
                          "该清单随即与调度器脱钩"),
    (("以远程为准",), "须写明默认以远程为准（取回的字节与本地不同才落盘、远端改过就刷新），"
                    "『重复执行即是更新』才是可核对的——缺则『更新』只说了一半，"
                    "执行者无法判断要不要覆盖本地那份"),
    (("--keep",), "须写明『不动本地那份』的开关——缺则只想核对、不想覆盖的执行者只能先删本地副本"),
    (("--base",), "须写明来源可改（`--base`）——缺则换来源的人只能改脚本"),
)

# 回指那一行的**识别标记**：本节里"真源"二字不止一处（「取回口径与判据分家」条也说
# 判据真源在 entry-doc.adoc），故须用**只属于回指那一行**的措辞把它认出来——
# 它声明的是"**工序侧**真源"（与防线 docstring 同一口径：工序侧＝怎么取、怎么更新）。
INSTALL_FETCH_POINTER_MARKER = "工序侧真源"

# 入口「取规范到本地副本」一节收敛后**仍须自己写明**的两件事：落点那一处事实 + 指向真源的
# 回指（读者按这一行就能找到细则，不必回头问用户）。两组都按**要点**核、不核句式。
INSTALL_FETCH_POINTER_KEYS = (
    (("__home_wording__",),
     "须把落点写成**用户侧**的定位（" + "、".join(HOME_WORDINGS) + " 任一写法与落点名同现）"
     "——本节是落点那一处事实的落点，缺则读者不知道副本在哪；只写裸路径字面值也不够，"
     "读者不知道那是「谁的家目录」"),
    # 回指真源的那一条：**须是"声明真源在哪"的那一行**，不是"任意提到两者"的一行——
    # 本节里别处也会顺带点到 `script/fetch-specs.py` 与其头部注释（如「取回口径与判据分家」
    # 条把处置次序也指向它），若按"任一行含这两个字样"核，把回指那一行整条删掉仍会被
    # 那一处兜住（本仓库实测复现：删掉该行，六道相关防线全绿）。故按**同一行**核、
    # 且要求该行带只属于它的措辞 `INSTALL_FETCH_POINTER_MARKER`，与别处的顺带提及区分开。
    ((INSTALL_FETCH_SOURCE_REL, INSTALL_FETCH_SOURCE_POINT, INSTALL_FETCH_POINTER_MARKER),
     "须回指真源**及其部位**（`script/fetch-specs.py` 的**头部注释**是「怎么取、怎么更新、"
     "解释器兜底」的真源）——只写落点而不给去向，读者读到本节仍不知道取法的细则在哪，"
     "等于把同一件事实再抄一遍或干脆丢掉；只给文件名而不给部位同样等于没给去向；"
     "该回指须落在**声明真源是哪一处**的那一行上（本节别处顺带提到文件名不算给了去向）"),
)


def _check_install_no_python_section():
    """解释器兜底与取回口径要点：**真源那一侧**写全 + 入口只留落点与回指。

    本函数原按 **入口的「取规范到本地副本」一节**逐条核那几组要点。用户点名该节与
    `script/fetch-specs.py` 头部注释重复后，判据随之改为**核真源**：

    * 要点（探测次序、处置次序「装一个 python 3 / 只装 python2 不算 / 退出码非 0 /
      `curl|python3` 同样要 python / 入口不得代为安装运行时」，以及取回与更新口径
      「一次取全 / 清单从入口自身解析 / 以远程为准 / `--keep` / `--base`」）须在
      `script/fetch-specs.py` 的**头部注释**里写全——它是"怎么取、怎么更新"的工序侧真源；
    * 入口那一节**不得**被抽空成一枚指针：它仍须自己写明**落点那一处事实**（落点名 +
      用户侧定位），**且**必须给出指向真源**及其部位**的回指。

    反向也拦：旧判据要求入口复述那几句时，"把同一件事实写两处"会被判成合规——正是本轮
    用户点名的形态，故**不得**再按"入口里有没有这些句子"判红。
    """
    phase("解释器兜底与取回口径防线检查（真源=脚本头部注释，入口只留落点与回指）")
    text = _read_script_src(INSTALL_REL)
    if text is None:
        err(f"缺失 {INSTALL_REL}——取回口径的落点与回指无处承载", INSTALL_REL)
        phase_done()
        return
    # ① 要点须在真源那一侧（脚本头部注释）写全
    source = _read_script_src(INSTALL_FETCH_SOURCE_REL)
    if source is None:
        err(f"缺失 {INSTALL_FETCH_SOURCE_REL}——解释器兜底与取回口径失去真源",
            INSTALL_FETCH_SOURCE_REL)
    else:
        head = source.split('"""')
        head_text = head[1] if len(head) > 1 else ""
        if not head_text:
            err(f"{INSTALL_FETCH_SOURCE_REL} 没有模块文档字符串——真源部位（头部注释）不存在",
                INSTALL_FETCH_SOURCE_REL)
        else:
            source_lines = [l.strip() for l in head_text.splitlines() if l.strip()]
            for keys, desc in INSTALL_NO_PYTHON_POINTS:
                if not any(all(k in line for k in keys) for line in source_lines):
                    err(f"{INSTALL_FETCH_SOURCE_REL} 的头部注释缺失要点 {list(keys)}"
                        f"（须落在同一行上）——{desc}；公共入口已不再复述这些句子"
                        "（同一件事实只写一处），真源这一侧缺即等于整条规则没有落点",
                        INSTALL_FETCH_SOURCE_REL)
    # ② 入口那一节不得被抽空：落点那一处事实 + 指向真源（及其部位）的回指
    m = re.search(r"^==+ *" + re.escape(INSTALL_FETCH_SECTION) + r".*?(?=^==+ |\Z)",
                  text, re.S | re.M)
    if not m:
        err(f"{INSTALL_REL} 缺少『{INSTALL_FETCH_SECTION}』整节——取回口径的落点与回指"
            "（本落点在哪、细则去哪儿读）一并失去落点", INSTALL_REL)
        phase_done()
        return
    # **按行核、不按整节核**：整节核时，节里任何一处出现该字样就算命中——回指那一句被改成
    # "真源见 script/fetch-specs.py"（部位写成"段尾注释"、或干脆不给部位）时，别的行里
    # 出现的文件名会把缺失兜住，防线全绿（本条要核的恰是"这一句有没有把去向说全"）。
    # 故与 `INSTALL_NO_PYTHON_POINTS` 同一口径：一行的正文里须**同时**出现整组键。
    lines_in_section = [l.strip() for l in m.group(0).splitlines()
                        if l.strip() and l.strip() != "----"]
    for keys, desc in INSTALL_FETCH_POINTER_KEYS:
        if keys == ("__home_wording__",):
            if not any(any(k in line for k in HOME_WORDINGS) and LANDING_NAME in line
                       for line in lines_in_section):
                err(f"{INSTALL_REL}『{INSTALL_FETCH_SECTION}』一节缺失落点（"
                    f"{'、'.join(HOME_WORDINGS)} 任一写法须与 `{LANDING_NAME}` "
                    "落在同一行上）——" + desc, INSTALL_REL)
            continue
        if not any(all(k in line for k in keys) for line in lines_in_section):
            err(f"{INSTALL_REL}『{INSTALL_FETCH_SECTION}』一节缺失 {list(keys)}"
                "（须落在同一行上）——" + desc
                + "（本节的职责已收敛为『写明落点 + 回指真源』，两件事缺一即读者要么不知道"
                "副本在哪、要么不知道去哪儿读取回与更新细则）", INSTALL_REL)
    phase_done()


def check_spec_fetch_guard():
    """『规范抓取防线』：随规范分发的取文件脚本不得被删、入口不得拆散或退化。

"""
    phase("规范抓取（安装取文件）防线检查")
    targets = {
        "script/fetch-specs.py": ("fetch-specs.py", "跨平台逻辑代码"),
        "script/fetch-specs.sh": ("Linux/macOS 入口",),
        "script/fetch-specs.bat": ("Windows 入口",),
    }
    for rel, desc in targets.items():
        if not os.path.isfile(os.path.join(REPO_ROOT, *rel.split("/"))):
            err(f"缺失 {rel}——安装取文件的抓手（{'/'.join(desc)}）被删除后，"
                "执行者又会临场手拼逐条下载命令（清单漏项 + 转义出错 + 逐条往返）", rel)
    py = os.path.join(REPO_ROOT, "script", "fetch-specs.py")
    if not os.path.isfile(py):
        phase_done()
        return
    body = open(py, encoding="utf-8").read()

    def _keys(k):
        return (k,) if isinstance(k, str) else tuple(k)

    for keys, desc in (
        (("AGENTS_COMMON.adoc", "SPECS_REF_RE", "specs/"),
         "须**从入口自身解析清单**（读 AGENTS_COMMON.adoc 的调度器登记、按 `specs/...` 提取）——"
         "退回手工清单/硬编码文件名即回到'新增规范就漏一份'的失效"),
        (("--keep", "local_bytes"),
         "须**默认以远程为准**（每份文件取回的字节与本地比较、不同才落盘；`--keep` 才回到"
         "「本地已有即不动」）——退回「本地既有就跳过」会让**重复执行安装拿不到最新规范**"
         "（安装脚本会更新，用户实测诉求：重跑一次要能更新现有的那份）"),
        (("把本地副本删掉", "--keep"),
         "须写明**取回失败时保留本地已有的那一份**、并给「不动本地那份」的路径（`--keep`）——"
         "以远程为准不等于「失败也把本地删掉」：那会把「没更新」变成「没有」"),
        (("doctype", "html"),
         "须有**不是站点首页**的判据（站点对未命中路径回落成首页 HTML 且返回 200，"
         "只判状态码会把 HTML 当成'取到的规范'写进落点）——本条实现期实测，故写成判据"),
        ("只写落点目录",
         "须写明**只写落点目录、不写项目里其他位置**（落点不是调用方给的路径，而是脚本自己"
         "按用户家目录算出来的固定位置——撤掉那些换落点的入口后，越界面随之消失，"
         "这条判据把『没有第二处写入』钉住）"),
        (("os.replace",),
         "须**先取到内存、再原子落盘**（临时文件 + `os.replace`）——直接覆盖既有副本时，"
         "传到一半失败会把原本完好的副本截断成半份（比'没更新'更坏：副本在、内容是坏的）"),
        (("退出码", "1", "2"),
         "头部注释须写明**退出码语义**（0 成功 / 1 有文件没取到 / 2 参数或前置条件错误）——"
         "只有『取不到』可被调用方判定，副本才不会被当成已就绪"),
        (("不删除", "保留本地"),
         "须写明**不删除落点里的既有文件**、且取回失败时**保留本地已有的那一份**"
         "（否则一次失败会把『没更新』变成『没有』）"),
    ):
        missing = [k for k in _keys(keys) if k not in body]
        if missing:
            err(f"规范抓取防线被破坏：script/fetch-specs.py 缺失要点 {missing}——{desc}",
                "script/fetch-specs.py")
    # 入口形态：薄壳 + 同主名 + 退出码（两平台各自的可核对写法）
    entry_checks = (
        ("script/fetch-specs.sh",
         (("exec", "fetch-specs.py"), ("$@",)),
         "须用 `exec` 跑同目录的逻辑代码并原样转交 `$@`（入口只做定位、参数透传、退出码转交三件事）"),
        ("script/fetch-specs.bat",
         (("%~dp0",), ("%*",), ("exit /b %errorlevel%",)),
         "须定位同目录逻辑代码、`%*` 原样透传参数，并以 `exit /b %errorlevel%` 原样返回退出码"
         "（缺则退出码是最后一条命令的，「失败也成功」）"),
    )
    for rel, keys_groups, desc in entry_checks:
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        text = open(path, encoding="utf-8").read()
        for keys in keys_groups:
            missing = [k for k in keys if k not in text]
            if missing:
                err(f"规范抓取防线被破坏：{rel} 缺失 {missing}——{desc}", rel)
    # 解释器兜底（本仓库实证：入口原先只调 python3，"没有 python 的机器上装不上规范"）。
# 判据**按行段核**（`_code_lines` / `_order_violation`）：键必须与同一条**去注释后的
# 可执行行**同时命中，探测次序也只在候选代码行之间比较——只核"整份文件里有没有这几个词"
# 时，注释里写一句就能骗过（本仓库实测复现：`.bat` 只探 python3 不探 `py`、`.sh` 次序
# 写反、把入口的取回与处置口径那一节整节删掉，旧实现全都报绿）。
    _check_interpreter_fallback_entry_lines()
    _check_install_no_python_section()
    # 落盘形态：`.bat` 纯 ASCII + CRLF、`.sh` LF（入口按各自平台规范落盘）
    bat = os.path.join(REPO_ROOT, "script", "fetch-specs.bat")
    if os.path.isfile(bat):
        raw = open(bat, "rb").read()
        if any(b > 127 for b in raw):
            err("script/fetch-specs.bat 含非 ASCII 字节——批处理须纯 ASCII"
                "（cmd.exe 按系统代码页解析，非 ASCII 会乱码）", "script/fetch-specs.bat")
        if b"\r\n" not in raw:
            err("script/fetch-specs.bat 不是 CRLF 行尾——LF-only 的批处理在 cmd.exe 下直接"
                "执行失败", "script/fetch-specs.bat")
    sh = os.path.join(REPO_ROOT, "script", "fetch-specs.sh")
    if os.path.isfile(sh):
        raw = open(sh, "rb").read()
        if b"\r\n" in raw:
            err("script/fetch-specs.sh 含 CRLF 行尾——.sh 一律 LF", "script/fetch-specs.sh")
    # 公开说明同步：公共入口与 README 须让执行者知道这个抓手
    for rel, keys, desc in (
        (INSTALL_REL, ("fetch-specs", "用户家目录"),
         "入口的安装与取回口径须写明取文件抓手与它的落点（用户家目录下的那一处）——"
         "否则安装时又回到手拼下载命令"),
        (INSTALL_REL, ("clean_tmp.py", "下载"),
         "入口的安装与取回口径须写明：**下载来的文件（含安装脚本）都只落这一处**——"
         "只写规范副本的落点时，清理脚本等下载物仍会被手工存到别处，"
         "用户口径『下载的文件一律只落这一个地方』就对不上了"),
        ("AGENTS_COMMON.adoc", ("fetch-specs",),
         "公共入口的「加载方式」须写明随规范分发的取文件抓手——引用方按入口加载时才知道有它"),
        ("README.adoc", ("fetch-specs",),
         "README 的目录结构与引用方式须登记该抓手（读者从入口才知道取文件不必手工拼清单）"),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        text = open(path, encoding="utf-8").read()
        missing = [k for k in keys if k not in text]
        if missing:
            err(f"规范抓取防线被破坏：{rel} 缺失 {missing}——{desc}", rel)
    phase_done()


def check_shared_cache_guard():
    """『规范抓取落点防线』：副本只取到**用户家目录下的一处**（无第二落点）。

"""
    phase("规范抓取落点防线检查")
    _check_install_entry_placeholder_lines()
    rel = "script/fetch-specs.py"
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"缺失 {rel}——取文件的抓手不在，落点与解释器兜底都无从谈起", rel)
    else:
        text = open(path, encoding="utf-8").read()
        # 正向判据：这些要点必须在（缺一即"只有这一个落点"无从谈起）
        for desc, keys in (
                ("落点须由用户家目录算出（不分系统、不分环境，只有这一处）",
                 ("expanduser", "CACHE_HOME_DIR", "CACHE_APP_DIR",
                  "CACHE_HOME_DIR, CACHE_APP_DIR")),
                ("家目录取不到时须报错退出、不得静默换地方",
                 ("not os.path.isdir", "raise ValueError")),
                ("落点须按来源地址分槽（不同来源的副本互不覆盖）",
                 ("cache_slot_dir", "urlsplit")),
                ("脚本不得删除落点里的既有文件（清理属破坏性操作）",
                 ("不删除",)),
                ("安装脚本（本脚本与其平台入口、清理脚本）须一并取到落点（用户口径："
                 "下载的文件一律只落这一个地方）",
                 ("INSTALL_SCRIPTS", "fetch_install_scripts")),
                ("安装脚本在落点里只保留文件名、跨来源共用（不落来源槽）",
                 ("os.path.basename(rel)", "落点根下")),
                ("落点里的入口须能直接跑（HTTP 取回不带文件模式，须补可执行位）",
                 ("_ensure_executable", "os.chmod")),
        ):
            missing = [k for k in keys if k not in text]
            if missing:
                err(f"取规范落点防线被破坏：{rel} 缺失 {missing}——{desc}", rel)
        # 反向判据：这些**出现即报红**——它们都是"同一份规范可以落在多处"的形态
        # （用 missing 判会把判据判反，故单独一组、按 present 判）
        for desc, keys in (
                ("不得再随平台另取一套缓存目录（落点只有用户家目录下的一个）",
                 ("XDG_CACHE_HOME", "LOCALAPPDATA")),
                ("不得再保留项目内临时目录这类第二落点",
                 ("--local", "tmp/agent-specs")),
                ("不得再保留换落点的入口（落点固定）",
                 ("--cache-dir", "AGENT_SPECS_CACHE", "--out")),
        ):
            present = [k for k in keys if k in text]
            if present:
                err(f"取规范落点防线被破坏：{rel} 仍出现 {present}——{desc}；"
                    "用户口径是『只有这个路径了，没有其他路径了』，多一套落点必然与人对不上",
                    rel)
    # 落点那**一处取值**只能有一个真源：公共入口（安装口径已并入它，它是"落点长什么样、
    # 怎么再取一次"的工序侧唯一真源）。其余文档**不得再抄一遍落点路径** —— 抄一份即多一个漂移点，
    # 而"抄过来的那句"与真源不一致时，读者无从判断以哪处为准（用户本轮点名：
    # "依旧有很多相同的描述在不同的地方，不满足精炼性的要求"）。
    # 判据按**要点**核：要么自己写出落点（用户侧词 + 落点名同现），要么给出指向真源的
    # 引用；既不写落点、也不给引用（只留"用户级缓存"这类笼统说法）即报红。
    for rel, desc, landing_owner in (
        (INSTALL_REL,
         "公共入口的「取规范到本地副本」是本落点与取回方式的**唯一真源**：它必须自己写明落点"
         "（用户家目录/用户路径下的 `.cache/agent-specs`），不得改成指向别处的引用",
         True),
        ("README.adoc",
         "README 的取法说明须让读者知道副本落在哪：写明落点，或给出指向入口的引用",
         False),
        ("PUBLIC.adoc",
         "公开内容清单须让引用方知道这些工具会把副本放在哪：写明落点，或给出指向入口的引用",
         False),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        text = open(path, encoding="utf-8").read()
        written = LANDING_NAME in text and any(k in text for k in HOME_WORDINGS)
        referenced = LANDING_REFERENCE_MARKER in text
        if landing_owner and not written:
            err(f"取规范落点防线被破坏：{rel} 未写明落点"
                f"（用户家目录/用户路径下的 `{LANDING_NAME}`）——{desc}", rel)
        elif not landing_owner and not written and not referenced:
            err(f"取规范落点防线被破坏：{rel} 既未写明落点、也未指向真源——{desc}；"
                "按『同一描述只写一处』它只该给一行引用"
                f"（含『{LANDING_REFERENCE_MARKER}』+ 指向 `{INSTALL_REL}`），"
                "否则读者不知道自己读到的是不是最新的那一份", rel)
        elif not landing_owner and written and not referenced:
            err(f"取规范落点防线被破坏：{rel} 又抄了一遍落点路径、且未指向真源——"
                "同一描述出现在第二处即多一个漂移点；收敛形态是**一处完整定义 + 其余一行引用**"
                f"（真源＝`{INSTALL_REL}`「取规范到本地副本」），"
                f"引用须含『{LANDING_REFERENCE_MARKER}』", rel)
    phase_done()


ENTRY_PLACEHOLDER_LINES = (
    (("优先取到本地副本", "避免网络原因无法访问"),
     "入口占位须保留『优先取到本地副本（避免网络原因无法访问）』这条要求（用户在 PR 上点名过）"
     "——它是『网络不可达时本地仍有一份可读副本』这条收益的唯一落点，删掉即等于回到『网络不通就读不了规范』；"
     "副本的落点只有用户家目录下的一处，故本条只钉『优先取到本地副本』、"
     "不在模板里钉死某一个落点字面值（落点改了不该让入口模板跟着报红）"),
    (("取不到", "远程"),
     "同一条须写明**取不到时的退路**（没取到就直接读远程入口）——只写『优先取到临时目录』会让人以为"
     "取文件是可用规范的前提；实际取不到也能读，缺这句等于把可选的一步写成前置条件"),
    (("需要最新规范", "更新"),
     "同一条须写明**需要最新规范时怎么办**（再运行一次即是更新）——安装脚本本身会更新，"
     "缺这句时用户重跑安装仍拿的是本地旧副本，且入口占位也被判成『与模板一致』而不更新"
     "（本仓库实证：把这句话删掉/合并后，机械检查不报错、已装项目的旧模板被判为逐字一致而原样不动）"),
)


def _check_install_entry_placeholder_lines():
    """『入口占位三要点』：公共入口「安装与更新」的入口模板里「怎么取、取不到怎么办、怎么更新」那一行不得被弱化。

    三要点＝①优先取到本地副本（网络不可达时的可读副本，**不钉具体落点**）；②取不到时的退路
    是直接读远程入口；③需要最新规范时再运行一次即是更新。缺任一即报红并说明读者会怎么读错。
    只核措辞要点；「取不到 / 更新」的**行为**由 `script/check_specs_test.py` 的端到端用例承担。

    """
    phase("入口占位三要点检查")
    path = os.path.join(REPO_ROOT, INSTALL_REL)
    if not os.path.isfile(path):
        err(f"缺失 {INSTALL_REL}——安装口径不在，入口占位的取法/退路/更新三要点无从核对",
            INSTALL_REL)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        lines = fh.readlines()
    sec_i = _section_line_index(lines, "安装与更新（引用方接入与取回口径）")
    delim = [i for i, l in enumerate(lines)
             if l.strip() == "----" and (sec_i is None or i > sec_i)]
    if sec_i is None or len(delim) < 2:
        err(f"{INSTALL_REL} 未找到「安装与更新」节的入口模板代码块定界符 `----`（需一对）——"
            "入口占位三要点无处承载", INSTALL_REL)
        phase_done()
        return
    body = "".join(lines[delim[0] + 1:delim[1]])
    for keys, desc in ENTRY_PLACEHOLDER_LINES:
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"入口占位三要点缺失 {missing}——{desc}", INSTALL_REL)
    phase_done()



ENTRY_DOC_SPEC = "specs/general/entry-doc.adoc"
# 入口模板里须能一站直达的三条路径（按字面核——它们是"下一站"的地址，少了任何一条，
# 新实例就只能回来问用户或自己猜）。核的是**路径本身在不在模板正文**，**不核它挂在哪
# 一节**——模板的小节结构以用户手工编辑的形态为准（用户已点名不要那三节）。
ENTRY_DOC_PATH_POINTS = (
    ("https://agent.c332030.com/AGENTS_COMMON.adoc", "规范路径（本项目的执行规范入口，安装与取回口径也在其中）"),
    ("https://agent.c332030.com/script/fetch-specs.py", "取规范脚本路径（下一次怎么下载规范）"),
)
# 副本落点与取回方式两要点（按模板正文核，不依赖小节标题）
# 同一条要点可以有多种等价写法，故判据按**要点**核、不核某一种写法的字面值：
# 『用户家目录』与『用户路径』同指用户家目录（`~` 的写法亦然）；`~/.cache/agent-specs`
# 与『用户家目录下的 `.cache/agent-specs`』同理。核字面值时，一次措辞精炼就会让判据空转
# （本轮实测：模板那行由「用户家目录下的 `.cache/agent-specs`」压成 `~/.cache/agent-specs`
# 后，旧字面判据报红，而"落点只有一处"这条要求本身并未被削弱）。
HOME_WORDINGS = ("用户家目录", "用户路径", "家目录", "~")
# 落点"指向真源"的识别特征：同一描述只写一处，其余位置给一行引用时必须点名真源
# （公共入口「取规范到本地副本」是落点与取回方式的唯一真源）。判据按要点核、
# 不核句式——"唯一真源/唯一落点/见（公共入口）…"任一形态都算给了引用。
LANDING_REFERENCE_MARKER = "唯一真源"
LANDING_NAME = ".cache/agent-specs"
ENTRY_DOC_COPY_POINTS = (
    (HOME_WORDINGS,
     "落点：用户家目录/用户路径下的 `.cache/agent-specs`（只有这一个）"),
    (("fetch-specs", "再运行一次"), "取回与更新方式：脚本名 + 「再运行一次即是更新」"),
)
# 「判据与工序分家」的**单一真源声明**（去重要求的机械抓手）：同一件事的两半各有唯一落点——
#   判据侧（该不该写、与临时产物的分界）＝ `specs/general/entry-doc.adoc`；
#   工序侧（入口文档里具体写哪几条路径、落点长什么样）＝ 公共入口「安装与更新」。
# 缺这两句声明时，两边"你抄我一段、我抄你一段"的重写会重新长出来（本仓库实测：入口模板
# 与 entry-doc.adoc 曾逐句重复"唯一持久化产物/会话结束就丢"的整段，改一处必漏另一处）。
ENTRY_DOC_SINGLE_SOURCE_MARKERS = (
    ("本文件是这一判据的**唯一真源**", "判据侧（entry-doc.adoc）缺『本文件是唯一真源』声明——"
     "不声明则可被别处再复述一遍，两处必然各自漂移"),
    ("本文件不抄那几条路径的字面值", "判据侧缺『工序字面值不在本文件』声明——"
     "不声明则本文件可再抄一份路径，与入口打架"),
    ("那是唯一真源", "工序侧（公共入口）缺『写入判据的真源在 entry-doc.adoc、"
     "本文件不重复其条文』这句——不声明则『该不该写』只能在本文件里再写一套，"
     "两处必然各自漂移"),
)


def check_entry_doc_manifest():
    """『入口文档持久化防线』：入口文档须给"隔一次会话还认得回来"的清单。

    背景（用户点名的形态）：安装流程会把入口文档落到目标项目，它是**唯一持久化到项目里的
    产物**——一次会话结束后，下一个会话（或另开的新实例）只能看到落到项目里的文件。原先的
    入口占位只写"入口地址 + 遵守要求"，于是"规范副本落在哪、怎么再取一次"只存在于本人会话里，
    新开实例即丢失（用户原话："放其他地方新开实例就丢了"）。

    故本检查核两处，互不替代：
      * **判据真源**（`specs/general/entry-doc.adoc`）：最小集（规范入口、取规范脚本路径、
        副本检索路径、取回与更新方式、跨会话保留信息）与『与临时产物的分界』必须写在那里
        ——"该不该写"由它管。
      * **入口模板**（`AGENTS_COMMON.adoc`「安装与更新」）：只核**路径链与副本两要点**
        （路径齐、落点写到具体那一处、取回方式齐），**不核模板的小节结构**——模板写成什么样**以用户手工编辑
        的形态为准**（用户已点名不要 `= Agent 规范入口` 标题与那三节；曾经核过，结果是把
        用户删掉的三节又"补"了回去）。核字面值时"措辞精炼"与"判据被换成笼统说法"分不开，
        故按要点核：只拦"笼统说法/缺路径"，不拦写法优化。
    """
    phase("入口文档持久化防线检查（入口文档清单）")
    spec_path = os.path.join(REPO_ROOT, *ENTRY_DOC_SPEC.split("/"))
    if not os.path.isfile(spec_path):
        err(f"缺少 {ENTRY_DOC_SPEC}——入口文档的最小集（规范入口、副本检索路径、取回与更新"
            "方式、要跨会话保留的本项目信息）与『与临时产物的分界』无处承载，"
            "执行者只能凭印象决定『什么该写进入口文档』", ENTRY_DOC_SPEC)
    else:
        spec_text = open(spec_path, encoding="utf-8").read()
        for key, desc in (
                ("唯一", "须写明入口文档是『唯一持久化到项目里的落点』"
                         "（否则会被当成装完即弃的产物）"),
                ("新实例", "须写明判据的另一半：会话结束后只有落到项目里的文件会被读到"),
                ("临时产物", "须写明入口文档与临时产物的分界（临时产物按 tmp/ 约定、不进入口文档）"),
                ("项目自身规范优先", "须写明项目自身内容优先、不因重新执行安装被改写")):
            if key not in spec_text:
                err(f"入口文档持久化防线被破坏：{ENTRY_DOC_SPEC} 缺失『{key}』——{desc}",
                    ENTRY_DOC_SPEC)
    # 「判据与工序分家」：同一件事的两半各有**唯一落点**，两边都须声明"我只说这一半、
    # 另一半去别处读"——不声明则可被再复述一遍（本仓库实测：入口模板与 entry-doc.adoc
    # 曾逐句重复整段，改一处必漏另一处）。
    if os.path.isfile(spec_path):
        spec_text = open(spec_path, encoding="utf-8").read()
        for key, desc in ENTRY_DOC_SINGLE_SOURCE_MARKERS[:2]:
            if key not in spec_text:
                err(f"入口文档持久化防线被破坏：{desc}", ENTRY_DOC_SPEC)
    if not os.path.isfile(INSTALL_FILE):
        err(f"缺失 {INSTALL_REL}——入口文档模板不在，入口文档清单无从核对", INSTALL_REL)
        phase_done()
        return
    install_text = open(INSTALL_FILE, encoding="utf-8").read()
    if ENTRY_DOC_SINGLE_SOURCE_MARKERS[2][0] not in install_text:
        err(f"入口文档持久化防线被破坏：{ENTRY_DOC_SINGLE_SOURCE_MARKERS[2][1]}",
            INSTALL_REL)
    with open(INSTALL_FILE, encoding="utf-8") as fh:
        lines = fh.readlines()
    sec_i = _section_line_index(lines, "安装与更新（引用方接入与取回口径）")
    delim = [i for i, l in enumerate(lines)
             if l.strip() == "----" and (sec_i is None or i > sec_i)]
    if sec_i is None or len(delim) < 2:
        err(f"{INSTALL_REL} 未找到「安装与更新」节的入口模板代码块定界符 `----`（需一对）——"
            "入口文档的清单无处承载", INSTALL_REL)
        phase_done()
        return
    body = "".join(lines[delim[0] + 1:delim[1]])
    # 用户口径（本 PR 反复确认）：入口模板**以用户手工编辑的形态为准**——模板里不要
    # `= Agent 规范入口` 标题、也不要「规范与安装文档的位置 / 规范副本的位置 / 本项目
    # 持久化到入口文档的信息」这三节；故本防线**不核模板里有没有这三节**（曾经核过，
    # 结果是把用户删掉的三节又"补"了回去，等于拿机械判据盖掉用户的手工编辑）。
    # 最小集这条要求本身并未放弃：它是 `specs/general/entry-doc.adoc` 的判据真源
    # （该文件的『最小集』一节 + 上面已核的『唯一真源』声明），入口文档该写什么由它管，
    # 模板写成什么样由用户定。
    #
    # 仍留在模板里的、必须核到的**要点**（不依赖小节标题，按正文核）：
    #   * 路径链（规范入口 / 取规范脚本）——新实例要能一站直达；
    #   * 副本落点（用户侧词 + 落点名同现）与取回/更新方式——新实例据此定位副本。
    # 判据按**要点**核、不核某一种写法的字面值（措辞精炼不该报红，笼统说法才该报红）。
    for key, desc in ENTRY_DOC_PATH_POINTS:
        if key not in body:
            err(f"{INSTALL_REL} 入口模板缺失 {key}——{desc}；入口文档要能一站直达这些路径，"
                "缺一条时新实例就不知道该去哪儿重装/更新/怎么下载规范"
                "（用户实测点名：取规范脚本没进入口文档）", INSTALL_REL)
    if LANDING_NAME not in body or not any(k in body for k in HOME_WORDINGS):
        err(f"{INSTALL_REL} 入口模板未写明副本落点"
            "（用户家目录/用户路径下的 `.cache/agent-specs`）——新实例是靠模板里这一处去定位"
            "副本的，只写『用户级缓存』这类笼统说法时它仍要猜路径；判据是用户侧词"
            f"（{list(HOME_WORDINGS)} 之一）与 `{LANDING_NAME}` 同现，"
            "只出现其中一个时该要求已被换成别的说法，机械判据随之空转", INSTALL_REL)
    for keys, desc in ENTRY_DOC_COPY_POINTS:
        if keys is HOME_WORDINGS:
            continue  # 落点已单独核过
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"{INSTALL_REL} 入口模板缺失 {missing}——{desc}；"
                "副本位置是新实例按入口文档定位规范的唯一线索，缺一项即只能重新手工下载一遍",
                INSTALL_REL)
    phase_done()


# 安装流程的**幂等更新**那一处的判据要点（`AGENTS_COMMON.adoc`「安装与更新」的
# 「本流程可重复执行、且以远程为准」一条——安装口径已并入公共入口，节名随之变化）。
# 背景（本仓库实证）：模板与安装流程的分工是"机械判据按模板核、人不按模板被机械改回"——
# 上一轮实施把用户手工删掉的标题与三节**按判据恢复**了回去，等于拿机械判据盖掉人的手工编辑
# （用户点名："我手动删的，你不要给我补上去"）。只在脚本注释里写这句"以用户手工编辑为准"
# 挡不住下一次：实施者照 `AGENTS_COMMON.adoc` 读流程，读到的仍是"与模板不一致就地更新为最新模板"。
# 故把这条**工序判据**落到安装流程里，并机械钉住——缺它时"拿机械判据盖掉人工编辑"会重演。
REPEAT_UPDATE_POINTS = (
    ("以用户改过的为准",
     "安装流程须写明：**用户手工编辑过的模板内容一律照原文保留**、不符合本模板时"
     "**不自动改回**、只在汇报里指出不一致等用户定——"
     "缺这句时实施者按『与最新模板不一致就地更新』把人的手写改回模板，"
     "正是本仓库实测过的形态（用户点名：『我手动删的，你不要给我补上去』『以我的为准』）"),
    ("不自动改回",
     "同一条须写明**不自动改回**这个动作本身——只说『以用户为准』而没有『不改回』时，"
     "实施者仍可把『按模板修正』读成对用户有利而照做"),
    ("等用户定",
     "同一条须写明不一致时的**正当处置**（汇报里指出、等用户定）——"
     "只说『不自动改回』会让人把它读成『什么都不说』，用户就不知道入口文档与模板已不一致"),
)


def check_install_repeat_update_guard():
    """『安装幂等更新防线』：安装流程须写明"用户手工编辑过的模板内容不自动改回"。

    判据本体：`AGENTS_COMMON.adoc`「安装与更新」的幂等更新一条不得只说"与最新模板不一致即
    就地更新为最新模板"——入口文档是**用户项目的文件**，用户改过的行按用户改过的原文保留，
    不一致时汇报、等用户定（见 `specs/general/scope.adoc`「只改当前工作空间」与「拒绝的形态」：
    未获用户声明时，"按模板修正"同样是把改动落到用户的文件上）。

    本函数只核**文本要点**（某次安装是否真的没改回用户的手写属运行时行为，交人/子 agent 复核）。
    """
    phase("安装幂等更新防线检查（用户手工编辑不得被模板盖掉）")
    rel = INSTALL_REL
    path = os.path.join(REPO_ROOT, rel)
    if not os.path.isfile(path):
        err(f"缺失 {rel}——安装流程不在，幂等更新的一条无从核对", rel)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = ""
    m = re.search(r"(?ms)^\* \*\*本流程可重复执行、且以远程为准\*\*：.*?(?=^== |\Z)", text)
    if not m:
        # 兼容：该条也可能被写成独立的三级节
        m = re.search(r"(?ms)^=== 本流程可重复执行.*?(?=^== |\Z)", text)
    if m:
        section = m.group(0)
    if not section:
        err(f"{rel} 未找到「本流程可重复执行、且以远程为准」一条——幂等更新的判据无处承载；"
            "缺该条时『与模板不一致就地更新』这条会孤立地生效，用户的手工编辑必被改回", rel)
    else:
        for key, desc in REPEAT_UPDATE_POINTS:
            if key not in section:
                err(f"{rel}「本流程可重复执行、且以远程为准」缺失『{key}』——{desc}", rel)
    phase_done()


# ---- 『防线清单与删除记账』的基线（改了就报红，逼"删了什么"留下痕迹）----
# 三道数字都是**本仓库自身的记账**，不是规范判据：
#   * 接线数：`CHECKS` 序列里编排的 `check_*` 个数。删除/摘出一道防线曾经"零痕迹"
#     （本轮实测：一道防线被从执行序列摘掉、它的 8 条反例用例也被删，而
#     `check_specs.py` 与全部单测仍然全绿、台账上的"抓手数"也不变）；
#     注意：这里的"接线数"是**序列元素个数**，而 `check_guard_manifest` 实际比对的是
#     **可达闭包**（序列 + 被别的防线收尾调用的，如公共内容自足两道）——两者当前是
#     93 与 95。基线只作"不得无记账减少"的下限，故取序列元素个数即可（更保守）。
#   * 用例数：全部 `*_test.py` 里的 `def test_` 个数（`check_specs_test.py` +
#     `check_effective_test.py` 的实际总数）。反例用例是防线的实际效力来源，被整批删掉时
#     数字会掉；基线须与这里**实取的总数**同源（它同时含 check_effective_test.py，
#     写成"只数 check_specs_test.py"会让基线长期低于实际数——本仓库实测：基线 974、
#     总数 985，删掉十余条用例都不会掉到线下）；
#   * 台账函数名：`check_effective.py` 必须**逐条声明**这条规范由哪一道防线钉住——该防线
#     须**真实存在**且**真的会被调用**（"定义了但没人调"的防线看起来还在、却永远不会执行）。
#     台账是"哪条规范由谁钉住"的唯一视图；旧判据只核"备注里点名的名字存在"，**没点名就
#     没核对**，于是"有抓手"这个数字可以靠把防线名删掉维持（删名字比删防线容易得多）。
# 两份基线的**口径**与取值（上面那条注释已点出"与实取总数同源"的要求，此处给本次的记账）：
#   * 用例数口径＝`script/` 下全部 `*_test.py` 的**真实收集**用例数相加（`类名.用例名`
#     限定名去重，见 `check_guard_manifest`）。旧值 995 只对得上"加了 3 条的那一时点"，此后
#     `check_effective_test.py` 被并入计数而未回填，故**长期低于实际数**——本仓库实测：
#     基线 995、实际 998，删掉 3 条用例仍不报红。本次一次性把**口径回填**与**本轮增删**记全：
#     接线数 92→91、反例用例数 1029→1012（该防线的 19 条反例一并删除），此后**净增 15 条**，
#     故终值为 **1013 = 1029 - 19 + 3**（口径统一后逐条相减：删除账 19 条，本 PR 新增 3 条）
#     ——两种口径的记账都留在此处，读者的每一条都能对得上（原先"1013 = 966 + 32 + 15"的
#     算式用的是改动前单文件口径 966，与 1029 的差别在于是否把 `check_effective_test.py` 的
#     32 条计入；两种算法指向同一集合，故终值同为一千零一十三）。
#     同一次里另处理了**两处同名覆盖**（同一测试类里重名的后一个会静默覆盖前一个、那条
#     反例从未执行）：`TestCheckPerformanceGuard` 一处逐字重复删掉一条、
#     `TestCheckRenameSplitGuard` 一处改名（两条并成一条且补足反例构造），故净增是按处理
#     同名覆盖**之后**的数算的。
#   * 接线数口径＝`CHECKS` 序列（`_guard_wiring_count`）。基线 90 是 2026-09 把编排从
#     `main()` 改成序列**之前**定的（旧口径 86），本次按同源口径回填为 91；本轮删除
#     `check_orm_boundary_guard`（原第 69 道）、新增 `check_java_serial_guard` 与
#     `check_maven_parallel_guard`，三笔在同一序列里一进一出，终值同为 `91`。
#     删除原因与承接方见 `specs-project-maintainer/guards.adoc`「已删除的防线（删除记账，
#     按次序留档）」；新增两条见同表第 90、91 行。
#   * **本次合并记账（两侧一并保留）**：上游那笔「删除 `orm_boundary` + 新增两条」与
#     本分支那笔「新增 `check_toolchain_present_guard`」在同一序列里各记一次，故终值为
#     **93 = 91 + 1（本分支新增校验工具链齐备）+ 1（此前 rebase 已含的并行度防线）**——
#     两笔都不得丢：`CHECKS` 里 `check_java_serial_guard`、`check_maven_parallel_guard`、
#     `check_toolchain_present_guard`、`check_asciidoctor_syntax` 四道同时在序。
#     用例数同源取实测（`check_specs_test.py` + `check_effective_test.py` 的 `test_*` 方法数）：
#     本分支初版记 1021，复核（d3209b8）又补了 CI 侧的例外形态用例；上游与两侧合并后
