#     * 接线数 **96(两侧) → 97**：本分支的 `check_rule_script_separation_guard` 与 main 的
#       `check_entity_dto_guard` / `check_java_interface_accessor_guard` / `check_alter_merge_guard`
#       各类一道，在 `CHECKS` 序列里各占一个位置，一道都不丢；清单表同步为 97 行、
#       编号 1..97 连续，与 `CHECKS` 逐一同序。
#     * 用例数 **1106 / 1085 → 1150**：两侧用例都保留后同源实测
#       （口径＝`script/` 下全部 `*_test.py` 的 `test_*` 方法数逐条相加）——只允许"不低于实测"。
# **本轮（规则文件格式换成 TOML）**：用户口径"配置文件格式换成 toml"。接线数与防线数不变
# （97）；用例数 1150 → 1151（`rules_engine_test.py` 净增 1 条：TOML 同名表头由语法直接拒绝
# 的反例；另有 3 条随格式改名/改写：纯 TOML 校验、非法 TOML 报错、合法 TOML 读入）。
# 判据侧新增一处确定项：`script/specs-rules/` 下须存在 `*.toml`（换回别的格式即报红）。

#   **本轮（Issue #169 模板类内容单独归类）**：新增 `check_template_separation_guard`（用户口径：
#   "要么不读、要么读全部的规范（如代码模板）不要和其他内容放一起、各自独立（除非有关联性或
#   内容不多拆开反而麻烦）"）——判据本体落**维护方自查层**
#   `specs-project-maintainer/spec-lifecycle.adoc`「要么不读、要么读全部的规范」（它描述的是
#   "规范集合自己怎么组织"，对引用方项目不成立），`AGENTS.adoc` 登记该落点、
#   `specs/general/context.adoc`「生成效率」留公共侧一跳引用。两个基线与 `guards.adoc` 清单表
#   均按**同源实测**回填（`check_template_separation_guard` 排在 `check_toolchain_present_guard`
#   与 `check_asciidoctor_syntax` 之间）：清单表同步追加一行、编号连续且与 `CHECKS` 逐一同序。
#   **数值不在本注释复述**——接线数与用例数分别以 `GUARD_WIRING_BASELINE`、
#   `GUARD_TEST_BASELINE` 为唯一真源（复述一份即第二处会各自漂移）。
#   规则数据一类一个文件：新增 `script/specs-rules/template.toml`（引擎按目录自动扫描，
#   脚本不登记文件名）。


def _read_ledger_no_grip_declared():
    """从台账 `script/check_effective.py` 读出「无机械抓手」的声明措辞（唯一真源）。

    常量定义在使用侧、校验侧引用——两处各写一份字面值正是本条要防的"两处真源"。
    读不到时退回字面值（台账整体缺失由各自的文件存在性检查兜住）。
    """
    text = _read_script_src("script/check_effective.py") or ""
    m = re.search(r'(?m)^NO_GRIP_DECLARED = "([^"]+)"', text)
    return m.group(1) if m else "无机械抓手"


# 台账逐条声明抓手的**唯一合法形态**：有抓手条目在 `note` 里用反引号包起具体那一道
# `check_*_guard`；无抓手条目显式声明为 `NO_GRIP_DECLARED`。
LEDGER_GRIP_DECLARED_GUARD = re.compile(r"`(check_[a-z0-9_]+_guard)`")
# 「无机械抓手」的唯一合法声明措辞：定义在台账侧（`script/check_effective.py`）——
# 常量须在使用侧，校验侧引用它，避免两处各写一份字面值（正是本条要防的"两处真源"）。
NO_GRIP_DECLARED = _read_ledger_no_grip_declared()


def _checks_block(src: str) -> str:
    """取 `CHECKS = (...)` 序列块的正文（`CHECKS` 是防线执行次序的唯一来源）。"""
    m = re.search(r"(?ms)^CHECKS = \((.*?)^\)", src)
    return m.group(1) if m else ""


def _guard_wiring_names(src: str) -> list:
    """取 `CHECKS` 序列里的防线名（**唯一来源是序列，不是 `main()` 的正文**）。

    口径刻意取窄：只认序列里以 `check_xxx,` 起行的元素——嵌套调用（如
    `check_adoption_guard` 内部再调的公共内容自足两道）属同一道防线链，不重复计数。
    为什么不再按 `main()` 正文数：那里一旦改成 `for check in CHECKS()` 就文本上数不到，
    而把接线判据绑在"`main()` 里怎么写的"上，等于让改一次编排写法就把全部防线误报成
    "没人调用"。序列是数据：数它与 `main()` 怎么执行它无关。

    **保留重复项**（不去重）：重复登记本身要被报出来，调用方按需 `set(...)` 取唯一数。
    """
    return re.findall(r"(?m)^ {4}(check_[a-z0-9_]+),$", _checks_block(src))


def _guard_wiring_count(src: str) -> int:
    """数 `CHECKS` 序列里**唯一**的防线个数（重复登记不得用来凑够条数）。

    重复项不承载任何新判据（同一道防线跑两遍，`run_rule_guard` 还按阶段去重、第二次
    直接跳过），故它**不得**被计入接线数——否则"删掉一道真防线 + 把另一道重复登记一遍"
    能让条数不动、把删除掩盖过去（本仓库实证形态，见 `check_guard_manifest`）。
    """
    return len(set(_guard_wiring_names(src)))


def _module_level_fn_body(src: str, name: str) -> str:
    """取**模块级** `def name(` 的函数体（自函数名起，到下一个模块级 `def` 行止）。

    "下一个 `def` 行"必须是**行首无缩进**的：嵌套里的 `def` 缩进在函数内，按 `def` 裸匹配
    会在第一个内层 `def` 处截断，把该函数剩余部分的调用漏掉。定义在文件里的**最后**一个
    模块级函数没有后继 `def`，此时才取到文件尾。
    """
    mm = re.search(r"(?m)^def " + re.escape(name) + r"\(", src)
    if mm is None:
        return ""
    start = mm.end()
    nxt = re.search(r"(?m)^def ", src[start:])
    return src[start:start + nxt.start()] if nxt else src[start:]


def _guard_wired_closure(src: str) -> set:
    """算出**真的会被执行**的防线集合（`CHECKS` 序列 + 其函数体内可达的调用）。

    只看序列会把"被别的防线带着跑的"误判成未调用（本仓库实证形态：
    公共内容自足两道由 `check_adoption_guard` 收尾调用）。故按可达闭包展开，
    与 `check_wiring_guard` 的口径一致——两处若各写一套，会出现"接线的说跑了、
    台账的说没跑"的矛盾结论。

    **判据不得依赖防线在文件里的先后**：函数体的取法只到**下一个模块级 `def`** 为止，
    不得因"写在前面的函数恰好定义在后面"而不同（否则把一道防线挪到前面，就会让它体内
    对后续函数的调用被算成"可达"——而它与序列无关）。
    """
    wired = set(re.findall(r"(?m)^ {4}(check_[a-z0-9_]+),$", _checks_block(src)))
    frontier = list(wired)
    while frontier:
        body = _module_level_fn_body(src, frontier.pop())
        for name in re.findall(r"\b(check_[a-z0-9_]+)\(", body):
            if name not in wired:
                wired.add(name)
                frontier.append(name)
    return wired


def _ledger_args(raw: str) -> list:
    """把台账条目的实参切开（字符串参数取正文、裸 `None` 取 `None`）。

    台账条目的实参形态只有两种：双引号字符串与裸 `None`。故按括号内的顶层逗号切分，
    逐段判形态即可——不必上解析器，也不受"字符串里出现逗号"影响（按引号配对切）。
    不能只 `findall` 字符串：`grip=None`（无抓手条目的唯一合法写法）没有引号，
    直接按字符串切会把第 4 段的声明当成 grip，于是无抓手条目被判成"没声明"。
    """
    inner = raw.strip()
    inner = inner[inner.index("(") + 1:inner.rindex(")")]
    args, buf, in_str, esc = [], "", False, False
    for ch in inner:
        if esc:
            buf += ch
            esc = False
            continue
        if ch == "\\" and in_str:
            esc = True
            buf += ch
            continue
        if ch == '"':
            in_str = not in_str
            buf += ch
            continue
        if ch == "," and not in_str:
            args.append(buf.strip())
            buf = ""
            continue
        buf += ch
    if buf.strip():
        args.append(buf.strip())
    out = []
    for a in args:
        if len(a) >= 2 and a.startswith('"') and a.endswith('"'):
            out.append(a[1:-1])
        elif a == "None":
            out.append(None)
        else:
            out.append(a)
    return out


def _ledger_entries() -> list:
    """从 `check_effective.py` 的 `MECHANISMS` 里取出每条台账条目。

    返回 `[(条款名, 抓手路径或 None, 备注, 声明的防线名集合, 声明的原文)]`——
    "声明的防线名"只认**条目第 4 段**（逐条声明），不认备注里的裸词：备注里的名字
    可能是说明文字、也可能是反例引用，靠它推断"由谁钉住"正是旧判据漏检的原因。
    取不到台账时返回空列表（台账整体缺失由各自的文件存在性检查兜住）。
    """
    text = _read_script_src("script/check_effective.py")
    if not text:
        return []
    m = re.search(r"(?ms)^MECHANISMS = \[(.*?)^\]", text)
    if not m:
        return []
    body = m.group(1)
    # 条目按 "行首 4 空格 + ( " 切开（台账是逐条一行起的列表，字符串里不含该形态）
    marks = [mm.start() for mm in re.finditer(r"(?m)^ {4}\(", body)]
    entries = []
    for k, start in enumerate(marks):
        raw = body[start:marks[k + 1] if k + 1 < len(marks) else len(body)]
        args = _ledger_args(raw)
        if len(args) < 3:
            continue
        grip = args[2]
        if len(args) < 5:
            # 旧形态（只有四段）＝尚未逐条声明抓手：按"没声明"处理，由检查方报错
            entries.append((args[0], None if grip is None else grip,
                            "".join(a for a in args[3:] if a), set(), ""))
            continue
        grip_name = args[3]
        declared = set()
        if grip_name and grip_name != NO_GRIP_DECLARED:
            declared = {grip_name}
        entries.append((args[0], None if grip is None else grip,
                        "".join(a for a in args[4:] if a), declared, grip_name))
    return entries


def _test_cases(module_name: str, src: str) -> list:
    """把一个测试文件里的用例算成**唯一可标识的清单**：`[(类名, 用例名, 该用例正文)]`。

    **口径必须与 CI / 实际执行同源**：`.github/workflows/check-specs.yml` 跑的是
    `python3 -m unittest discover -s script -p '*_test.py'`，收集面＝**模块级**
    `TestCase` 子类的一层缩进 `test_*` 方法 + 顶格 `test_*` 函数。

    为什么"数 `def test_` 的个数"这个口径不成立（**本仓库本轮实测**，两处都会误判）：

    * **数重**：`^\s+def (test_...)` 里 `\s` 会匹配到**换行**，于是同一个 `def` 会被它
      所在行与其上一行的空白各命中一次——本仓库实测 `check_specs_test.py` 的 `1165`
      里有 `1155` 是这种重复命中，真实 `def test_` **只有 1165 行、980 个不同名字**。
      这不是"用例数"，是"正则命中数"。
    * **同名不可区分**：用例名在**同一个文件里跨类复用**（实测 `test_valid_passes`
      在 `check_specs_test.py` 出现过 28 次、`test_missing_file_reports` 13 次）。
      只记名字时，"类 A 的 `test_valid_passes` 被删、类 B 的同名用例仍留"这个动作
      **看不见**——名字还在集合里、计数也够，读者却会以为那条反例还钉着。

    故清单按**类路径限定**给出（`类名.用例名`）：增删到"哪一个类里的哪一条"上。
    缩进层级按 `def` 前的空白判，不按正则数 `def test_`——只有一层缩进（直接写在模块级
    `class` 体内）与顶格（模块级函数）会被收集；坐在模块级 `if __name__ == "__main__":`
    块里、仍缩进两层的 `def test_` 是**块内局部函数**：源码里"看得到"、运行时永远收集不到
    （本仓库实测失效形态，见 `check_guard_manifest` 的入口块判据）。
    """
    lines = src.splitlines(keepends=True)
    cls = None
    cases = []
    heads = []  # (行号, 限定名)
    for idx, line in enumerate(lines):
        mc = re.match(r"(?P<indent>[ \t]*)class ([A-Za-z_][A-Za-z0-9_]*)\b", line)
        if mc:
            indent = mc.group("indent").expandtabs(4)
            cls = mc.group(2) if indent == "" or len(indent) == 4 else None
            continue
        md = re.match(r"(?P<indent>[ \t]*)def (test_[A-Za-z0-9_]+)\(", line)
        if not md:
            continue
        indent = md.group("indent").expandtabs(4)
        if indent == "":
            heads.append((idx, md.group(2)))
        elif len(indent) == 4 and cls:
            heads.append((idx, f"{cls}.{md.group(2)}"))
    if not heads:
        return []
    # 同层级的下一个定义（含装饰器）＝本条用例那一节的结束位置
    stops = []
    for idx, line in enumerate(lines):
        m = re.match(r"(?P<indent>[ \t]*)(?:(?:def|class) [A-Za-z_]|@)", line)
        if not m:
            continue
        indent = m.group("indent").expandtabs(4)
        if indent == "" or len(indent) == 4:
            stops.append(idx)
    for idx, qualified in heads:
        after = [d for d in stops if d > idx]
        end = after[0] if after else len(lines)
        cases.append((qualified, "".join(lines[idx:end])))
    return cases


def _has_any_assertion(body: str) -> bool:
    """这一节里有没有任何断言（含 `self.assert*` / 裸 `assert` / `self.fail` / `skipTest`）。

    只判"有没有"，不判断言对不对——后者是语义判断（见 `GUARD_CHECK_LIMITS`）。
    YAML/文本夹具里出现的 `assert` 字样会误判成正例（放行），这是刻意的：本判据的
    假阳性会误伤真实用例，故宁可窄（只拦"整节一条断言都没有"的确定性空壳形态）。
    """
    return bool(re.search(r"\bassert[A-Za-z_]*\b|\bself\.fail\b|\bskipTest\b|pytest\.raises", body))


def _collectable_test_names(module_name: str, src: str) -> set:
    """**会被收集**的用例限定名集合（`类名.用例名`，模块级函数用裸名）。"""
    return {q for q, _ in _test_cases(module_name, src)}


def _count_collectable_tests(module_name: str, src: str) -> int:
    """**会被收集**的用例条数（按唯一限定名去重，见 `_test_cases`）。"""
    return len(_test_cases(module_name, src))


def check_guard_manifest():
    """『防线清单与删除记账』：防线的增删必须留下痕迹，清单本身的描述必须与实际一致。

    背景（本轮实测复现的三桩"删了却全绿"）：①一道防线被从执行序列摘掉、它的 8 条
    反例用例一并被删，`check_specs.py` 报 OK、单测全通过、"抓手数"也没变；②台账
    `script/check_effective.py` 的备注里点名的防线名改成不存在的名字（`check_THIS_GUARD_IS_GONE`）
    仍报"有抓手"——判据只看文件在不在；③脚本头部清单出现断号（条目被删）无人核对，
    而"有抓手"这个数字可以靠改注释维持。

    故本检查把三件事变成可核对的：**接线数**（不得减少）、**反例用例数**（不得减少）、
    **台账点名的防线名**（必须真实存在且真的会被调用）。数字变了就得改基线——
    改基线这个动作本身让"删了什么"在 diff 里可见。
    """
    phase("防线清单与删除记账检查")
    src = _read_script_src("script/check_specs.py")
    if src is None:
        err("缺失 script/check_specs.py——防线清单本体不在，接线数与台账都无从核对",
            "script/check_specs.py")
        phase_done()
        return

    wiring = _guard_wiring_count(src)
    if wiring < GUARD_WIRING_BASELINE:
        err(f"防线接线数从基线 {GUARD_WIRING_BASELINE} 减到 {wiring}——**每摘掉一道防线都要留下"
            f"记账**：说明「删的是哪一道、为什么删、由谁承接」，并把 `GUARD_WIRING_BASELINE` "
            "改成新值（改基线这个动作让删除在 diff 里可见）。不记账就减数＝防线静默消失"
            "（本仓库实测：一道防线被摘出执行序列后，脚本与全部单测仍全绿）",
            "script/check_specs.py")

    # **重复登记**：同一道防线在序列里出现两次以上——重复项不承载任何新判据，
    # 却能把接线数凑够、掩盖"真防线被删掉一道"（删掉的那道由重复项顶上，条数不掉）。
    # 本仓库实证形态：`check_pagination_guard` 在序列里一次、末尾又追加一次。
    # 防法是**两道**：① `_guard_wiring_count` 按唯一名计数（重复项不计入），
    # 故"重复 + 少一道"必然低于基线、被上面的核对拦下；② 这里再把重复本身报出来，
    # 让"手滑写重了"这个动作在 diff 之外也有一处可核对的报错。
    seq_names = _guard_wiring_names(src)
    dup_names = sorted({n for n in seq_names if seq_names.count(n) > 1})
    if dup_names:
        err(f"`CHECKS` 序列里出现**重复登记的防线** {dup_names}——重复项不承载任何新判据"
            "（同一道防线跑两遍，规则还按阶段去重、第二次直接跳过），**不计入唯一防线数**；"
            "它会把条数凑够、掩盖\u201c真防线被删掉一道\u201d。"
            "**改基线不算记账**——重复项不构成一道防线，把 `GUARD_WIRING_BASELINE` 改成"
            "含重复项的值只会把这条掩盖固化下来。请删掉重复项本身，并在 "
            "`specs-project-maintainer/guards.adoc` 清单表里同步删掉对应的重复行"
            "（清单表的重复行由 `check_guard_order_guard` 的逐一同序核对报出）",
            "script/check_specs.py")

    # "定义了但没人调"的防线：看起来还在（函数体完好、台账也点了名），但永远不会执行。
    # 判据按**接线闭包**算（与 `check_wiring_guard` 同口径）——被别的防线带着跑的不算
    # 未接线（本仓库实证形态：公共内容自足两道由 `check_adoption_guard` 收尾调用；
    # 若按"全文件任何地方调过"判，它们就成了"没人调"的假报）。
    reachable = _guard_wired_closure(src)
    defined_names = set(re.findall(r"(?m)^def (check_[a-z0-9_]+)\(", src))
    dead = sorted(set(re.findall(r"(?m)^def (check_[a-z0-9_]+)\(", src)) - reachable)
    if dead:
        err(f"存在**已定义但任何地方都没被调用**的防线函数 {dead}——它们看起来还在"
            "（函数体完好、台账也点了名），但永远不会执行；要么接线、要么删掉并记账",
            "script/check_specs.py")

    # 用例数口径：`script/` 下**全部** `*_test.py` 里**真正被执行**的 `test_*` 用例数
    # 逐条相加（与"防线放在哪个文件"无关——新增一个测试文件时该数随之增长）。
    #
    # 口径为什么必须是"真实执行"而不是"源码里写了几个 `def test_`"（本仓库实证失效）：
    # 旧实现按源码正则 `^\s+def (test_...)` 数，数的是「**写在那里的** `def test_`」；
    # 而 CI 与实际执行走 `python3 -m unittest discover`（`.github/workflows/check-specs.yml`），
    # 数的是「**真正被 collect 到的**用例」。两者一旦不等，"自证"与"被证明"就不是同一个数。
    # 实测（本仓库，`main` 上）：在测试文件末尾的 `if __name__ == "__main__":` 块**之后**
    # 注入一个仍缩进 4 的 `def test_`（源码正则数得到、`unittest` 收集不到）：
    #   * 源码正则口径 → 比基线**高**，故"用例数减少"不报红；单测照旧 `Ran 1277 tests ... OK`；
    #   * `check_specs.py` 只报"缺 AsciiDoc 处理器"一条环境错误，**基线防线全程未报红**。
    # 同根因的历史实证（本仓库祖先提交 `8802613`）：`unittest.main` 被写在文件**中段**，
    # 其后 2 个测试类从未进入 `main()`，`Ran 897 tests` 而源码有 899 个 `def test_`——
    # 2 条反例被静默吞掉、脚本与基线全绿（那正是本条自己点名的最高危形态）。
    tests = 0
    script_dir = os.path.join(REPO_ROOT, "script")
    if os.path.isdir(script_dir):
        for fn in sorted(os.listdir(script_dir)):
            if not fn.endswith("_test.py"):
                continue
            src_i = _read_script_src(f"script/{fn}") or ""
            tests += _count_collectable_tests(fn, src_i)
    if tests < GUARD_TEST_BASELINE:
        err(f"防线反例用例数从基线 {GUARD_TEST_BASELINE} 减到 {tests}——**反例用例是防线的"
            "实际效力来源**（一条防线被删时常连带删掉它的全部反例，而脚本与单测仍全绿）；"
            "确实要删就得说明删了哪些、为什么删（并同步 `GUARD_TEST_BASELINE`）。"
            "**本数是 `script/` 下全部 `*_test.py` 里真正被 `unittest` 收集到的用例数**"
            "（不是源码里写了几个 `def test_`——两者不等的形态即『写了却跑不到』，"
            f"本仓库实测：末尾 `if __name__` 块之后仍缩进的 `def test_` 源码数得到、"
            f"执行收集不到，两者当前 {tests}）；只核**数量不得减少**，"
            "同文件内改名/增删一进一出都能维持该数，故别把它读成「某条用例仍在」",
            "script/check_specs_test.py")

    # 每条用例**逐个**核对"它那一节还在不在"：只核总数存在一个已点名的空缺——
    # 同文件内"删 1 条、加 1 条"（甚至"改名"）都能维持该数，故总数过绿不代表某条用例仍在。
    # 判据是**段级**的：每个 `def test_...` 从它在模块级类体内的定义位置起、到**同一层级的
    # 下一个定义**（`def`/`class`/装饰器）或文件末尾为止，算"它那一节"；这一节里不含任何
    # 断言（`self.assert*` / `assert` / `self.fail` / `self.skipTest` 等）时，说明这条用例
    # 已被抽空成空壳——它仍在收集面内、仍占着那个数，却什么都证不了。
    # 存量空壳（`pass` 占位、靠夹具调用防线再断言的形式由上面那组原生断言覆盖）不阻断：
    # 本判据只拦"本轮新掏空的"，故基线里已存在的空壳名一并放行（见 `GUARD_EMPTY_TEST_NAMES`）。
    # 免责：机械判据只到"这一节里有没有断言"这一层；"断言还对不对得上判据"属语义判断。
    script_dir = os.path.join(REPO_ROOT, "script")
    if os.path.isdir(script_dir):
        for fn in sorted(os.listdir(script_dir)):
            if not fn.endswith("_test.py"):
                continue
            src_i = _read_script_src(f"script/{fn}") or ""
            for name, body in _test_cases(fn, src_i):
                if name in GUARD_EMPTY_TEST_NAMES:
                    continue
                if not _has_any_assertion(body):
                    err(f"用例 `{name}`（script/{fn}）的**这一节里没有任何断言**——"
                        "总数基线只保证用例数不减少，同文件内删一条加一条（或把用例掏空成"
                        "空壳）都能维持该数；被抽空的反例用例仍会被收集、仍占着那个数，"
                        "却什么都证不了。要么把断言补回去，要么说明删了哪条、为什么删"
                        "（并同步 `GUARD_TEST_BASELINE`）",
                        f"script/{fn}")

    # 测试文件不得在**中段**结束模块级代码（`if __name__ == "__main__":` 出现在中段、
    # 或在其之后仍写模块级定义）：`unittest.main()` 只跑到那里为止，其后的测试类**永远
    # 不会被 `unittest.main` 执行**——本仓库祖先提交 `8802613` 的真实形态（`unittest.main`
    # 在第 10388 行、文件共 11041 行，其后 2 个测试类，`Ran 897 tests` 而源码 899 个
    # `def test_`：2 条反例被静默吞掉，脚本与基线全绿）。
    # CI 走 `-m unittest discover` 时这些类仍会被收集，故"能否被 discover 到"这一条看不出问题；
    # 本判据钉的是**单文件自跑**（`python script/xxx_test.py`）这条路：入口块必须位于文件末尾。
    if os.path.isdir(script_dir):
        for fn in sorted(os.listdir(script_dir)):
            if not fn.endswith("_test.py"):
                continue
            src_i = _read_script_src(f"script/{fn}") or ""
            first = re.search(r'(?m)^if __name__ == ["\']__main__["\']:', src_i)
            if not first:
                continue
            tail = src_i[first.start():]
            # 入口块之后**任何缩进层级**的 `def` / `class` 都算"还有东西没跑到"：最隐蔽的
            # 形态正是"仍缩进两层"的 `def test_`（老实排到模块级反而会被 discover 收走，
            # 问题没这么隐蔽）——故这里**不要求顶格**。
            later = [m.group(1) for m in
                     re.finditer(r"(?m)^[ \t]*(?:class|def) ([A-Za-z_][A-Za-z0-9_]*)", tail[1:])]
            if later:
                err(f"script/{fn} 的 `if __name__ == \"__main__\":` 出现在**中段**——"
                    f"其后仍有模块级定义 {later[:3]}。`unittest.main()` 只跑到该块为止，"
                    "其后的测试类在单文件自跑时**永远不会执行**（本仓库祖先提交 `8802613` "
                    "的真实形态：2 条反例被静默吞掉、脚本与基线全绿）。入口块必须落在文件末尾",
                    f"script/{fn}")

    # 台账**逐条**声明：这条规范到底由哪一道防线钉住。旧实现只核"备注里点名的名字
    # 必须存在"，**没点名就没核对**——于是"有抓手"这个数字可以靠把备注里的防线名
    # 删掉来维持（删名字比删防线容易得多）。故改为**必填**：有抓手条目须点名具体那一道，
    # 无抓手条目须显式写「无机械抓手」。
    for name, grip, note, declared, grip_name in _ledger_entries():
        if not grip_name:
            err(f"台账 script/check_effective.py 的条目『{name}』**未声明抓手**——"
                "每条须在自己的条目里点名钉住它的那一件事（有抓手＝具体防线名、"
                f"无抓手＝『{NO_GRIP_DECLARED}』），否则『有抓手』这个数字可以靠删"
                "备注里的防线名维持，而读者以为还有抓手",
                "script/check_effective.py")
            continue
        if grip is None:
            if grip_name != NO_GRIP_DECLARED:
                err(f"台账条目『{name}』没抓手（`grip=None`）却声明了 `{grip_name}`——"
                    f"无抓手条目须显式声明为『{NO_GRIP_DECLARED}』，声明与实现不一致",
                    "script/check_effective.py")
            continue
        if grip_name == NO_GRIP_DECLARED:
            err(f"台账条目『{name}』声明为『{NO_GRIP_DECLARED}』、却填了抓手路径 "
                f"`{grip}`——声明与实现不一致", "script/check_effective.py")
            continue
        if not grip_name.startswith("check_"):
            # 非防线类抓手（随规范分发的工具、配套测试文件）指向的是**文件本身**：
            # 它们没有"哪一道防线"可点名，声明即该路径（须与 `grip` 一致、且文件真实存在）。
            if grip_name != grip:
                err(f"台账条目『{name}』声明的抓手 `{grip_name}` 与其抓手路径 `{grip}` "
                    "不一致——非防线类抓手只能声明文件本身，写错时读者会以为还有抓手",
                    "script/check_effective.py")
            elif not os.path.isfile(os.path.join(REPO_ROOT, *grip.split("/"))):
                err(f"台账条目『{name}』声明的抓手文件 `{grip_name}` 不存在——"
                    "台账是「哪条规范由谁钉住」的唯一视图，文件已删时读者会以为还有抓手",
                    "script/check_effective.py")
                continue
            continue
        if grip_name not in defined_names:
            err(f"台账条目『{name}』声明的防线 `{grip_name}` 在 script/check_specs.py 里"
                "**不存在**——台账是「哪条规范由谁钉住」的唯一视图，名字写错/防线已删时"
                "读者会以为还有抓手（本轮实测：把台账里的防线名改成不存在的名字，"
                "仍报『有抓手』）", "script/check_effective.py")
        elif grip_name not in reachable:
            err(f"台账条目『{name}』声明的防线 `{grip_name}` **定义了却没人调用**——"
                "它看起来还在、却永远不会执行；台账与接线两处必须同口径",
                "script/check_effective.py")

    # 脚本头部清单的编号：出现断号即说明有条目被整条删掉；出现**重号**即说明重排编号时
    # 把两条并成了同一个号（后者曾漏报：只核"有没有断号"时，重号与连通的两段编号都过）。
    # 头部 = 从文件开头到第一段可执行 import（夹具里可能没有，取不到就不核这一段）。
    cut = src.find("\nimport ")
    header = src[:cut] if cut >= 0 else src
    nums = [int(n) for n in re.findall(r"(?m)^ (\d+)[a-z]?\. ", header)]
    if nums:
        present = set(nums)
        top = max(present)
        gaps = [i for i in range(1, top + 1) if i not in present]
        if gaps:
            err(f"script/check_specs.py 头部检查项清单出现断号 {gaps}（最大编号 {top}）——"
                "条目被整条删掉时编号会断开，而清单描述**不参与一致性核对、写死不报红**"
                "（本仓库实测：把清单里某两条整条删掉，旧实现仍报绿）；"
                "删条目须连带改编号并说明，不得留下断号",
                "script/check_specs.py")
        dup = sorted({n for n in nums if nums.count(n) > 1})
        if dup:
            err(f"script/check_specs.py 头部检查项清单出现重号 {dup}——"
                "重排/插入编号时把两条并成了同一个号；本仓库实测：只核断号时不报红，"
                "而清单里编号所指的那一项会随重排**静默错位**（新增一条时把原有的那条"
                "也编成同一个号，两处指向同一编号、其后编号整体下移一位）。"
                "编号须**严格递增、不重不漏**，改编号须连带核对相邻条目",
                "script/check_specs.py")
        # 乱序：既无断号也无重号，但编号在文件里的**出现次序**不是递增的。这正是一道新防线
        # 插错位置（插在编号更小的条目之前）的形态——集合仍是 1..N 齐备，故前两条判据全过。
        # 本仓库实测：PR 把新增的第 63 条插在第 60 条之前，清单顺序成了
        # `…55, 60, 61, 62, 63, 56, 57, 58, 59`，断号与重号两条都报绿。
        disorder = next((idx for idx in range(1, len(nums)) if nums[idx] < nums[idx - 1]), None)
        if disorder is not None:
            err(f"script/check_specs.py 头部检查项清单编号乱序：第 {nums[disorder - 1]} 条之后"
                f"出现第 {nums[disorder]} 条——新条目被插到了编号更小的条目之前"
                "（断号与重号两条判据都拦不住这种形态：集合仍是 1..N 齐备，只是次序错了）。"
                "清单是给人按编号定位用的，须**按编号升序排列、与 `CHECKS`/台账的次序同源**；"
                "新增条目要插到与它次序相符的位置（本仓库实测：PR 在 #154 那条之后追加新条目时，"
                "它被插到了第 60 条之前，清单次序与防线次序脱节）",
                "script/check_specs.py")
    phase_done()


def check_link_refs():
    """校验内部文档链接 link: 的格式：须用相对路径，禁止根绝对、禁止越出仓库根。

    背景：AsciiDoc 的 link: 目标既在 IDE 里解析、也在浏览器/站点里解析。若写成
    根绝对路径 `link:/specs/...`，站点按仓库根解析看似正确，但 IDE 会把 `/` 当
    文件系统盘符根解析，导致 IDE 无法跳转；只有写相对当前文件所在目录的相对路径
    （如 `link:../general/x.adoc`）才能让 IDE 与浏览器按同一相对语义一致跳转。
    """
    phase("文档链接格式检查")
    files = collect_adoc_files()
    for i, rel in enumerate(files, 1):
        if _is_historical(rel):
            continue  # 变更历史按定义保留旧路径与旧写法，链接格式检查对它不适用
        base = _ref_base(rel)
        found_in_file = False
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                for m in re.finditer(r"\blink:([^\[]+)\[", line):
                    target = m.group(1).strip()
                    # 外部链接（带 scheme）与页内锚点（#...）除外
                    if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", target) or target.startswith("#"):
                        continue
                    if not found_in_file:
                        detail(f"  [{i}/{len(files)}] 检查 {rel}")
                        found_in_file = True
                    if target.startswith("/"):
                        err("内部链接禁止用根绝对路径（link:/specs/... 在 IDE 中会按文件系统根解析、无法跳转），"
                            f"应改为相对路径（如 link:../specs/...[]），实际为 link:{target}[", rel, j)
                        continue
                    resolved = posixpath.normpath(posixpath.join(base, target))
                    if resolved == ".." or resolved.startswith("../") or os.path.isabs(resolved):
                        err(f"链接目标越出仓库根: link:{target}[", rel, j)
    phase_done()


def _ref_titles(path: str):
    """收集一个 .adoc 文件里**可被 `link:x.adoc[]「…」` 指向的标题文本**。

    两类写法都收（引用方按其中任一种指过来都算指向真实存在的东西）：
      * **节标题**：`== 设计文档`、`=== 信息归属（同一信息只写一处）`（带 `=` 前缀）；
      * **条目名**：`* **入口语言选择（L1）**：……` —— 规范文件里大量判据是**列表条目**
        而非节，引用方更常指「某文件「某条目」」（本仓库既有大量这类引用）。

    每类都收录别名，便于按习惯省略级别/括号说明：完整文本、去掉括号后缀的简化名
    （`信息归属（同一信息只写一处）` → `信息归属`）、括号内的文字
    （`分类与懒加载（加载调度器）` → `加载调度器`）。
    `----` 代码块内的行不采集（如入口模板里被逐字复制的代码块正文并非节）。

    **历史缺陷（本轮实测）**：原实现只采集 `=` 起头的节标题，`link:a.adoc[]「某条目」`
    一律判为悬空——于是「指向条目」这种正确写法**无法通过校验、只能改成节名**。
    该缺陷会反向诱导规范改坏（把 `「入口语言选择」` 改成 `「文件头与解释器」` 只为过检）。
    """
    names = set()
    in_block = False
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            if line.strip() == "----":
                in_block = not in_block
                continue
            if in_block:
                continue
            m = re.match(r"^(=+)\s+(.+?)\s*$", line)          # 节标题
            if m:
                titles = [m.group(2)]
            else:
                m = re.match(r"\s*\*\s+\*\*(.+?)\*\*", line)   # 列表条目：`* **名称**`
                titles = [m.group(1)] if m else []
            for title in titles:
                title = title.strip()
                if not title:
                    continue
                names.add(title)
                # 条目名常带级别后缀（`（L1）`、`（L2，……）`），引用时通常省略，故收录简化名
                simple = re.sub(r"[（(].*$", "", title).strip()
                if simple:
                    names.add(simple)
                for inner in re.findall(r"[（(]([^（）()]+)[）)]", title):
                    if inner.strip():
                        names.add(inner.strip())
    return names


def _collect_section_names(path: str):
    """`_ref_titles` 的兼容别名（既有调用点与用例沿用旧名）。"""
    return _ref_titles(path)


def check_section_refs():
    """校验『{文件}「节名」』式引用指向的节真实存在（机械抓手）。

    背景：规范间常以 `link:xxx.adoc[]「某节名」` 形式引用具体小节。文件存在性由
    check_refs_exist 覆盖，但**节名是否真实存在不会被任何检查发现**——某节被改名
    后，其余文件的引用会静默悬空（check_specs.py 原先的检查死角）。本检查按
    `link:<目标>[]「<节名>」` 的写法，解析目标文件、核对节名真实存在，让『节名引用
    不悬空』成为可执行约束，规范改名/重整时自动兜住。

    同一 link 后并列多个「节名」（如 `link:x.adoc[]「A」「B」`）时**逐个校验**。
    仅校验能在仓库内解析、且目标为 .adoc 的引用；占位符/目录/外部链接跳过。
    """
    phase("节名引用存在性检查")
    files = collect_adoc_files()
    checked = 0
    intra_checked = 0
    for i, rel in enumerate(files, 1):
        if _is_historical(rel):
            continue  # 变更历史按定义保留旧节名引用，节名检查对它不适用
        base = _ref_base(rel)
        found_in_file = False
        own_names = _collect_section_names(os.path.join(REPO_ROOT, *rel.split("/")))
        with open(os.path.join(REPO_ROOT, *rel.split("/")), encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                # 匹配 `link:目标[]` 及其后连续出现的「节名」（同一行内，可并列多个）
                for m in re.finditer(r"\blink:([^\[]+)\[\]((?:\s*「[^」]+」)+)", line):
                    target = m.group(1).strip()
                    if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", target) or target.startswith(("#", "/")):
                        continue
                    if not target.endswith(".adoc") or _is_placeholder_ref(target):
                        continue
                    resolved = posixpath.normpath(posixpath.join(base, target))
                    if resolved == ".." or resolved.startswith("../"):
                        continue
                    path = os.path.join(REPO_ROOT, *resolved.split("/"))
                    if not os.path.isfile(path):
                        continue  # 文件不存在由 check_refs_exist 报告
                    names = _collect_section_names(path)
                    for sec in re.findall(r"「([^」]+)」", m.group(2)):
                        section = sec.strip()
                        if not found_in_file:
                            detail(f"  [{i}/{len(files)}] 检查 {rel}")
                            found_in_file = True
                        checked += 1
                        simple = re.sub(r"[（(].*$", "", section).strip()
                        if section not in names and simple not in names:
                            err(f"引用了不存在的节名: {resolved}「{section}」"
                                f"（该节可能已改名/删除，须同步更新引用）", rel, j)
                # 补充：『同文件「节名」』式自然语言指向——写"同文件"即声明该节在
                # 本文件内，若本文件无此节则指向悬空（check_section_refs 原先只认
                # `link:x.adoc[]「节」` 写法，拦不住这类指向；曾出现实测悬空引用）。
                for m2 in re.finditer(r"同文件「([^」]+)」", line):
                    section = m2.group(1).strip()
                    simple = re.sub(r"[（(].*$", "", section).strip()
                    intra_checked += 1
                    if section not in own_names and simple not in own_names:
                        err(f"「同文件「{section}」」指向的节在本文件不存在"
                            f"（该节可能在其他文件，须改写成 link:<文件>[]「{section}」"
                            "或就地补节）", rel, j)
    log(f"  校验 {checked} 处节名引用（含 {intra_checked} 处同文件指向）")
    phase_done()


# 『文档不得注水』的机械可判定形态（保守口径，只拦"必然成立"的形态，避免误伤
# 简短但有实质内容的条目——语义判断不在机械检查范围，由人 review 承担）。
# 占位词：整段除它之外没有任何实质内容时，才算"无实质内容的占位段"。
# 判定刻意**不含字符数阈值**——"参考：""内容为：" 这类短引导句是正常文档写法，
# 按字数判注水必然误伤；短不等于水，篇幅问题属语义判断、交人 review。
FILLER_PLACEHOLDER_WORDS = _RULES_TOKENS["FILLER_PLACEHOLDER_WORDS"]
FILLER_DUP_MIN_CHARS = 12       # 判重段落的实质字符下限（只滤掉"重复标点/符号行"，短而真实的重复条目仍应报）
FILLER_MIN_SUBSTANCE_CHARS = 4  # 段落"实质字符"下限：低于此值视为格式分隔行（如 `：`、`——`），不判注水
# 承载实质内容的行结构：列表条目、表格行、链接、块属性、注释行
MEANINGFUL_LINE_PAT = re.compile(r"^\s*(?:\*|\d+\.|\||\[|<|link:|include::)")
# 判"是否只剩占位词"时需忽略的标点与格式符
FILLER_NOISE_PAT = re.compile(r"[\s*`\-—、。，,：:；;（）()\[\]\"\'“”~…]")


def _iter_blocks(path: str):
    """按 AsciiDoc 块结构切分正文，逐块产出 (起始行号, 行列表, 是否含承载行)。

    代码块（`----` 定界）内容、节标题与块属性行不计入段落；空行分段。列表/表格等
    结构行归入所在段，并标记该段是否"含承载实质内容的行"——只有**整段都没有承载行**
    时才可能是注水段（避免把正常规则条目误判为注水）。
    """
    with open(path, encoding="utf-8") as fh:
        lines = fh.readlines()
    in_block = False
    para, start, meaningful = [], 0, False
    for i, raw in enumerate(lines, 1):
        line = raw.rstrip("\n").rstrip("\r")
        if line.strip() == "----":
            in_block = not in_block
            continue
        if in_block:
            continue
        stripped = line.strip()
        if not stripped:
            if para:
                yield start, para, meaningful
                para, start, meaningful = [], 0, False
            continue
        if re.match(r"^=+\s+", stripped) or stripped.startswith(":") or stripped.startswith("["):
            if para:
                yield start, para, meaningful
                para, start, meaningful = [], 0, False
            continue
        if not para:
            start = i
        para.append(line)
        if MEANINGFUL_LINE_PAT.match(line):
            meaningful = True
    if para:
        yield start, para, meaningful


def _para_metrics(para: list) -> tuple:
    """统计段落：去格式符后的实质字符数、条目数、是否含列表标记。"""
    texts, items, has_bullet = set(), 0, False
    for line in para:
        s = line.strip()
        if re.match(r"^\s*(?:[*]|\d+\.)\s+", line):
            has_bullet = True
            items += 1
        norm = FILLER_NOISE_PAT.sub("", s)
        if norm:
            texts.add(norm)
    return len("".join(sorted(texts))), items, has_bullet


def _placeholder_only(text: str) -> bool:
    """整段是否"只剩占位词、没有别的实质内容"。

    去掉占位词与标点、格式符后若不再剩任何字符，即判为占位段（如"此处待补充""（略）"）；
    只要还留有别的字词（"参考：""内容为：""第 3 步：略"）就不算——短引导句与
    "标题词 + 后接内容"都是正常文档写法，机械检查不得误伤。按词长从长到短去除，
    避免先去掉短词（"待补"）导致长词（"待补充"）只被去掉前缀、残留无关字符。
    """
    rest = text
    for word in sorted(FILLER_PLACEHOLDER_WORDS, key=len, reverse=True):
        rest = rest.replace(word, "")
    return FILLER_NOISE_PAT.sub("", rest) == ""


def _substance_chars(text: str) -> int:
    """段落的"实质字符"数（去掉标点/格式符后剩下的字数）。

    用于滤掉纯格式行（如 `：`、`——`、`***`）——它们既非占位也非内容，
    判注水属误报，故低于下限时不参与占位段/重复段判定。
    """
    return len(FILLER_NOISE_PAT.sub("", text))


def check_filler_docs():
    """『文档不得注水』机械兜底（只拦机械可判定、必然成立的形态）。

"""
    phase("文档注水检查")
    files = collect_adoc_files()
    for i, rel in enumerate(files, 1):
        detail(f"  [{i}/{len(files)}] 检查 {rel}")
        seen_paras = set()
        for lineno, para, meaningful in _iter_blocks(os.path.join(REPO_ROOT, *rel.split("/"))):
            text = " ".join(p.strip() for p in para).strip()
            # 0) 纯格式行（`：`、`——`、`***` 等）：无实质字符，不判注水（防误报）
            if _substance_chars(text) < FILLER_MIN_SUBSTANCE_CHARS:
                continue
            # 1) 纯占位段：整段无承载行，且除占位词外没有实质内容
            if not meaningful and _placeholder_only(text):
                err(f"疑似注水：无实质内容的占位段『{text[:30]}』"
                    "（『文档不得注水』），补上可核对的实质内容或删除", rel, lineno)
                continue
            # 2) 同段重复：逐字相同且承载实质内容的段落（凑数堆砌）——**对全部段落判重**，
            #    不只判"含列表/表格行"的段落：否则同段重复出现在节标题分隔的两处时会被漏掉
            if _substance_chars(text) >= FILLER_DUP_MIN_CHARS:
                if text in seen_paras:
                    err(f"疑似注水：与上文完全重复的段落『{text[:30]}』"
                        "（『文档不得注水』），合并去重", rel, lineno)
                    continue
                seen_paras.add(text)
    phase_done()


def check_principle_guard():
    """校验规范"要点防线"仍在（防『定义完整性校验却不执行/被意外误删』）。

"""
    phase("规范要点防线检查")
    path = os.path.join(REPO_ROOT, "AGENTS.adoc")
    rel = os.path.relpath(path, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(path):
        err("缺少 Agent 项目自身规范入口 AGENTS.adoc，无法核验『调整后须做完整性校验』要点防线是否存在", rel)
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    for key in ("子 agent", "完整性"):
        if key not in text:
            err(f"规范要点防线被破坏：{rel} 缺失『{key}』——『调整规范后必须真正执行完整性校验』这条底线可能被删除/改写", rel)
    phase_done()


def check_priority_guard():
    """『规范优先级防线』：最高关注项、分级定义与落点必须仍在、且级别未被改动。

"""
    phase("规范优先级防线检查")
    rel_exec = "specs/core/execution.adoc"
    exec_path = os.path.join(REPO_ROOT, *rel_exec.split("/"))
    if not os.path.isfile(exec_path):
        err(f"缺少 {rel_exec}——分级定义与最高关注项的公共落点丢失", rel_exec)
        phase_done()
        return
    with open(exec_path, encoding="utf-8") as fh:
        exec_text = fh.read()
    # 公共侧：分级定义与最高关注项（含保留形态）必须仍在
    for key, desc in (("L1 强制", "分级定义之一（违反即视为未完成、不可豁免）"),
                      ("L2 建议", "分级定义之一（有正当理由可偏离、须留痕）"),
                      ("L3 允许", "分级定义之一（可选做法）"),
                      ("最高关注项", "最高关注项的公共落点（不可降级、重构首保）"),
                      ("不可降级", "最高关注项只能加强不得削弱的声明"),
                      ("一行引用", "保留形态：一处完整定义 + 其余一行引用（防复制正文）"),
                      ("强调", "强调的正确做法（升级别 + 单一定义 + 显式引用）")):
        if key not in exec_text:
            err(f"规范优先级防线被破坏：{rel_exec} 缺失『{key}』（{desc}）——"
                "分级与最高关注项的公共口径不得被删或降级", rel_exec)
    # 最高关注项 P1/P5 的必加载层落点仍须保留
    if "git mv" not in exec_text:
        err(f"规范优先级防线被破坏：{rel_exec} 缺失 `git mv` 铁律——"
            "最高关注项 P1 的必加载层落点被删除/改写", rel_exec)
    if "破坏性操作" not in exec_text:
        err(f"规范优先级防线被破坏：{rel_exec} 缺失「破坏性操作」——"
            "最高关注项（不可逆操作先确认）的必加载层落点被删除/改写", rel_exec)
    if "不得顺口编造" not in exec_text:
        err(f"规范优先级防线被破坏：{rel_exec} 缺失来源真实性（不得编造事实与来源）——"
            "最高关注项的必加载层落点被删除/改写", rel_exec)
    if "范围控制" not in exec_text:
        err(f"规范优先级防线被破坏：{rel_exec} 缺失读取范围与长会话治理（「范围控制」）——"
            "最高关注项的必加载层落点被删除/改写", rel_exec)

    # 维护方侧：P1-P6 清单与级别
    rel_priority = "specs-project-maintainer/priority.adoc"
    path = os.path.join(REPO_ROOT, *rel_priority.split("/"))
    if not os.path.isfile(path):
        err(f"缺少维护方最高关注项清单 {rel_priority}——不可降级清单无处承载", rel_priority)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    for pid, name, level in (("P1", "git mv", "L1，最高"), ("P2", "完整性", "L1，最高"),
                             ("P3", "内容不得减少", "L1，最高"),
                             ("P4", "读取与上下文纪律（含执行轮次合并／少绕）", "L2 建议"),
                             ("P5", "不可逆操作与来源真实性", "L1，最高"),
                             ("P6", "协作执行者选择", "L1，最高")):
        if pid not in text:
            err(f"规范优先级防线被破坏：{rel_priority} 缺失最高关注项 {pid}（{name}）——"
                "最高关注项不得被删除或降级", rel_priority)
        else:
            m = re.search(rf"^===\s*{pid}\.", text, re.M)
            if m is None:
                err(f"规范优先级防线被破坏：{rel_priority} 未找到最高关注项 {pid}"
                    f"（{name}）的小标题『=== {pid}. 』——结构被改写会导致级别核对失效",
                    rel_priority)
                continue
            seg = text[m.start():].split("\n===")[0]
            if f"要求（{level}" not in seg:
                err(f"规范优先级防线被破坏：{rel_priority} 的最高关注项 {pid}（{name}）"
                    f"须标明『要求（{level}』——级别不得被静默改动"
                    "（P1/P2/P3/P5/P6 为 L1 铁律，P4 条款本身为 L2 建议）", rel_priority)
            if "**依据**" not in seg:
                err(f"规范优先级防线被破坏：{rel_priority} 的最高关注项 {pid}（{name}）"
                    "缺失『**依据**』行——依据可压缩为标准名/编号，但不得整段删除"
                    "（检索不到依据，就无从判断它是『拍脑袋』还是『有出处』）", rel_priority)
            if pid == "P4" and "少绕" not in seg:
                err(f"规范优先级防线被破坏：{rel_priority} 的最高关注项 P4 "
                    "缺失『少绕』（执行轮次须合并）这一半——只留『少读』时，"
                    "执行者会把可合并的调用拆成多轮，每轮重付一次全上下文输入"
                    "（实证见 library/throughput.adoc）", rel_priority)
        if "不可降级" not in text:
            err(f"规范优先级防线被破坏：{rel_priority} 缺失『不可降级』声明——"
                "最高关注项须明确只能加强、不得削弱", rel_priority)
    # P6 的**内容**（不只看名字还在）：本条是"清单里列着、正文却是旧口径"的实证——
    # 出处选择曾被收紧为"强制同 Agent、不得点名外部 NPC"，这一段却停在"优先同源 +
    # 外部来源作备选"，于是按最高关注项读的维护方会照旧把复核派给外部执行者；而当时的
    # 防线只核 `**要求（L1，最高` 与 `**依据**`，两句旧字样照样全绿（防"关键词堆砌假绿"
    # 的反面：只核格式、不核口径）。故此处同时钉**新口径须在**与**旧口径不得复活**。
    p6_m = re.search(r"^===\s*P6\..*?(?=\n=== |\Z)", text, re.M | re.S)
    if p6_m is None:
        err(f"{rel_priority} 未找到 P6 条目正文——协作执行者选择的口径失去落点", rel_priority)
    else:
        p6 = p6_m.group(0)
        run_rule_guard("check_priority_guard")
        if "备选" in p6 or "同源不可用" in p6:
            err(f"规范优先级防线被破坏：{rel_priority} 的 P6 正文出现旧口径字样"
                "（『外部来源作备选』/『同源不可用』）——该口径已被公共侧收紧为"
                "『强制同 Agent、不得点名外部 Agent/NPC』；此处不同步即"
                "『清单更高更显眼、正文却是旧路』，按最高关注项读的维护方会继续派外部执行者",
                rel_priority)
    # 维护方层须由维护方的项目规范入口登记（否则不会被加载、其中规则实际失效）
    if not os.path.isfile(PROJECT_FILE):
        err("缺少 AGENTS.adoc——维护方自查层的登记入口丢失", "AGENTS.adoc")
    else:
        with open(PROJECT_FILE, encoding="utf-8") as fh:
            own = fh.read()
        # 名单以 `MAINTAINER_LAYER_FILES` 为唯一来源（新增一个维护方文件时只改名单一处）
        for rel in MAINTAINER_LAYER_FILES:
            if rel not in own:
                err(f"{rel} 未在维护方项目规范入口 AGENTS.adoc 登记"
                    "（不会被加载、其中规则实际失效）", "AGENTS.adoc")


def check_spec_admission_guard():
    """『规范准入防线』：分类/准入规范、其调度器登记与提案校验要点不得被删或降级。

"""
    phase("规范准入防线检查")
    rel_admission = os.path.relpath(ADMISSION_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(ADMISSION_FILE):
        err(f"缺少规范分类与准入文件 {rel_admission}——"
            "新增/调整规范条目将失去分类、分层与准入判定的依据", rel_admission)
        phase_done()
        return
    with open(ADMISSION_FILE, encoding="utf-8") as fh:
        text = fh.read()
    # 要点须仍在：公共/项目归属判定、准入判定、提案校验（是否已有标准/已有条目/升级举一反三）
    for key, desc in (
            ("归属判定", "公共/项目归属判定（对谁成立 + 自足性判据）"),
            ("准入判定", "该不该收进规范集合的准入判定"),
            ("已有标准", "提案校验之「检查是否已有标准」"),
            ("先找参照物、别自己造", "提案校验之「先找参照物、别自己造」（现成口径/更优设计/判定标准）"),
            ("存在比用户口述更优的设计时", "提案校验之更优设计取舍（不得照抄用户口述）"),
            ("已有本项目条目", "提案校验之「检查是否已有条目（不重复收）」"),
            ("举一反三", "提案校验之「升级与举一反三」"),
            ("规范集合的自身重构", "规范自身的瘦身与归位（重构顺序与删/移/留速查）"),
            ("同一条规则有两种读法", "执行侧只给『怎么走』、依据与取舍归思考/决策侧（读的形态判据）"),
            ("归属判定", "公共/项目归属判定（对谁成立 + 自足性判据）"),
            ("重构后须核对规范有效性", "重构不丢内容之外还须保证有效性（两形态分离/可执行性不降级/可见性不丢）")):
        if key not in text:
            err(f"规范准入防线被破坏：{rel_admission} 缺失『{key}』（{desc}）——"
                "准入与提案校验口径不得被删或降级", rel_admission)
    # 定级口径须以**节标题**存在（条目"该定哪一级"的判定依据；被删或降为正文一句，
    # 条目级别就再无判定依据、会重新回到"凭感觉/看关键词"，正是本仓库出现过的混乱来源）。
    for sec, desc in (("如何给一条规范定级", "定级口径四问"),
                      ("与条款类型一一对应", "条款类型与级别的判定表"),
                      ("归属谁", "分级与强制对象的正交判定"),
                      ("归类举证", "定级结论的对象/依据/类型/结论留痕"),
                      ("级别变更与复盘", "级别变更须说明理由 + 定期复盘六查")):
        if not re.search(rf"^==+\s*{re.escape(sec)}", text, re.M):
            err(f"规范准入防线被破坏：{rel_admission} 缺失节『{sec}』（{desc}）——"
                "定级口径被删后条目级别再无判定依据、级别会重新混乱", rel_admission)
    # 重构顺序（先判归属 → 再判层级 → 再判重复）不得被删或颠倒：顺序颠倒会把
    # "放错位置的内容"直接删掉（本该移走却被当冗余删除）。
    for key in ("先判归属", "再判层级", "再判重复"):
        if key not in text:
            err(f"规范准入防线被破坏：{rel_admission} 缺失重构顺序要点『{key}』——"
                "规范自身重构的判断顺序不得被删或改写", rel_admission)
    # 维护方层须由维护方项目规范入口登记（未登记则永不被加载、其中规则实际失效）
    with open(PROJECT_FILE, encoding="utf-8") as fh:
        if rel_admission not in fh.read():
            err(f"规范准入文件 {rel_admission} 未在 {os.path.relpath(PROJECT_FILE, REPO_ROOT)} "
                "登记（不会被加载、其中规则实际失效）",
                os.path.relpath(PROJECT_FILE, REPO_ROOT))
    phase_done()

def check_lifecycle_guard():
    """『任务生命周期防线』：节点自查、验证边界与拆分判据不得被删或降级。

"""
    phase("任务生命周期防线检查")
    rel_exec = os.path.relpath(EXECUTION_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(EXECUTION_FILE):
        err(f"缺少必加载层文件 {rel_exec}——任务节点的自查清单失去集中落点", rel_exec)
    else:
        with open(EXECUTION_FILE, encoding="utf-8") as fh:
            text = fh.read()
        if not re.search(r"^==+\s*任务生命周期与节点自查", text, re.M):
            err(f"任务生命周期防线被破坏：{rel_exec} 缺失「任务生命周期与节点自查」节——"
                "各节点该查什么必须可枚举，否则任务只能靠'做完才发现读错方向'", rel_exec)
        # 节点须以**表格行**形态存在（`| **节点**（L1）`）：只匹配关键词会被
        # "方案改/验证项"之类的改写蒙混过去——节点清单是本节的核心，必须行级钉住。
        for node, desc in (
                ("提出", "用户表述不清先澄清，不自行假设后开工"),
                ("理解", "规范是否已实际加载 + 最小必要信息集 + 主侧重"),
                ("方案", "规划落盘 + 去重删减前先核覆盖完整性"),
                ("执行", "加载由入口驱动 + 环境能力先自评 + 读取不越界"),
                ("验证", "按改动性质选范围 + 严格执行/尽力而为 + 全局核对"),
                ("交付", "交付形态按执行环境区分 + 落盘同步"),
                ("复盘", "三视角评有效性 + 核规则初衷 + 核是否该拆分")):
            if not re.search(rf"^\|\s*\*\*{node}\*\*", text, re.M):
                err(f"任务生命周期防线被破坏：{rel_exec} 缺失节点行『{node}』（{desc}）——"
                    "节点清单被删/改写后'到哪个节点查什么'重新无人负责", rel_exec)
        # 节点清单必须含"哪些节点不设"的**独立声明**（否则概念性验证会外溢到代码类任务）：
        # 只匹配"代码类改动"会被验证节点行里的同一措辞蒙混过去，须按声明行钉住。
        if not re.search(r"^\*\s*\*\*哪些节点不设", text, re.M) or "代码类改动" not in text:
            err(f"任务生命周期防线被破坏：{rel_exec} 未写明哪些节点**不设**（代码类改动"
                "不设复盘、不做三视角与全局验证）——概念性验证会外溢成所有任务的流程",
                rel_exec)
    # 验证边界：公共口径的**单一落点**是 specs/general/verify.adoc；testing.adoc 同名节
    # 只留一跳入口（两处各写一份会各自漂移——已实测漂移过一次）
    rel_verify = os.path.join("specs", "general", "verify.adoc").replace(os.sep, "/")
    v_path = os.path.join(REPO_ROOT, *rel_verify.split("/"))
    if not os.path.isfile(v_path):
        err(f"缺少验证规范文件 {rel_verify}——验证的适用边界失去集中落点", rel_verify)
    else:
        with open(v_path, encoding="utf-8") as fh:
            vtext = fh.read()
        if not re.search(r"^==+\s*验证的适用边界", vtext, re.M):
            err(f"任务生命周期防线被破坏：{rel_verify} 缺失「验证的适用边界」节——"
                "不先判改动性质，验证范围就无处取值（规范类改动只跑机械校验、"
                "代码类改动被要求三视角），两头失效会重新出现", rel_verify)
        for key, desc in (
                ("效力等级", "验证结论须按对象标效力（确定项可判对错、概念项只到未发现）"),
                ("代码类改动", "A 类：按机械判据判过不过（能过就能过）"),
                ("规范类改动", "B 类：三视角深度验证 + 全局核对"),
                ("不改内容的操作", "C 类：只改提交/历史或文件路径、内容逐字节不变，不重跑全量校验"),
                ("不重跑全量编译与测试", "C 类的验证口径：内容没变，重跑得不到新判据"),
                ('"内容没变"不是"少核对"的借口', "C 的边界：省的是重跑、不是核对，操作自身判据一条不能少"),
                ("会不会被未知项目加载", "唯一判据：改动是否会被未知项目加载/改变别人行为"),
                ("先判改动性质", "先判性质、再选范围（不得因改动小就降级）"),
                ("不得互串", "过度验证与跳过验证都禁止"),
                ("取**更严的一侧**", "两类改动同批时取更严一侧，代码部分仍按机械判据")):
            if key not in vtext:
                err(f"任务生命周期防线被破坏：{rel_verify} 缺失『{key}』（{desc}）——"
                    "验证边界不得被删或降级", rel_verify)
        if "每次验证都换一个干净上下文" not in vtext:
            err(f"任务生命周期防线被破坏：{rel_verify} 未要求**每次验证换一个干净上下文**——"
                "复用发起改动/上一轮验证的上下文等于自己复核自己，会只找'是否已改'",
                rel_verify)
    # 拆分判据：拆是加载面的膨胀源，判据不得被删
    rel_adm = os.path.relpath(ADMISSION_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(ADMISSION_FILE):
        with open(ADMISSION_FILE, encoding="utf-8") as fh:
            atext = fh.read()
        for sec, desc in (("一条规范何时该拆分", "拆分硬条件（默认不拆、三条同时成立）"),
                          ("拆分后的自洽核对", "拆完逐项核对（引用可达/无矛盾/不失完整性/登记同步）")):
            if not re.search(rf"^==+\s*{re.escape(sec)}", atext, re.M):
                err(f"任务生命周期防线被破坏：{rel_adm} 缺失节『{sec}』（{desc}）——"
                    "拆分若无判据，就会为'看起来更整齐'多出一个没人维护的东西", rel_adm)
        for key, desc in (
                ("判据与用处不同", "硬条件一：判据形态或加载时机不同（同类条目不得拆）"),
                ("不拆就真的坏", "硬条件二：须能指出实害，'更整齐'不构成理由"),
                ("拆后每一半都自足", "硬条件三：每半都有判据、落点、加载方式"),
                ("默认不拆", "取向：按需才拆，不为对称、不为好看而拆"),
                ("单独过准入九问", "拆分不豁免准入判定（有落点/成本可接受尤其）"),
                ("同一事项只有一个真源", "不拆后的落点口径：真源一处、其余一跳引用"),
                ("推荐程度与机械量级不构成另建落点的理由", "第二处真源的成因之一（判据本体相同）"),
                ("新增规范的提案校验", "另建防线这一高发入口的拦法落点"),
                ("同一事项不得留两处真源", "提案校验里的拦法：已钉过不另建、判据形态不同才另建")):
            if key not in atext:
                err(f"任务生命周期防线被破坏：{rel_adm} 缺失『{key}』（{desc}）——"
                    "同一条规则会被钉出第二处真源（两处各改一次、先报红的未必是权威）",
                    rel_adm)
    # 三处口径同源：执行原则（节点清单）→ AGENTS.adoc（本仓库落点）→ verify.adoc（边界判据）
    if not os.path.isfile(PROJECT_FILE):
        err("缺少 AGENTS.adoc：任务生命周期的本仓库落点无处承载", "AGENTS.adoc")
        phase_done()
        return
    with open(PROJECT_FILE, encoding="utf-8") as fh:
        own = fh.read()
    for key, desc in (("验证的适用边界", "本仓库落点须指向公共边界节的判据"),
                      ("验证的效力等级", "本仓库落点须指向效力等级口径"),
                      ("一条规范何时该拆分", "本仓库落点须指向拆分判据"),
                      ("specs-project-maintainer/verify.adoc", "维护方的验证义务落点")):
        if key not in own:
            err(f"任务生命周期防线被破坏：AGENTS.adoc 缺失『{key}』（{desc}）——"
                "本仓库维护口径须与公共口径一致", "AGENTS.adoc")
    phase_done()


def check_line_ending_guard():
    """『换行符防线』：跨平台行尾规则（LF 基准 + Windows 批处理 CRLF）不得被删或弱化。

"""
    phase("换行符防线检查")
    rel = _rel_label(ENCODING_FILE)
    if not os.path.isfile(ENCODING_FILE):
        err(f"缺少编码与语言无关规范文件 {rel}——"
            "跨平台换行符（LF 基准与 Windows 批处理 CRLF）失去集中落点", rel)
    else:
        with open(ENCODING_FILE, encoding="utf-8") as fh:
            text = fh.read()
        for key, desc in (
                ("换行符", "行尾规则的权威小节"),
                ("以 LF 为基准", "仓库基准行尾（防被改成 CRLF 基准）"),
                (".bat", "Windows 批处理必须 CRLF 的对象"),
                ("CRLF", "Windows 批处理的行尾要求"),
                ("core.autocrlf", "检出归一化依据（不靠人工手动调整）"),
                (".gitattributes", "行尾策略的权威落盘口"),
                (".editorconfig", "编辑器侧行尾/编码的落盘口")):
            if key not in text:
                err(f"换行符防线被破坏：{rel} 缺失『{key}』（{desc}）——"
                    "跨平台行尾规则不得被删或弱化", rel)
    # 脚本技术栈文件各自须写明行尾要求（引用方按各自栈文件加载）
    for stack_file in LINE_ENDING_STACK_FILES:
        srel = _rel_label(stack_file)
        if not os.path.isfile(stack_file):
            err(f"缺少脚本技术栈文件 {srel}——其行尾要求无处承载", srel)
            continue
        with open(stack_file, encoding="utf-8") as fh:
            stext = fh.read()
        if "行尾" not in stext and "CRLF" not in stext:
            err(f"换行符防线被破坏：{srel} 未写明行尾要求——"
                "引用方按该栈文件学习时学不到行尾规则", srel)
    # BOM 与首行声明：BOM 是唯一允许出现在首行之前的东西（`.bat` 的 `@echo off`、`.ps1` 的
    # 同类声明都依赖"首行就是第一行"）；`.bat` 取纯 ASCII 时天然无 BOM，二者是一件事。
    for stack_file, keys, desc in (
            (os.path.join(SPECS_DIR, "stack", "batch.adoc"),
             (("天然不带 BOM",), ("首行",)),
             "批处理栈须写明「纯 ASCII 天然不带 BOM」（二者是一件事的两面）与『首行』的字面口径"
             "——缺则会被读成『纯 ASCII 是不写 BOM 的子集』，或任由空行/BOM 把 `@echo off` 挤下首行"),
            (os.path.join(SPECS_DIR, "stack", "powershell.adoc"),
             (("BOM 是唯一允许出现在首行之前",),),
             "PowerShell 栈须写明 BOM 是唯一允许出现在首行之前的东西——"
             "缺则空行/注释被写在 BOM 之前、首行声明失效")):
        srel = _rel_label(stack_file)
        if not os.path.isfile(stack_file):
            err(f"缺少脚本技术栈文件 {srel}——其 BOM/首行口径无处承载", srel)
            continue
        with open(stack_file, encoding="utf-8") as fh:
            stext = fh.read()
        for sk in keys:
            missing = [k for k in sk if k not in stext]
            if missing:
                err(f"换行符/编码防线被破坏：{srel} 缺失要点 {missing}——{desc}", srel)
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        if rel not in set(extract_specs_refs(fh.read(), "")):
            err(f"编码与语言无关规范 {rel} 未在加载调度器登记（不会被加载、其中规则实际失效）",
                "AGENTS_COMMON.adoc")
    phase_done()


def check_java_test_naming():
    """『Java 测试类命名防线』：四类测试后缀与测试类拆分裁决的判据不得在任一处被删或漂移。

"""
    phase("Java 测试类命名防线检查")
    rel = os.path.relpath(JAVA_TEST_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_TEST_FILE):
        err(f"缺少 Java 测试规范文件 {rel}——"
            "测试类命名契约（Tests/BootTests/PerfTests/IT 四类后缀）失去落点", rel)
    else:
        with open(JAVA_TEST_FILE, encoding="utf-8") as fh:
            text = fh.read()
        for suffix in JAVA_TEST_SUFFIXES:
            if suffix not in text:
                err(f"Java 测试类命名防线被破坏：{rel} 缺失测试类型后缀『{suffix}』——"
                    "四类命名契约不得被删或降级", rel)
        for key, desc in (("测试类命名", "四类后缀的权威定义节"),
                          ("被测类名", "『被测类名 + 测试类型后缀』的命名口径"),
                          ("常规", "类别与执行阶段的绑定口径")):
            if key not in text:
                err(f"Java 测试类命名防线被破坏：{rel} 缺失『{key}』（{desc}）", rel)
        # 拆分裁决：一个被测类可拆多个测试类，但只按需求/分类拆、不得滥拆——三段判据缺一
        # 即口径只剩一半（只剩"可拆"会放任滥拆，只剩"合并"会退回"一个被测类一个测试类"）。
        for part, anchors in JAVA_TEST_SPLIT_MARKERS.items():
            if not all(a in text for a in anchors):
                err(f"Java 测试类命名防线被破坏：{rel} 缺失拆分裁决『{part}』判据——"
                    "『可拆但不得滥拆』只剩一半（要么放任滥拆、要么退回一个被测类一个测试类）", rel)
    # 调度器的 Java 技术栈登记须与该契约一致（只说一半会让引用方学不全）
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        generic = fh.read()
    # 调度器里**可能有多条**指向 java-testing 的加载项（如"跑测试/补测试"与"做性能测试"
    # 各一条：后者需要该文件的承载与执行边界说明）——命名契约只要在**任一条**里写全即可，
    # 故把候选行**合起来**核对；只看第一条会在新增第二条时假红（且与"契约是否真的被传达"
    # 无关：契约只要在调度器里可达即成立）。
    java_lines = [ln for ln in generic.splitlines() if "stack/java-testing.adoc" in ln]
    if not java_lines:
        err(f"Java 测试规范 {rel} 未在加载调度器登记（不会被加载、其中命名契约实际失效）",
            "AGENTS_COMMON.adoc")
    else:
        # 调度器**只须带「什么时候要加载」的触发特征**（要新建或改动 Java 测试类），
        # 四类后缀与拆分裁决是 `java-testing.adoc` 的**条目本体**——原先要求调度器逐字
        # 抄全后缀名与「多个测试类/不得滥拆」，是把本体复制进调度器（第二真源：
        # `terminology.adoc`「数据字典」的反膨胀、`doc-design.adoc`「信息归属」）。
        # 本体齐备由上面对 `java-testing.adoc` 的核对负责，这里只核「调度器能不能被触发」。
        java_line = "\n".join(java_lines)
        if not any(t in java_line for t in ("测试类", "测试规范", "测试")):
            err("Java 测试类命名防线被破坏：AGENTS_COMMON.adoc 的 Java 技术栈登记"
                "未写明「要新建或改动 Java 测试类」这一触发特征——"
                "缺则写测试类时该文件不会被加载，其中的命名契约实际失效",
                "AGENTS_COMMON.adoc")
    phase_done()


def check_git_mv_selfcheck():
    """『本仓库自身侧 git mv 自查』：把最高关注项 P1 从"口号"变成本仓库可机械核对的一项。

    背景：最高关注项 P1（文件移动/重命名必须 `git mv`）此前被登记为**无机械抓手**——
    因为铁律作用于**引用方项目的工作区**，本仓库看不到。但这只对"引用方"成立：
    **本仓库自己也有工作区**，其暂存内容可以核对。故在本仓库侧补上这一半：核对暂存区
    （`git diff --cached -M --name-status --diff-filter=AD`）是否同时出现删除与新增——
    那是 delete+create 误用的典型形态（历史会断链，且事后无法恢复）。

    实现边界（防止把校验扩到引用方，违反 `AGENTS.adoc`「校验范围」）：

      * 只查 **git 暂存区**（`git diff --cached`，不读工作区文件内容、不做逐文件比较）；
      * 无 git 仓库、无暂存内容、git 不可用 → 一律**跳过、不报错**（保持确定性与幂等）；
      * 发现疑似形态只提示并给出复核命令，**不自动改工作区**（修复由人工/agent 按 git
        规范执行，规范集合不代改引用方与自己的工作区）；
      * 真删真增（非移动）属合法改动，故本条给出的是"须复核"提示。

    **改写式移动（本仓库实证）**：把 `specs/library/` 搬到仓库根 `library/` 时，入口
    文件同时被整篇重写（去掉"分发给引用方/可关闭"口径、换登记处）——**内容相似度实测
    11%**（命令 `git diff --cached -M10% --summary` 输出 `rename ... (11%)`）、低于 git
    默认 50% 阈值，索引里就只剩"删除 + 新增"，看起来像违规的 delete+create，其实正是
    `git mv` 后正常改写。

    **阈值取值理由（说明它不是个案反推）**：`-M` 判据是 **"临时相似度索引"**——git 用
    一个近似算法（默认按 blob 大小建索引、对候选只做逐块指纹比对，故 2~3 行的短文
    **返回 0% 相似度属正常**，见 git 官方文档 `git-diff` 的 `--find-renames` 与
    `diff.renames`）；再叠加"移动后又被大幅改写"（**重写与移动常常同时发生**，本仓库即
    一例），默认阈值下**必然**漏检真移动。故所取阈值只需落在"真移动的下界"之下，不必
    精确：**真 delete+create 是"两个文件内容无关"，相似度接近 0；而 `git mv` + 改写
    实测仍有 11%**。取 10% 属保守取值（比实测低、给常见重写留余量），且本检查**只对
    "暂存区同时存在删除与新增"这一形态发声**——它是**提示须人工复核**（见下第 3 条），
    不是"判违规"，故阈值不是 P1 的效力边界：P1 的判定标准仍在规范文本（`git mv` 铁律
    + `git diff --cached -M --summary` 复核），本阈值只决定"要不要提醒人来看一眼"。
    """
    phase("本仓库 git mv 自查（P1 自身侧抓手）")
    if not os.path.isdir(os.path.join(REPO_ROOT, ".git")):
        phase_done()
        return
    try:
        out = subprocess.run(
            # -M10%：改写式移动（内容大幅重写）也能被识别为 rename，避免把合规的
            # `git mv` + 改写误判成 delete+create（默认阈值 50% 会漏掉这类）
            ["git", "diff", "--cached", "-M10%", "--name-status", "--diff-filter=AD"],
            cwd=REPO_ROOT, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        phase_done()
        return
    if out.returncode != 0:
        phase_done()
        return
    deleted, added = set(), set()
    for line in out.stdout.splitlines():
        parts = line.split("\t")
        if len(parts) < 2:
            continue
        status = parts[0][0]
        if status == "D":
            deleted.add(parts[-1])
        elif status == "A":
            added.add(parts[-1])
    if deleted and added:
        err("暂存区同时存在删除与新增（未识别为 rename）——这些改动若是文件移动/重命名，"
            "须改用 `git mv`（最高关注项 P1：delete+create 会使历史永久断链）；"
            "若确为真删真增（非移动），用 `git diff --cached -M10% --summary` 复核后可忽略本提示",
            "git 暂存区")
    phase_done()


def _merge_state_guard_repo_root():
    """当前被检查的仓库根（现场推导）：**不在导入期固化**——单测会把 `REPO_ROOT`
    重定向到临时仓库，故本道防线须每次现取，否则重定向失效（实测踩过）。"""
    return REPO_ROOT


def _merge_state_guard_rules():
    """取『NPC 禁合并·动作侧』的措辞表（规则数据外置，改措辞不动代码）。

    规则数据缺失不是"没有可核对的措辞"，而是整道防线无从执行——故回落到**空表**
    并在阶段内如实报错，不得静默放行（与 `_bootstrap_rules_tokens` 同口径）。
    """
    try:
        files = rules_engine.load_rule_files(_rules_spec())
    except rules_engine.RulesError as exc:
        err(f"规则数据不可读（{exc}）——『NPC 禁合并·动作侧』的措辞表无从取值，"
            "本道防线不得静默跳过", "script/specs-rules")
        return {}
    return files.get("merge_state_guard", {}) or {}


def check_merge_state_guard():
    """『NPC 禁合并·动作侧』：核**本仓库自身**的"合并动作真没做"，不是只核规则文本在不在。

    背景（本仓库实证失效一次）：用户要求"压缩提交"，执行者把它读成"合并 PR"、直接调
    平台合并、并在 PR 下回"已合并 ✅"——**真正被要求的那件事一件没做**。而当时三道
    **文本**防线（`check_npc_merge_guard` 的要点、提示词 `delivery` 片段、入口登记）
    **全部报 OK**：文本侧只能证"规则写着"，证不了"动作没做"。

    故本检查是文本侧之外的另一半，核三件**可机械核对的事实**（全部只读本仓库自身，
    不碰平台、不碰引用方）：

      * ① **提交说明**里出现合并动作的痕迹——`merge-pull`/`merge --no-ff`/`squash 合并`/
        `已合并`/`已合入`（措辞表在规则数据里，改措辞不改代码）；命中的行里若出现
        拒绝/禁令/不做一类标记词则放行——`check_merge_state_guard` 的报错文案本身、
        以及本条实证记录都会提到这些词，不能把"记录这件禁令的话"读成"执行了合并"。
      * ② **当前源分支 HEAD 不等于并发唤起时钉定的 sha**——PR 还在开着却把源分支推到
        别的 sha，是"合并/改写"的典型残留（判定只在 PR 为打开态、且钉定 sha 取得到时
        才发声；平台不提供这两个取值时按**跳过**处理，绝不猜）。
      * ③ **本分支历史里出现合并提交**（`git rev-list --merges <默认分支>..HEAD`）——
        "合并 PR"落盘一定会留下合并提交；正常交付（PR 分支上的单亲提交）不会。
        只在本分支相对默认分支**领先**时才发声，且合并提交本身要与默认分支/远端同名
        分支做交叉核对后再报——**避免把"把自己分支同步一次默认分支"这种合规动作读成违规**。

    **效力边界（说明白了才不算虚报抓手）**：这三条覆盖的是"合并在本仓库留下痕迹"的
    情形；平台上直接合并、且不在本仓库留下任何痕迹时，本检查**看不到**——那一半只能
    由**平台侧禁止 NPC 执行合并**（撤销执行环境的合并权限）拦住，故 `AGENTS.adoc` 里
    写明该防线只是**第二道**。
    """
    phase("NPC 禁合并·动作侧检查")
    repo_root = _merge_state_guard_repo_root()
    if not os.path.isdir(os.path.join(repo_root, ".git")):
        phase_done()
        return
    data = _merge_state_guard_rules()

    def _git(*args):
        # `encoding="utf-8"`：git 输出默认就是 UTF-8，而 `text=True` 单用会按**本机 locale**
        # 解码——中文 Windows（GBK）下中文提交说明被解成乱码，`已合并` 一类标记词**匹配不上**，
        # 于是"真做了合并"反而**不报**（本轮实测：动作侧两条用例在本机失败，就是这一步）。
        try:
            out = subprocess.run(["git", *args], cwd=repo_root,
                                 capture_output=True, text=True, timeout=30,
                                 encoding="utf-8", errors="replace")
        except (OSError, subprocess.SubprocessError):
            return None
        return out.stdout if out.returncode == 0 else None

    # ① 提交说明的**动作面**（标题 + 正文首个段落）出现合并动作话术
    #
    # 取"标题 + 首段"而不是整篇正文：交付口径里"做了什么"就在这两处，而叙述性的
    # 复述（如判据本体里的实证记录、图书馆里的依据说明）落在后面的段落——
    # 整篇扫会把"记录这件禁令"的句子读成"执行了合并"（实测踩过：本条自己的提交
    # 说明写过"把原话读成合并 PR、直接调平台合并并回已合并 ✅"，那是记录不是执行）。
    msgs = _git("log", "-100", "--format=%s%n---BODY---%n%b%n---END---")
    if msgs is not None:
        markers = [w.lower() for w in data.get("merge_action_markers", [])]
        allow = [w.lower() for w in data.get("allow_markers", [])]
        hits = []
        for record in msgs.split("---END---"):
            lines = [l for l in record.splitlines() if l.strip() and l.strip() != "---BODY---"]
            zone = lines[:1] + lines[1:2]  # 标题 + 正文首段
            for line in zone:
                low = line.lower()
                if any(m in low for m in markers) and not any(a in low for a in allow):
                    hits.append(line.strip())
        if hits:
            shown = "；".join(list(dict.fromkeys(hits))[:3])
            err(f"提交说明（标题或正文首段）里出现合并动作的痕迹（`{shown}`）——"
                "NPC/CI 执行者**一律不得合并合并请求**"
                "（`specs/platform/cnb.adoc`「合并请求的合并主体（NPC 禁合并）」）；"
                "若这是「记录禁令本身」的文字而非真正执行，按该条允许的拒绝措辞写明是"
                "**拒绝**执行、不得写成已完成", "git 提交说明")

    # ② 源分支 HEAD 与并发唤起时钉定的 sha 不符（PR 仍开着 ＝ 典型残留）
    if os.environ.get("CNB_PULL_REQUEST", "").lower() == "true":
        pinned = os.environ.get("CNB_PULL_REQUEST_SHA", "").strip()
        head = (_git("rev-parse", "HEAD") or "").strip()
        if pinned and head and not head.startswith(pinned[:8]) and not pinned.startswith(head[:8]):
            err(f"当前检出 sha（`{head[:8]}`）与本次并发唤起时钉定的 sha（`{pinned[:8]}`）不符，"
                "而该合并请求仍处于打开态——PR 还在开着却把源分支推到别的 sha，是"
                "**合并/改写后未回退**的典型残留；须核对源分支是否已被合并或强推改写",
                "git HEAD")

    # ③ 本分支历史里的合并提交（正常交付是单亲提交链，不会出现合并提交）
    base = os.environ.get("CNB_DEFAULT_BRANCH", "main") or "main"
    ahead = _git("rev-list", "--count", f"{base}..HEAD")
    merges = _git("rev-list", "--merges", f"{base}..HEAD")
    if ahead and ahead.strip() not in ("", "0") and merges is not None:
        found = [l for l in merges.splitlines() if l.strip()]
        if found:
            detail = "; ".join(f"`{h.strip()[:8]}`" for h in found[:3])
            err(f"分支历史里出现合并提交（{detail}）——`specs/platform/cnb.adoc`「NPC 禁合并」"
                "要求合入只由人工完成，交付到创建/推送 PR 分支为止"
                "（交付形态须是源分支上的单亲提交链）；核对命令："
                "`git rev-list --merges <默认分支>..HEAD`", "git 历史")
    phase_done()


def check_file_size_hint():
    """『单个规范文件的软阈值』：超线只提醒、不报错、不阻断（**刻意不用 err()**）。

    背景（本仓库实证）：内容会被一路往既有文件里丢——单个规范文件越大，按需加载越
    退化成"整份读完"，与本次任务无关的规则同样占满读取预算（多读挤上下文），
    而"这一处该归到哪一层、哪一节"也失去了触发点。必加载层另有"合计量硬上限"
    （`check_budget_guard`），但**非必加载的单个文件此前没有任何提醒机制**。

    与硬上限的分工（两条都不得替代对方）：
      * `check_budget_guard`：必加载层（入口 + `specs/core/`）**合计量**的机械上限，
        超限**报错**——它最直接地消耗每次会话的注意力预算，必须有天花板。
      * 本条：**单个规范文件**的**软阈值**，超出**只提醒**——是否拆由
        `spec-lifecycle`「一条规范何时该拆分」的三条硬条件判定，**默认不拆**；
        硬上限会逼出"为压体积删规则"或"为达标拆出没人维护的空壳"，故此处只给信号。

    提醒形态（不新增错误通道）：打印一行提示清单，**不进 errors**、不影响退出码——
    提醒不阻断提交，符合"软阈值"的语义（用 err() 就成了硬上限）。

    范围：公共规范（入口 `AGENTS_COMMON.adoc` 与 `specs/**`）与维护方自查层
    （`specs-project-maintainer/**`）；其中**常驻层**（入口 + `specs/core/`）**排除**
    ——它由硬上限 `check_budget_guard` 负责，两条都覆盖同一份文件会让"该处理哪条"分不清。
    图书馆（`library/**`，无体量上限、按主题取用）与说明类文档（README/CHANGELOG 等）
    **不吃**本软阈值：它们不是"按需加载即整份读完"的对象，误伤只会制造噪音。
    """
    phase("单个规范文件软阈值（提醒，不报错）")
    # 现场推导（不直接引用可能被单测重定向的模块常量）：只收仓库内的规范文件
    root_dir = os.path.abspath(REPO_ROOT)
    targets = []
    entry = os.path.join(root_dir, "AGENTS_COMMON.adoc")
    if os.path.isfile(entry):
        targets.append(entry)
    for sub in ("specs", "specs-project-maintainer"):
        d = os.path.join(root_dir, sub)
        for dirpath, _, files in os.walk(d):
            for f in files:
                if f.endswith(".adoc"):
                    targets.append(os.path.join(dirpath, f))
    # 常驻层由硬上限（check_budget_guard）负责，不再重复提醒：否则同一份文件
    # 同时出现在"超限报错"与"超线提醒"两处，读者会分不清哪条是需要处理的
    resident = {_rel_of(entry), _rel_of(os.path.join(root_dir, "specs", "core", "execution.adoc"))}
    hints = []
    for path in sorted(set(targets)):
        rel = _rel_of(path)
        if rel in resident:
            continue
        size = os.path.getsize(path)
        if size > SOFT_FILE_SIZE_HINT:
            hints.append((rel, size))
    if hints:
        # 刻意不用 err()：软阈值不进 errors、不影响退出码
        log(f"  ! {len(hints)} 个规范文件超过软阈值 "
            f"{SOFT_FILE_SIZE_HINT} 字节（**提醒、不阻断**——先按 "
            "specs-project-maintainer/spec-lifecycle.adoc「单个规范文件的软阈值」判归属与层级，"
            "再按「一条规范何时该拆分」判是否该拆；都不成立即不做）：")
        for rel, size in hints:
            print(f"      * {rel}  {size} 字节")
    phase_done()


def check_budget_guard():
    """『常驻层体积上限』：必加载层体积与调度器条目数不得无声膨胀。

    背景：必加载层（`AGENTS_COMMON.adoc` + `specs/core/`）**每次会话无条件加载**，是
    最直接的"注意力预算"消耗者；规范自己写着"常驻层只放底线""篇幅越大越易挤爆上下文"，
    但此前**只有方向、没有机械抓手**——每次新增都"礼貌地"往常驻层加一点，几十次之后
    体量翻倍而无人发现（本仓库已发生过一次，靠人 review 才拦下）。故把预算写成机械上限：
    超限即报错，须"先归位、再新增"。

    上限不是目标、是**天花板**：只在明显膨胀时报警，正常增删不误伤（数值留有余量）。
    """
    phase("常驻层体积上限检查")
    total = 0
    for rel in ("AGENTS_COMMON.adoc", "specs/core/execution.adoc"):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少必加载层文件 {rel}", rel)
            continue
        total += os.path.getsize(path)
    if total > RESIDENT_BUDGET:
        err(f"常驻层体积超限：必加载层（AGENTS_COMMON.adoc + specs/core/）共 {total} 字节，"
            f"超出上限 {RESIDENT_BUDGET} 字节——常驻层只放 L1 底线、最高关注项与其引用落点，"
            "方法论/依据论证/示例/元规范须移到通用层（用到才加载）；请先按 "
            "specs-project-maintainer/spec-lifecycle.adoc「规范集合的自身重构」判归属与层级，"
            "再决定该项是否真该常驻", "AGENTS_COMMON.adoc + specs/core/")
    # 项目自身入口 AGENTS.adoc 同为每次会话无条件加载的常驻物，单列上限（不并入
    # RESIDENT_BUDGET——它是项目自身规范、引用方不使用，口径不同）。
    entry_path = os.path.join(REPO_ROOT, "AGENTS.adoc")
    if os.path.isfile(entry_path):
        entry_size = os.path.getsize(entry_path)
        if entry_size > PROJECT_ENTRY_BUDGET:
            err(f"项目入口 AGENTS.adoc 体积超限：{entry_size} 字节，超出上限 "
                f"{PROJECT_ENTRY_BUDGET} 字节——它同为每次会话无条件加载的常驻物，"
                "只放本项目的加载说明与校验范围；方法论/依据论证/示例须移到 specs/ 用到才加载",
                "AGENTS.adoc")
    rel_common = "AGENTS_COMMON.adoc"
    with open(os.path.join(REPO_ROOT, rel_common), encoding="utf-8") as fh:
        text = fh.read()
    m = re.search(r"== 分类与懒加载（加载调度器）(.*?)== 技术栈扩展约定", text, re.S)
    if m is None:
        err(f"{rel_common} 未找到「分类与懒加载（加载调度器）」节——调度器结构被改写，"
            "条目数上限失去抓手", rel_common)
    else:
        count = m.group(1).count("\n* ")
        if count > DISPATCHER_ITEMS_MAX:
            err(f"加载调度器条目数超限：「涉及即加载」条目共 {count} 个，"
                f"超出上限 {DISPATCHER_ITEMS_MAX}——条目过多会让每次执行都难以判全"
                "『该加载哪些』；请先归并同类条目（一条覆盖一个主题族），再新增", rel_common)
    phase_done()


def check_delegation_guard():
    """『从属者与能力自评防线』：两类"定义了却不会被执行"的机制要点必须仍在。

"""
    phase("从属者与能力自评防线检查")
    for rel, key, desc in (
        ("AGENTS_COMMON.adoc", "从属者", "入口驱动加载（子 agent/被引用方不靠自报）"),
        ("specs/general/self-check.adoc", "环境能力自评", "无机制时按降级路径、不得空自评"),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少文件 {rel}——{desc} 无处承载", rel)
            continue
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        if key not in text:
            err(f"从属者与能力自评防线被破坏：{rel} 缺失『{key}』机制——{desc}；"
                "该类要点属'定义了却不会执行'的高发盲点，不得删除或并入他处而失去痕迹", rel)
    # 执行者来源选择：『**强制同 Agent**』的五处要点——(a) 子任务必须与执行者同 Agent、
    # (b) **不得点名外部 Agent/NPC**（含判定标准）、(c) 同 Agent 不可用时的降级路径（本
    # 地串行/标悬置、不换外部来源）、(d) 优先一次性调用、(e) 三视角与维护方落点同口径。
    # 此处只钉"要求文本仍在"——"本次是否真按同 Agent 派发、有没有点名外部 NPC"属运行时
    # 行为（评论/派发的实际内容），机械无法判定，交人/子 agent 复核；但"要求被抽掉"必须
    # 拦住（本项目已有两次外部 NPC 实证：派发即失败、1 h+ 未回传）。**每条要求须同时命中
    # 多处要素**，否则别处一句同名字样即可让检查假绿（与 check_checklist_guard 同口径）。
    for rel, keys, desc in (
        ("specs/general/collab.adoc", ("子任务必须由与执行者相同的 Agent 承担",
                                       "不得点名外部 Agent / 外部 NPC",
                                       "同一 Agent 身份"),
         "子任务一律同 Agent（同 Agent 身份 + 同入口/调度器），不得点名外部 Agent/NPC"),
        ("specs/general/collab.adoc", ("判定标准", "派发目标", "交换面", "回传面"),
         "『不得点名外部 NPC』须给出可核对的判定标准，否则只剩一句口号"),
        ("specs/general/collab.adoc", ("降级路径（L1）", "不换任何外部来源",
                                       "由执行者本人（主 agent）串行承担"),
         "同 Agent 不可用也不得换外部来源，须降级为执行者本人串行或如实标悬置"),
        ("specs/general/collab.adoc", ("优先一次性调用",),
         "派发优先一次性、边界明确、可超时，不交有自主探查权的执行者"),
        # 三视角复核口径的单一落点是 verify.adoc（testing.adoc 同名节只留一跳入口）
        ("specs/general/verify.adoc", ("强制同 Agent", "不得点名外部 Agent"),
         "三视角复核口径须与协作规范同口径（强制同 Agent、不得点名外部 NPC）"),
        ("specs-project-maintainer/verify.adoc", ("子 Agent 强制与执行者同 Agent",),
         "维护方落点：强制同 Agent、外部复核者不作为备选"),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少文件 {rel}——{desc} 无处承载", rel)
            continue
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        missing = [k for k in keys if k not in text]
        if missing:
            err(f"执行者来源选择防线被破坏：{rel} 缺失要点 {missing}——{desc}；"
                "该要点防的是'缺复核时随手抓一个不可核对的外部执行者'，"
                "不得删除或并入他处而失去痕迹", rel)
    # 『旧口径不得复活』：上面只核"新口径的要素仍在"，会漏掉一种同样致命的破坏——
    # 把**许可范围悄悄放宽**（写成"优先同源、外部作备选"或"拿不到同 Agent 时也可换外部
    # 顶替"）。此时"不得点名外部 Agent / 外部 NPC"等字样往往仍在，检查全绿，而按它读的人
    # 会重新把外部执行者当成合法路径（本项目实证：外部评审 NPC 两次分别派发即失败、
    # 1 h+ 未回传）。故按**旧口径措辞**设防。
    #
    # 判定口径（命中即报，均可逐字核对）——**只拦"放宽形态"，不拦"禁止形态"**：
    #   * 旧口径整句：`<来源替换词> + <备选/次选类词>` 的**明确搭配**，如"外部来源…备选"、
    #     "外部复核者作备选"、"也可以换外部…顶替"；
    #   * 每条命中都能定位到**具体短语**，不做"整文共现即报"（那会把
    #     "不得换任何外部来源的 Agent 顶替"这类**正当禁止式**写法误判为违规）。
    # 正当写法（**不得误报**，均为本仓库现行文本）："不得点名外部 Agent / 外部 NPC"、
    # "不得用外部 Agent 顶替"、"不换任何外部来源的 Agent 顶替"、
    # "不得改回『外部来源可以顶替』的宽松写法"（反例引用）、"外部复核者不作为备选"。
    STALE_PATTERNS = (
        # (正则, 说明) —— 只描述"放宽/许可"形态
        (r"外部(?:来源|NPC|Agent|复核者)?[^。；\n]{0,12}?(?:备选|次选)",
         "把外部来源写成可选/次选（旧口径）"),
        (r"(?:也可换|也可以换|可换|允许换)[^。；\n]{0,10}?外部",
         "以『(也)可换外部』放宽来源（旧口径）"),
        (r"外部[^。；\n]{0,10}?(?:也可|也可以|亦可|同样可)",
         "以『外部也可』放宽来源（旧口径）"),
        (r"同源[^。；\n]{0,12}?(?:备选|次选)",
         "以『同源不可用时作备选』放宽来源（旧口径）"),
        (r"优先[^。；\n]{0,8}?(?:同源|外部来源)",
         "以『优先同源/优先外部来源』表达非强制（旧口径）"),
    )
    # 否定式排除：命中片段所在**分句**含任一禁止词时视为正当写法（禁止式 / 反例引用）
    NEGATION = ("不得", "禁止", "不可", "不允许", "不予", "不属", "不换", "不作",
                "不因", "不是", "勿", "忌", "反例", "误", "违规", "旧口径")
    CLAUSE_BREAK = "，；：（）()【】\n"
    for rel in ("specs/general/collab.adoc", "specs/general/verify.adoc",
                "specs/general/self-check.adoc",
                "specs-project-maintainer/priority.adoc",
                "specs-project-maintainer/verify.adoc"):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        for pat, desc in STALE_PATTERNS:
            for m in re.finditer(pat, text):
                # 取命中片段所在分句（以中英文标点/换行切分），再判定有无否定词。
                # **否定词只认紧邻命中片段的那一层**：若把整个长分句都算进来，
                # "不得点名外部 Agent / 外部 NPC、也允许换外部复核者当备选" 这类
                # **前半句禁止、后半句放宽**的句子会被误判为正当（本项目真实形态）。
                starts = [text.rfind(x, 0, m.start()) for x in CLAUSE_BREAK]
                st = max(starts) if starts else -1
                ends = [text.find(x, m.end()) for x in CLAUSE_BREAK]
                en = min([i for i in ends if i != -1] or [len(text)])
                clause = text[st + 1:en]
                # 以顿号/逗号再切一层，只取**命中片段紧邻的那一小段**判否定
                for seg in re.split(r"[、,]", clause):
                    if m.group(0) in seg and seg.strip():
                        clause = seg
                        break
                if any(w in clause for w in NEGATION):
                    continue
                err(f"执行者来源选择防线被破坏：{rel} 出现把外部来源**重新放宽**的写法"
                    f"（{desc}）：…{clause.strip()[:70]}…；公共侧已收紧为"
                    "『强制同 Agent、不得点名外部 Agent/NPC、不可用时降级为执行者本人串行"
                    "或如实标悬置』，任何写法都不得让外部来源重新成为合法路径"
                    "（禁止式表述与反例引用除外）", rel)
    phase_done()


def check_adoption_guard():
    """『接纳面防线』：公共内容被未知项目加载时的可控性（运行契约）不得被删。

"""
    phase("接纳面防线检查（未知项目加载）")
    # 运行契约的**单一落点**是 verify.adoc（testing.adoc / context.adoc 同名节只留一跳入口）
    rel_pub = os.path.join("specs", "general", "verify.adoc").replace(os.sep, "/")
    pub_path = os.path.join(REPO_ROOT, *rel_pub.split("/"))
    if not os.path.isfile(pub_path):
        err(f"缺少验证与运行契约文件 {rel_pub}——公共内容被未知项目加载时的可控性"
            "（运行契约）失去集中落点", rel_pub)
    else:
        with open(pub_path, encoding="utf-8") as fh:
            text = fh.read()
        if not re.search(r"^==+\s*运行契约", text, re.M):
            err(f"接纳面防线被破坏：{rel_pub} 缺失「运行契约」节——"
                "公共内容被未知项目加载时的可控性不得无人负责", rel_pub)
        for key, desc in (
                ("① 影响面", "不静默推翻引用方既有约定、冲突次序写明"),
                ("② 成本", "加载体积/时延开销/依赖要求可控且可说清"),
                ("③ 可控性", "不默认改动引用方工作区、不依赖引用方看不到的私有物、不阻断正常路径"),
                ("降级路径", "引入的机制/依赖须有不可用时的降级路径"),
                ("不得让引用方依赖本仓库私有物", "条目不得引用引用方看不到的私有脚本名/结构"),
                ("ISO 9241-110", "标准出处：可控、可预期、不阻断"),
                ("接纳面须留证", "新增/调整公共内容时逐维留证，未核对不得计入验证通过")):
            if key not in text:
                err(f"接纳面防线被破坏：{rel_pub} 缺失『{key}』（{desc}）——"
                    "未知项目加载的可控性判据不得被删或降级", rel_pub)
    # 维护方自己的承接清单：不得缺、且须指向公共判据
    rel_m = "specs-project-maintainer/context.adoc"
    m_path = os.path.join(REPO_ROOT, *rel_m.split("/"))
    if not os.path.isfile(m_path):
        err(f"缺少维护方接纳面清单 {rel_m}——维护方在新增公共内容时的核对职责无人承载", rel_m)
    else:
        with open(m_path, encoding="utf-8") as fh:
            mtext = fh.read()
        for key, desc in (("运行契约", "维护方的核对落点"),
                          ("影响面", "三维之一"),
                          ("成本", "三维之一"),
                          ("可控性", "三维之一")):
            if key not in mtext:
                err(f"接纳面防线被破坏：{rel_m} 缺失『{key}』（{desc}）", rel_m)
        if not os.path.isfile(PROJECT_FILE) or rel_m not in open(
                PROJECT_FILE, encoding="utf-8").read():
            err(f"{rel_m} 未在维护方项目规范入口 AGENTS.adoc 登记"
                "（不会被加载、其中规则实际失效）", "AGENTS.adoc")
    check_public_content_has_no_private_refs()
    check_public_content_is_self_contained()
    phase_done()



def check_ci_cd_guard():
    """『CI/CD 与平台协作防线』：CICD 校验链完整性与 CNB 对象钉定要点不得被删或降级。

"""
    phase("CI/CD 与平台协作防线检查")
    # ① CI/CD 规范：校验链完整 / 触发范围 / 依赖可用 / 超时
    rel_ci = "specs/general/ci-cd.adoc"
    ci_path = os.path.join(REPO_ROOT, *rel_ci.split("/"))
    if not os.path.isfile(ci_path):
        err(f"缺少 CI/CD 规范文件 {rel_ci}——"
            "流水线校验链完整性与超时等判据失去集中落点", rel_ci)
    else:
        with open(ci_path, encoding="utf-8") as fh:
            text = fh.read()
        for key, desc in (
                ("校验链完整", "流水线须跑全既定校验（含配套测试），防‘定义未执行’"),
                ("只跑主校验脚本", "把‘只跑主脚本’显式判为验证不完整"),
                ("须能被测试框架自动发现", "测试文件命名/位置须落在框架发现规则内"),
                ("触发路径须覆盖校验对象", "改了却不跑＝漏检"),
                ("须先确认实际可用", "上游镜像/制品/工具须实测可用，不得凭名称假设"),
                ("须有可判定的超时", "不得让流水线无限挂在 pending"),
                ("不在 CI 中调用会给出非确定性结论的外部 AI", "非确定性不得阻塞构建")):
            if key not in text:
                err(f"CI/CD 防线被破坏：{rel_ci} 缺失『{key}』（{desc}）——"
                    "踩坑判据不得被删或降级", rel_ci)
    # ② CNB 平台规范：对象钉定与可追溯 / 执行者可用性
    rel_cnb = "specs/platform/cnb.adoc"
    cnb_path = os.path.join(REPO_ROOT, *rel_cnb.split("/"))
    if not os.path.isfile(cnb_path):
        err(f"缺少 CNB 平台规范文件 {rel_cnb}——"
            "平台上的对象钉定与协作判据失去集中落点", rel_cnb)
    else:
        with open(cnb_path, encoding="utf-8") as fh:
            text = fh.read()
        for key, desc in (
                ("派发与复核须钉定 commit sha", "分支名不是稳定标识，须钉 sha"),
                ("压缩提交/强推会替换对象", "旧 sha 作废、结论须在新 sha 上重核"),
                ("先取得该分支当前指向的 sha", "取对象须取分支当前 sha，防本地缓存旧 sha（不写取法）"),
                ("派发前确认执行者实际可用", "镜像/制品 not found 时任务从未真正开始"),
                ("流水线不无界挂起", "平台 job/step 须可判定超时")):
            if key not in text:
                err(f"CNB 平台防线被破坏：{rel_cnb} 缺失『{key}』（{desc}）——"
                    "平台协作的踩坑判据不得被删或降级", rel_cnb)
    # ③ 相应的通用侧落点：验证须覆盖全部校验手段、验证对象钉定 sha（verify.adoc）
    rel_v = "specs/general/verify.adoc"
    v_path = os.path.join(REPO_ROOT, *rel_v.split("/"))
    if os.path.isfile(v_path):
        with open(v_path, encoding="utf-8") as fh:
            vtext = fh.read()
        for key, desc in (
                ("验证须覆盖项目的全部既定校验手段", "‘存在测试’≠‘测试被执行’"),
                ("验证对象须钉定 commit sha", "验证/复核前须先取定 sha")):
            if key not in vtext:
                err(f"CI/CD 防线被破坏：{rel_v} 缺失『{key}』（{desc}）", rel_v)
    # ④ 协作侧落点：派发对象钉定与执行者可用性（collab.adoc）
    rel_c = "specs/general/collab.adoc"
    c_path = os.path.join(REPO_ROOT, *rel_c.split("/"))
    if os.path.isfile(c_path):
        with open(c_path, encoding="utf-8") as fh:
            ctext = fh.read()
        for key, desc in (
                ("派发对象须钉定 commit sha", "派发指令须写明具体 sha"),
                ("派发前确认执行者可执行", "确认镜像/制品实际可取")):
            if key not in ctext:
                err(f"CI/CD 防线被破坏：{rel_c} 缺失『{key}』（{desc}）", rel_c)
    phase_done()

def check_self_check_guard():
    """『自检防线』：执行前自检规范与其必加载层落点不得被删或降级。

"""
    phase("自检防线检查")
    rel = os.path.relpath(SELF_CHECK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(SELF_CHECK_FILE):
        err(f"缺少执行前自检规范文件 {rel}——"
            "动手前的自检关口丢失（规范是否被实际加载与遵守将无兜底）", rel)
    else:
        with open(SELF_CHECK_FILE, encoding="utf-8") as fh:
            text = fh.read()
        # 「改动面按处读」那一问挂在清单的第⑤项上（证据条）。**它必须逐字可核**：
        # 本条的两处落点里，必加载层与通用层由 `check_dev_flow_guard` 核，**自检关口
        # 这一处只有本分支能核**——不核时整条从自检清单里被抽掉仍全绿（复核实测），
        # 而"动手前问不问这一句"正是本条要买的东西。**核的是那一问的判据本体**，
        # 不看编号与排版（编号顺序交人工 review）。
        for key, desc in (
                ("执行前自检清单", "动手前逐项自检的清单"),
                ("非平凡任务", "自检适用范围界定（防被'只对大任务'架空）"),
                ("不得顺口编造", "知识边界（不知道就说不知道、去查证）"),
                ("完成前自检", "交付前的对照核验"),
                ("动手改一个文件前是否先读了该文件里要改的那一处",
                 "自检关口对『要改的那一处读过没有』的那一问"),
                ("`specs/general/planning.adoc`「要改的那一处是否已实际读过",
                 "该问的判据回指（自检关口只说问什么、判据本体在通用层）")):
            if key not in text:
                err(f"自检防线被破坏：{rel} 缺失『{key}』（{desc}）——"
                    "自检要点不得被删或降级", rel)
    # 公共层（`specs/general/`）的规范文件由调度器登记；自检机制同时须有必加载层落点
    # （执行原则里的一行引用），否则"动手前自检"不会被任何入口触发。
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        if rel not in set(extract_specs_refs(fh.read(), "")):
            err(f"自检规范 {rel} 未在加载调度器登记（不会被加载、其中规则实际失效）",
                "AGENTS_COMMON.adoc")
    rel_exec = "specs/core/execution.adoc"
    exec_path = os.path.join(REPO_ROOT, rel_exec)
    if not os.path.isfile(exec_path):
        err(f"缺少 {rel_exec}，自检的必加载层落点丢失", rel_exec)
    else:
        with open(exec_path, encoding="utf-8") as fh:
            if "自检" not in fh.read():
                err(f"自检防线被破坏：{rel_exec} 缺失对「执行前自检」的落点——"
                    "自检要求未挂到必加载层，实际不会被触发", rel_exec)
    phase_done()


def check_verify_guard():
    """『规范验证防线』：验证口径（三视角/效力等级/总纲/规范验证）与其维护方落点不得被删。

"""
    phase("规范验证防线检查")
    rel_public = os.path.join("specs", "general", "verify.adoc").replace(os.sep, "/")
    path_public = os.path.join(REPO_ROOT, *rel_public.split("/"))
    if not os.path.isfile(path_public):
        err(f"缺少公共验证规范文件 {rel_public}——验证三视角、效力等级与运行契约失去落点",
            rel_public)
    else:
        with open(path_public, encoding="utf-8") as fh:
            pub = fh.read()
        for pat, desc in ((r"^==+\s*验证与运行契约", "「验证与运行契约」节（验证的公共口径）"),
                          (r"^==+\s*规范验证", "「规范验证」节（改完规范后的语义复核定式）"),
                          (r"^==+\s*验证总纲", "「验证总纲」节（验证什么、怎么算过、标准出自哪里）"),
                          (r"^==+\s*验证的效力等级", "「验证的效力等级」节（确定项/概念项与结论强度）"),
                          (r"^==+\s*验证的适用边界", "「验证的适用边界」节（先判改动性质）"),
                          (r"^==+\s*运行契约", "「运行契约」节（未知项目加载的可控性）")):
            if not re.search(pat, pub, re.M):
                err(f"规范验证防线被破坏：{rel_public} 缺失{desc}——验证的公共定式不得被删或降级",
                    rel_public)
        for key, desc in (
                ("判据本体验证", "确定项：机械校验按**判据本身**核对，不按引用形式近似"),
                ("概念项", "概念项：无确定性判据，只能启发式复核"),
                ("只能启发式复核", "概念项的可用手段：换角度/换机器/换样本增加独立核对"),
                ("未发现问题", "概念项的结论强度：只到'未发现问题'，不写成'通过'"),
                ("悬置", "未确证部分须逐项标悬置并写明已复核角度"),
                ("不得当作阻断交付的条件", "概念项不得作为交付的隐性前置条件"),
                ("①完整性", "视角一：对象在改动前后是否等价（核对未丢规则）"),
                ("②有效性与认知质量", "视角二：规范本体是否说得对、说得清、跑得动、判得了"),
                ("③接纳面", "视角三：被未知项目加载后的影响面/成本/可控性"),
                ("同一个干净子 agent", "三视角合用一个子 agent 一并回答（一次读取、结论分栏）"),
                ("每次验证都换一个干净上下文", "不复用发起改动/上一轮验证的上下文"),
                ("三态台账", "留证形态：通过 / 未发现问题 / 悬置三态分列、不得合并"),
                ("严格执行", "判准维度：严格执行（须逐次达成并给证据）"),
                ("尽力而为", "判准维度：尽力而为（须尝试、须说明、不记通过）"),
                ("如何验证", "验证对象不止规范文件（会被执行的产物同样要验）"),
                ("读的形态", "②的形态项：执行侧只给怎么走（重构最易丢的一条）"),
                ("ISO/IEC Directives Part 2", "标准出处：要求须可验证（防自造一套说法）"),
                ("RFC 2119", "标准出处：用语强度（要求与建议不得混用）"),
                ("ISO 10007", "标准出处：配置管理与变更控制"),
                ("ISO/IEC/IEEE 25010", "标准出处：质量特性（含性能效率）"),
                ("IEEE 1028", "标准出处：软件评审")):
            if key not in pub:
                err(f"规范验证防线被破坏：{rel_public} 缺失『{key}』（{desc}）——"
                    "验证的判定标准与标准出处不得被删或降级", rel_public)
    # 维护方落点：specs-project-maintainer/verify.adoc 须存在且含"三视角/悬置/超时"三要点
    rel_m = "specs-project-maintainer/verify.adoc"
    path_m = os.path.join(REPO_ROOT, *rel_m.split("/"))
    if not os.path.isfile(path_m):
        err(f"缺少维护方验证落点 {rel_m}——维护方自己的验证义务（三视角动作、硬超时、"
            "三态台账）失去集中落点", rel_m)
    else:
        with open(path_m, encoding="utf-8") as fh:
            mtext = fh.read()
        for key, desc in (("硬超时", "派发子 agent 必须自带可判定的时限"),
                          ("悬置", "查不出的部分如实标悬置、写明已复核角度"),
                          ("三态台账", "留证按三态分列、不得合并"),
                          ("完整性校验", "改完规范必做的完整性校验动作"),
                          ("check_checklist_guard", "维护方侧的具名抓手（文档↔脚本一致）")):
            if key not in mtext:
                err(f"规范验证防线被破坏：{rel_m} 缺失『{key}』（{desc}）——"
                    "维护方的验证义务不得被删或降级", rel_m)
    # 最高关注项 P2 的落点须指向公共验证口径
    rel_p2 = "specs-project-maintainer/priority.adoc"
    p2_path = os.path.join(REPO_ROOT, *rel_p2.split("/"))
    if not os.path.isfile(p2_path):
        err(f"缺少 {rel_p2}——最高关注项 P2 的落点丢失", rel_p2)
    else:
        with open(p2_path, encoding="utf-8") as fh:
            p2_text = fh.read()
        for key, desc in (("②有效性与认知质量", "P2 须声明语义复核的第二视角"),
                          ("③接纳面", "P2 须声明语义复核的第三视角（未知项目加载）"),
                          ("同一个干净子 agent", "P2 须声明三视角合用一个子 agent"),
                          ("验证的效力等级", "P2 须指向效力等级口径（结论强度按对象分档）"),
                          ("未发现问题", "P2 须声明复核结论只到'未发现问题'"),
                          ("悬置", "P2 须声明未确证部分标悬置（写明已复核角度）"),
                          ("不得当作阻断交付的条件", "P2 须声明概念项不得阻断交付")):
            if key not in p2_text:
                err(f"规范验证防线被破坏：{rel_p2} 的 P2 缺失『{key}』（{desc}）——"
                    "最高关注项 P2 的语义复核退化为只查完整性", rel_p2)
    # 本仓库落点：AGENTS.adoc 的完整性校验动作须与公共口径同源
    rel_own = "AGENTS.adoc"
    own_path = os.path.join(REPO_ROOT, *rel_own.split("/"))
    if os.path.isfile(own_path):
        with open(own_path, encoding="utf-8") as fh:
            own_text = fh.read()
        for key, desc in (("②有效性与认知质量", "本仓库的完整性校验动作须含第二视角"),
                          ("③接纳面", "本仓库的完整性校验动作须含第三视角"),
                          ("三视角合用一个子 agent", "本仓库须声明三视角合一次派发"),
                          ("未发现问题", "本仓库落点须区分'未发现问题'与'通过'")):
            if key not in own_text:
                err(f"规范验证防线被破坏：{rel_own} 的完整性校验动作缺失『{key}』（{desc}）——"
                    "本仓库维护口径须与公共口径一致", rel_own)


def check_public_content_has_no_private_refs():
    """公共内容不得把**本仓库私有物当成可执行抓手/可读文档**引用（③可控性的机械抓手）。

"""
    phase("公共内容私有引用检查（③可控性）")
    # 私有物名 → 说明；匹配时要求同行出现"维护语境"词，避免把合法提及误判为引用
    private_names = ("script/check_specs.py", "script/check_effective.py",
                     "script/clean_tmp.py", "PROMPTS.adoc", "AGENTS.adoc")
    context_words = ("本仓库", "本项目自身", "校验脚本", "机械校验", "工具声明",
                     "check_specs", "check_effective", "check_priority_guard",
                     "check_principle_guard", "check_verify_guard",
                     "check_adoption_guard", "check_source_guard",
                     "check_filler_docs", "CI 拦下")
    for f in [_rel_of(GENERIC_FILE)] + collect_adoc_files():
        rel = _rel_of(f)
        if rel == "AGENTS.adoc":
            continue  # 根 AGENTS.adoc 是项目自身内容，允许引用私有物
        if rel != "AGENTS_COMMON.adoc" and not rel.startswith("specs/"):
            continue  # 只检查公共内容（AGENTS_COMMON.adoc + specs/）；specs-project-maintainer/ 属维护方自有
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                if not any(w in line for w in context_words):
                    continue
                for name in private_names:
                    if f"`{name}" in line or f"link:{name}" in line:
                        err(f"公共内容不得把本仓库私有物『{name}』当作抓手/文档引用——"
                            "引用方看不到它、读到的只是死链；请改成自足的通用表述"
                            "（'维护规范集合的项目须自行设机械防线'一类）", rel, j)
    phase_done()


# 「自证不在默认引用面内」的括号说明：说明文档介绍图书馆时必然要点出它的路径，同时
# **同一句**里写明"引用方拿不到"。这类句子不是"把读者引过去"，故不算路径型引用。
# 判据落在**语义要素**（"不在默认引用面内"）而不是某个固定搭配上。
_SELF_EXCLUDING_NOTE = re.compile(r"[（(][^）)]*不(?:在|是|会)?[^）)]*默认引用面[^）)]*[）)]")


def _has_library_path_ref(line: str) -> bool:
    """该行是否含指向图书馆的**路径型**引用（`link:../library/x[]`、`library/x.adoc` 等）。

    只认路径形态（带 `library/` 目录前缀或 `link:` 指向它），不误伤两类正当表述：
    ① "图书馆"这个词本身（"依据落点在图书馆"给的是**依据名**而非可点开的路径）；
    ② 说明文档里**自证不在默认引用面内**的括号说明（同一句里已写明"引用方拿不到"）。
    """
    if "library/" not in line:
        return False
    if _SELF_EXCLUDING_NOTE.search(line):
        return False
    # 反引号路径、link: 目标、裸路径三种写法都算——**先取"去掉 `../` 前缀"的形态**
    # （公共内容里指图书馆要向上跳出 specs/，写作 `../../library/...`，
    # 若只匹配 `library/` 紧跟在 link:/反引号/空白之后，这种真实写法会漏掉）
    return bool(re.search(r"(?:link:|`|\s|^)(?:\.\./)*library/", line))


_PUBLIC_FACING_DOCS = ("README.adoc", "PROMPTS.adoc")

# 私有落点枚举里的①类（本仓库私有目录）与②类（本仓库私有文件，作为跨目录引用目标时）：
# 逐类给出「可机械判定的引用形态」与「为什么读者拿到的是死链」。
# 端点（协议头 `https://` / 文件名紧跟在 `link:`、反引号、空白之后）与 `_has_library_path_ref` 同源。
_PRIVATE_LOCATION_REFS = (
    (r"(?:link:|`|\s|^)(?:\.\./)*specs-project-maintainer/",
     "维护方自查层『specs-project-maintainer/』",
     "该层不是公共入口的加载项，引用方按公共输入加载时看不到该文件（读到的规则只成立一半）"),
    # ③类里的**文件级**私有落点——只把"本仓库的"这类文件算进来：`AGENTS.adoc` 作为
    # *引用方自己的*项目规范入口（公共内容通篇如此写）、`README.adoc` 作为*引用方项目
    # 模块级*索引页（`doc-module.adoc` 讲的就是它）都是正当表述，故两者**不列入**本枚举；
    # 能明确指到"本仓库"的是这两处。
    (r"(?:link:|`|\s|^)(?:\.\./)*PUBLIC\.adoc\b",
     "维护方公共内容索引『`PUBLIC.adoc`』",
     "它是维护方内容、不在默认引用面内，引用方项目里没有这份文件"),
    (r"(?:根|仓库根|项目根)\s*目录[^\n]{0,12}?CHANGELOG\.adoc",
     "本仓库根目录的『`CHANGELOG.adoc`』",
     "同一文件名在引用方项目里指它自己的变更日志，指向本仓库那份就是死链"),
)


def check_public_content_is_self_contained():
    """『公共内容自足性防线』：会被引用方读到 / 复制到未知项目执行的文本不得引用私有落点。

    约束对象见 `PUBLIC.adoc`「自足要求的适用范围」两类：①会被入口取到的
    （`AGENTS_COMMON.adoc` + `specs/**`）；②会被复制到未知项目执行的（`prompts/**`）。
    另按 `PUBLIC.adoc` 明写，**公开面说明文档**（`README.adoc` / `PROMPTS.adoc`）同受约束。

    本仓库实测失效（本轮）：`PROMPTS.adoc` 的公共约定里新加了一句把读者指向
    `AGENTS.adoc`（本仓库私有文件）的说明，当时 `check_public_facing_docs_stay_self_contained` /
    `check_no_mechanism_claims_in_public` / 本条**三条防线全绿**——它们只看
    `specs-project-maintainer/` 路径、防线声明与裸抓手名，不看**文件级**私有引用。
    故本条按 `PUBLIC.adoc` 的私有落点枚举**逐类**核，公开面文档一并纳入。
    """
    phase("公共内容自足性检查（不引用私有落点）")
    for f in [_rel_of(GENERIC_FILE)] + collect_adoc_files() + list(_PUBLIC_FACING_DOCS):
        rel = _rel_of(f)
        if rel == "AGENTS.adoc":
            continue  # 根 AGENTS.adoc 是项目自身内容，可引用任意私有落点
        # 自足受限集合 = ①会被入口取到的（AGENTS_COMMON.adoc + specs/**）
        #              ∪ ②会被复制到未知项目执行的（prompts/**）
        #              ∪ ③会被引用方阅读 / 在公开站点渲染的说明文档（README / PROMPTS）
        if rel != "AGENTS_COMMON.adoc" and not rel.startswith("specs/") \
                and not rel.startswith("prompts/") and rel not in _PUBLIC_FACING_DOCS:
            continue  # 其余（library/ 等）不属本条的约束对象
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                if _has_library_path_ref(line):
                    err(f"{'公开面文档' if rel in _PUBLIC_FACING_DOCS else '公共内容'}"
                        "不得引用图书馆『library/』——图书馆不在默认引用面内"
                        "（无公共加载项、引用方项目里也没有本仓库的文件）；"
                        "请把这条规则在公共内容里自足表达，或把它移出公共内容", rel, j)
                for pattern, name, why in _PRIVATE_LOCATION_REFS:
                    if not re.search(pattern, line):
                        continue
                    err(f"{'公开面文档' if rel in _PUBLIC_FACING_DOCS else '公共内容'}"
                        f"不得引用{name}——{why}；"
                        "请把这条规则在公共内容里自足表达，或把它移出公共内容", rel, j)
    phase_done()


def check_public_facing_docs_stay_self_contained():
    """『公开面文档自足性防线』：会被**分发给引用方/在公开站点渲染**的文档不得指向维护方自查层。

"""
    phase("公开面文档自足性检查（README/PROMPTS/公共入口 不指向维护方层）")
    for rel in ("README.adoc", "PROMPTS.adoc", "AGENTS_COMMON.adoc"):
        path = os.path.join(REPO_ROOT, rel)
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                if "specs-project-maintainer/" in line:
                    err("公开面文档不得给出维护方自查层『specs-project-maintainer/』的路径——"
                        "本文件会被引用方阅读/在公开站点渲染，该层不是公共入口的加载项，"
                        "引用方读到的是死链；请改为文字描述（'本仓库另有一层只对维护方成立'）"
                        "或删掉该链接", rel, j)
    phase_done()


def check_no_mechanism_claims_in_public():
    """公共内容不得**声明机械防线的存在**（防"机械防线随规范分发"的错觉）。

"""
    phase("公共内容不得声明机械防线检查（元信息）")
    claim_words = ("当前", "目前", "已由", "另有", "本仓库", "本项目")
    for f in [_rel_of(GENERIC_FILE), _rel_of(PROMPTS_FILE), _rel_of(README_FILE)] \
            + collect_adoc_files():
        rel = _rel_of(f)
        if rel == "AGENTS.adoc":
            continue  # 根 AGENTS.adoc 是项目自身内容，可以声明本仓库防线
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        if rel != "AGENTS_COMMON.adoc" and not rel.startswith("specs/") \
                and rel not in ("README.adoc", "PROMPTS.adoc"):
            continue  # 只检查公共内容与其说明文档；specs-project-maintainer/ 属维护方自有，可点名自家防线
        with open(path, encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                if "防线" in line and any(w in line for w in claim_words) \
                        and not any(w in line for w in ("应", "须", "要求")):
                    err("公共内容不得声明机械防线的存在（如'当前由某防线钉住''本仓库另有防线'）——"
                        "机械防线属维护规范集合的那一方，引用方既拿不到也不该依赖它；"
                        "请删掉该声明的元信息，或改成自足的通用表述"
                        "（'维护规范集合的项目应自行设机械防线'一类）", rel, j)
                m = re.search(r"check_[a-z]+_[a-z_]+", line)
                if m:
                    err(f"公共内容不得出现裸防线名『{m.group(0)}』——"
                        "它是私有抓手名，引用方看不到、也无法据此执行；"
                        "请删掉或改为通用表述（'机械防线'/'机械校验'）", rel, j)
    phase_done()


def check_source_guard():
    """『来源防线』：依据与来源真实性规范及其要点不得被删或降级。

"""
    phase("来源防线检查")
    rel = os.path.relpath(SOURCE_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(SOURCE_FILE):
        err(f"缺少依据与来源真实性规范文件 {rel}——"
            "引用真实性与『不得编造』失去集中落点", rel)
    else:
        with open(SOURCE_FILE, encoding="utf-8") as fh:
            text = fh.read()
        for key, desc in (
                ("真实存在", "内部引用须指向当前真实存在的目标"),
                ("不得编造", "标准编号/名称与事实不得凭印象生成"),
                ("宁可不引", "无法确证时的正确做法（不给不错）"),
                ("不附链接", "外部标准只写名称/编号、不附链接")):
            if key not in text:
                err(f"来源防线被破坏：{rel} 缺失『{key}』（{desc}）——"
                    "来源真实性要点不得被删或降级", rel)
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        if rel not in set(extract_specs_refs(fh.read(), "")):
            err(f"来源真实性规范 {rel} 未在加载调度器登记（不会被加载、其中规则实际失效）",
                "AGENTS_COMMON.adoc")
    phase_done()


# 提示词「主侧重（方向前提）」与「优先级规则」的机械防线口径：

#   * 每个提示词的侧重点用一段**块级短语**承载，形如 `**主侧重（…）**：**检查修复问题**——…`；
#     两侧分别锚定「主侧重」标签与「方向」标签，中间即侧重内容本身。
PRIMARY_LABEL = "主侧重"
PRIMARY_LINE = re.compile(
    r"\*\*主侧重[^*]*\*\*\s*[:：]\s*\*\*([^*]+)\*\*[^\n]*方向")
# 登记表侧重列：`| **<侧重>** | 主侧重片段 \`primary\``；侧重内容两侧的引号/星号
# 只为排版强调，比对时统一剥掉，避免"同一侧重、写法不同"被误判为未登记。
PRIMARY_ADOC = re.compile(
    r"\|\s*\*\*([^*|]+?)\*\*\s*\|\s*主侧重片段 `primary`")
# 提示词正文的「主侧重（方向性前提，先读）」段：`**主侧重（…）**：**<侧重>**——…`。
# 用更宽的行内锚点扫描，确保侧重值出现在正文说明段（而非仅在片段占位符里）。
PRIMARY_ANY = re.compile(
    r"\*\*主侧重[^*\n]*\*\*\s*[:：]\s*\*\*([^*|\n]+?)\*\*")


def _normalize_primary(text: str) -> str:
    """归一化侧重方向文本：去掉排版用的引号/星号/空白，便于登记表与正文比对。"""
    return text.strip().strip('"\'“”*').strip()
#   优先级规则归并用语（RFC 2119 / ISO shall-should-may 的对应关系），三级定义缺一即防线被破坏。
PRIORITY_TERMS = {
    "L1": ("必须", "严禁"),
    "L2": ("应当",),
    "L3": ("可以",),
}


def _iter_prompt_files():
    """列出公共任务提示词文档（`prompts/` 下非 `_` 前缀的 .adoc）。"""
    if not os.path.isdir(PROMPTS_DIR):
        return []
    return sorted(os.path.join(PROMPTS_DIR, f)
                  for f in os.listdir(PROMPTS_DIR)
                  if f.endswith(".adoc") and not f.startswith("_"))




def check_dev_flow_guard():
    """『开发流程防线』：先查现状/最佳方案/基线、大动先确认、不得另写一套、老用例不得改判，要点不得被删。

"""
    phase("开发流程防线检查")
    # ① 必加载层底线
    rel_ex = "specs/core/execution.adoc"
    path_ex = os.path.join(REPO_ROOT, *rel_ex.split("/"))
    if not os.path.isfile(path_ex):
        err(f"缺少文件 {rel_ex}——「先规划后执行」的底线无处承载", rel_ex)
    else:
        ex = open(path_ex, encoding="utf-8").read()
        run_rule_guard("check_dev_flow_guard")
    # ② 通用层展开
    rel_pl = "specs/general/planning.adoc"
    path_pl = os.path.join(REPO_ROOT, *rel_pl.split("/"))
    if not os.path.isfile(path_pl):
        err(f"缺少文件 {rel_pl}——动手前的现状/方案/基线口径失去**展开落点**"
            "（必加载层只剩底线，条件判据与判定标准无处可查）", rel_pl)
    else:
        pl = open(path_pl, encoding="utf-8").read()
        run_rule_guard("check_dev_flow_guard")
    # ②b 验证侧：覆盖全部既定校验手段 ≠ 手段/用例够用（基线完整性的验证侧口径）
    rel_v = "specs/general/verify.adoc"
    path_v = os.path.join(REPO_ROOT, *rel_v.split("/"))
    if not os.path.isfile(path_v):
        err(f"缺少文件 {rel_v}——验证侧口径无处承载", rel_v)
    else:
        v = open(path_v, encoding="utf-8").read()
        run_rule_guard("check_dev_flow_guard")
    # ②c 自检侧：**自检关口本身还在不在**——本分支挡的是"整份自检规范被删"（「要改的
    #    那一处读过没有」挂在自检关口上，关口没了就没人问它）。**自检清单里那一问的
    #    判据本体**由 `check_self_check_guard` 核（本分支不重复设第二份判据：判据只在
    #    能判定它的那处写一份）。
    rel_sc = "specs/general/self-check.adoc"
    path_sc = os.path.join(REPO_ROOT, *rel_sc.split("/"))
    if not os.path.isfile(path_sc):
        err(f"缺少文件 {rel_sc}——动手前的自检关口丢失，"
            "『要改的那一处读过没有』不再有人问", rel_sc)
    # ③ 测试侧：老用例不得为迁就改动而改判 + 兼容不了先确认
    rel_t = "specs/general/testing.adoc"
    path_t = os.path.join(REPO_ROOT, *rel_t.split("/"))
    if not os.path.isfile(path_t):
        err(f"缺少文件 {rel_t}——回归/兼容口径无处承载", rel_t)
    else:
        t = open(path_t, encoding="utf-8").read()
        run_rule_guard("check_dev_flow_guard")
    # ④ 提示词侧：两个片段须在，且两个提示词都引入
    rel_cf = os.path.relpath(COMMON_PROMPT_FILE, REPO_ROOT).replace("\\", "/").replace(os.sep, "/")
    if not os.path.isfile(COMMON_PROMPT_FILE):
        err(f"缺少提示词公共片段 {rel_cf}——基线/兼容口径无处承载", rel_cf)
    else:
        cf = open(COMMON_PROMPT_FILE, encoding="utf-8").read()
        run_rule_guard("check_dev_flow_guard")
    files = _iter_prompt_files()
    if not files:
        err("prompts/ 下未找到任何任务提示词文档（除 `_` 前缀公共片段外）", "prompts/")
    for f in files:
        rel_f = os.path.relpath(f, REPO_ROOT).replace(os.sep, "/")
        ftext = open(f, encoding="utf-8").read()
        for tag in ("baseline-and-compat", "compat"):
            if f"include::_common.txt[tag={tag}]" not in ftext:
                err(f"开发流程防线被破坏：{rel_f} 未引入公共片段 `{tag}`——"
                    "题面未装配该边界，AI 按此提示词执行时读不到它", rel_f)
        # 需求侧先找参照物：题面里须有一句可执行的检索要求（只靠公共片段不够——
        # 两个提示词的动手前步骤各有一处自行表述的"先调研最佳方案"，那里也得带上它）
        if not (("调整内容一类需求" in ftext or "调整内容一类改动" in ftext)
                and "更优的设计" in ftext):
            err(f"开发流程防线被破坏：{rel_f} 的动手前步骤缺『调整内容一类需求/改动须先检索"
                "现成可参照的标准与更优设计』——公共片段里写了，题面自己的那处表述也得同口径",
                rel_f)
    # ⑤ 登记同步：调度器 + 公开面
    rel_d = "AGENTS_COMMON.adoc"
    dpath = os.path.join(REPO_ROOT, rel_d)
    if os.path.isfile(dpath):
        dt = open(dpath, encoding="utf-8").read()
        if "specs/general/planning.adoc" not in dt:
            err(f"开发流程防线被破坏：{rel_d} 未登记 `specs/general/planning.adoc`——"
                "该文件不会被加载，其中规则实际失效", rel_d)
    else:
        err(f"缺少 {rel_d}——加载调度器无处登记 planning.adoc", rel_d)
    rel_p = os.path.relpath(PROMPTS_FILE, REPO_ROOT).replace(os.sep, "/")
    if os.path.isfile(PROMPTS_FILE):
        pt = open(PROMPTS_FILE, encoding="utf-8").read()
        for key in ("baseline-and-compat", "compat", "先定基线", "更优的设计"):
            if key not in pt:
                err(f"开发流程防线被破坏：{rel_p} 公开面缺失『{key}』——"
                    "提示词的公共约定须登记该边界（公开面漏了这层则复制出去的那份没有）", rel_p)
    else:
        err(f"缺少 {rel_p}——公开提示词入口未登记该边界", rel_p)
    rel_r = os.path.relpath(README_FILE, REPO_ROOT).replace(os.sep, "/")
    if os.path.isfile(README_FILE):
        rt = open(README_FILE, encoding="utf-8").read()
        for key in ("先定基线", "既有用例不得为迁就改动而改判"):
            if key not in rt:
                err(f"开发流程防线被破坏：{rel_r} 使用要点未同步『{key}』", rel_r)
    else:
        err(f"缺少 {rel_r}——公开面说明无处承载", rel_r)
    phase_done()


def check_checklist_guard():
    """『清单逐项与文档-脚本一致性防线』：把"可机械核对却被漏掉"的判定点补成抓手。

"""
    phase("清单逐项与文档-脚本一致性防线检查")

    # 1) 准入判定：自称"九问"则条目须为 9 条
    rel_sl = "specs-project-maintainer/spec-lifecycle.adoc"
    sl_path = os.path.join(REPO_ROOT, *rel_sl.split("/"))
    if os.path.isfile(sl_path):
        with open(sl_path, encoding="utf-8") as fh:
            sl = fh.read()
        m = re.search(r"== 准入判定.*?(?=\n== )", sl, re.S)
        if m is None:
            err(f"{rel_sl} 未找到「准入判定」节——准入清单的项数失去抓手", rel_sl)
        else:
            items = re.findall(r"^\. \*\*", m.group(0), re.M)
            claim = re.search(r"准入判定\*\*（([一二三四五六七八九十]+)问", m.group(0))
            if claim is None:
                err(f"{rel_sl} 的「准入判定」未声明项数（形如『九问』）——"
                    "项数不写就无法核对该收的条目有没有被少列", rel_sl)
            else:
                num_map = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6,
                           "七": 7, "八": 8, "九": 9, "十": 10}
                want = num_map.get(claim.group(1))
                if want is not None and len(items) != want:
                    err(f"{rel_sl}「准入判定」自称 {claim.group(1)}问、实际列出 "
                        f"{len(items)} 条——清单被增删而声明未同步（读者按声明核对会漏项）",
                        rel_sl)

    # 2) 任务生命周期：七节点须逐个在表中出现
    rel_ex = "specs/core/execution.adoc"
    ex_path = os.path.join(REPO_ROOT, *rel_ex.split("/"))
    if os.path.isfile(ex_path):
        with open(ex_path, encoding="utf-8") as fh:
            ex = fh.read()
        m = re.search(r"== 任务生命周期与节点自查.*?(?=\n== )", ex, re.S)
        if m is None:
            err(f"{rel_ex} 未找到「任务生命周期与节点自查」节", rel_ex)
        else:
            for node in ("提出", "理解", "方案", "执行", "验证", "交付", "复盘"):
                if f"| **{node}**" not in m.group(0):
                    err(f"{rel_ex}「任务生命周期与节点自查」表中缺少节点『{node}』——"
                        "节点被删则该节点的自查要求实际失效", rel_ex)
            # 效力标法须写明（防"哪些节点 L1、哪些仅公共内容改动"再次含混）
            for key in ("仅公共内容改动", "哪些节点不设"):
                if key not in m.group(0):
                    err(f"{rel_ex}「任务生命周期与节点自查」缺少『{key}』——"
                        "节点效力标法（哪些节点对任何任务成立、哪些仅公共内容改动）"
                        "不得被含糊掉", rel_ex)

    # 3) 复核机制的可执行性：硬超时与三态留证须仍在（防"防卡死"与"留证"退化回口号）
    rel_v = "specs-project-maintainer/verify.adoc"
    v_path = os.path.join(REPO_ROOT, *rel_v.split("/"))
    if os.path.isfile(v_path):
        with open(v_path, encoding="utf-8") as fh:
            vtext = fh.read()
        # 钉"整条要求仍在"而非"关键词出现过一次"——须同时命中该条的多处要素，
        # 否则别处一句"三态"字样即可让检查假绿（这正是本防线要防的失效模式）。
        run_rule_guard("check_checklist_guard")
    rel_c = "specs/general/collab.adoc"
    c_path = os.path.join(REPO_ROOT, *rel_c.split("/"))
    if os.path.isfile(c_path):
        with open(c_path, encoding="utf-8") as fh:
            ctext = fh.read()
        run_rule_guard("check_checklist_guard")

    # 4) 文档↔脚本一致性：文档里点名的 check_* / 脚本名须真实存在
    script_names = set()
    script_dir = os.path.join(REPO_ROOT, "script")
    if os.path.isdir(script_dir):
        script_names = set(os.listdir(script_dir))
    with open(os.path.join(REPO_ROOT, "script", "check_specs.py"), encoding="utf-8") as fh:
        self_src = fh.read()
    defined = set(re.findall(r"^def (check_[a-z_]+)\(", self_src, re.M))
    # 校验范围含**维护方内容**（AGENTS.adoc、PUBLIC.adoc）：它们同样会点名 `check_*` 与
    # 脚本名，改名/删除后不同步即"声称有防线而防线不存在"。
    for rel in ("AGENTS.adoc", "PUBLIC.adoc", "README.adoc"):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        for name in sorted(set(re.findall(r"`(check_[a-z_]+|clean_tmp\.py|check_specs\.py|"
                                          r"check_effective\.py)`", text))):
            if name.endswith(".py"):
                if name not in script_names:
                    err(f"{rel} 点名了不存在的脚本 `{name}`——"
                        "文档声称的抓手与 script/ 实际不一致", rel)
            elif name not in defined:
                err(f"{rel} 点名了脚本中未定义的 `{name}`——"
                    "防线的声称与实现不一致（改名/删除后未同步文档）", rel)
    phase_done()


# 『重命名与内容修改须分两个提交防线』要点（每条须同时命中多处要素，否则别处一句同名字样即可假绿）
# 本节的条目轴（小标题）——逐项须在，防"整条 bullet 被摘掉、正文并入相邻条目"这一形态
# 『运行环境须与项目声明一致』（`specs/general/ci-cd.adoc`）——用户提出的硬性要求：
# 项目里声明的运行环境（jdk1.8、python2 等）就是开发与验证**唯一**可用的环境，
# **换个版本也能跑通也不得换**。本条最易被三条路径绕过——①"另一个版本也跑通了"（结果导向
# 的自我豁免）、②用等价/兼容/近似版本顶替（大版本相同即可自圆其说）、③环境声明缺失或不可得
# 时直接用环境默认版本开工并记作通过。故机械钉住：条文与 L1 标注、判据形态（"不一致即违规"
# 与"能跑通不是理由"两句须在）、**声明落点**（取项目已有声明、不得另立第二真源）、
# **降级路径**（未声明先确认 / 不可得时标未确证、不得记为通过）、依据行，以及三处引用
# （必加载层、验证、基线）与调度器两处识别特征——它们缺一，本条就只在 CI 场景生效或读不到。
# 判据能否覆盖"某个具体项目该怎么取版本"属语义判断，交人/子 agent 复核。
RUNTIME_ENV_SECTION = "运行环境须与项目声明一致"

