def check_java_object_template_guard():
    """『Java 数据对象模板防线』：模板文件与判据本体两处都不得被删、被合或降级。

    用户口径：数据对象模板属"**要么不读、要么整份读完**"的产物，故**单列成模板文件**、
    不并进 `specs/stack/java.adoc`；判据本体必须留在规范文件里。失效形态有四类：
      * **模板文件被删或被并回规范** —— 回到"撑大规范正文、而它又不一定被读"；
      * **判据本体从规范文件里消失** —— 只剩一份清单，读者不知道"为什么补注解时
        已提交的类默认不加 `@Accessors`"，于是"补注解也加上吧"重新成立（看起来只是多一个注解）；
      * **加载门丢了** —— 新建对象时该文件永不被加载，模板形同不存在；
      * **三处取值被删或降级** —— 无参 `@AllArgsConstructor`、集合 `@Singular` 两条各自
        都可能被当成风格偏好顺手去掉；
      * **生效面被当不存在** —— `@Accessors` 补注解时的两档（**类已提交默认不补 /
        类未提交可以补**）与 **review 面**（未主动声明要补时，既有对象缺这套注解
        **不构成问题、review 不得据此提出问题**）都是**容易被当成"没写也一样"**的边界，
        缺则补注解一律都加、或 review 把存量缺注解报成问题。
    故逐组核模板文件与规范文件的**可核对那句话**（取值 + 机制 + 判定标准 + 依据；锚点与
    分组见 `script/specs-rules/java.toml`），并核调度器登记与 README 同步。"某个类算不算
    数据对象、代码里到底标没标"属语义判断与运行时事实（见 `GUARD_CHECK_LIMITS`），
    交人/子 agent 复核。
    """
    phase("Java 数据对象模板防线检查")
    rel_tpl = JAVA_OBJECT_TEMPLATE_FILE
    if not os.path.isfile(os.path.join(REPO_ROOT, *rel_tpl.split("/"))):
        err(f"缺少 {rel_tpl}——『Java 数据对象模板』的模板本体丢失"
            "（该条是 Java 栈专属、且是「要么不读、要么整份读完」的产物，"
            "故单列为模板文件而**不并进** `specs/stack/java.adoc`）", rel_tpl)
    else:
        run_rule_guard("check_java_object_template_guard")
    # 判据本体：`specs/stack/java.adoc`「编码」里的「数据对象模板」条——先确认**条目还在**
    # （标题级，条目整条被删时给出可读的报错），再逐组核条目正文的锚点（锚点在
    # `script/specs-rules/java.toml` 的 `file_groups` 里）。
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——『数据对象模板』的判据本体无处承载"
            "（模板文件只给整段清单，判据必须留在规范文件里）", rel_java)
    else:
        text = open(JAVA_STACK_FILE, encoding="utf-8").read()
        if f"**{JAVA_OBJECT_TEMPLATE_SECTION}" not in text:
            err(f"Java 数据对象模板防线被破坏：{rel_java}「编码」缺少"
                f"`* **{JAVA_OBJECT_TEMPLATE_SECTION}` 条目——判据本体不在规范文件里时，"
                "模板文件成了第二真源（两处各自漂移），或读者只拿到清单、不知道"
                "『为什么补注解时已提交的类默认不加 `@Accessors`』", rel_java)
        run_rule_guard("check_java_object_template_guard")
    phase_done()


def check_java_interface_accessor_guard():
    """『Java 字段接口只加 get、不加 set 防线』：判据本体不得被删或降级到类上。

    用户点名：设计字段接口时**只允许添加 get 方法、禁止添加 set 方法**（除非主动声明，
    已经有的不管也不告警）——**因为下游可能添加 `@Accessors(chain = true)`，会产生编译
    问题**；下一轮澄清「**是接口不是类**」（本条只约束接口，类不受约束）。

    本条**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "「编码」这一节在不在"属防线空转——最易被四件事冲掉：
      * **判定面被放大** —— "只约束接口"这半句丢了，正常类的 lombok setter 被大面积判红；
      * **理由被抽** —— `@Accessors(chain = true)` 与"编译不过"一丢，读者不知道要防什么，
        于是"接口不加 set 怎么写入"会把 setter 补回去；
      * **存量口径被删** —— "已经有的不管、也不告警"丢字，L1 被扩到存量接口上；
      * **豁免被删或泛化** —— "除非主动声明"丢了声明过的场景被判红，没了"不得泛化"
        则一次声明被套到整个模块。
    故逐条核 `JAVA_INTERFACE_ACCESSOR_RULES`（每项要求"规则 + 判定标准 + 边界"里的
    **可核对那句话**），并核调度器识别特征、README 同步与图书馆两处落点。
    "某个接口算不算字段接口、某次是否真的只动了新增接口"属语义判断与运行时事实
    （见 `GUARD_CHECK_LIMITS`），交人/子 agent 复核。
    """
    phase("Java 字段接口只加 get、不加 set 防线检查")
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——『字段接口只加 get、不加 set』的落点丢失"
            "（该条是 Java 栈专属——`interface` 与 lombok 的 `@Accessors` 都是 Java 侧概念，"
            "须收在技术栈层而非通用层）", rel_java)
    else:
        text = open(JAVA_STACK_FILE, encoding="utf-8").read()
        # 逐条核**本条自己的正文**（不是整文件）：`不适用本条` 一类字样在 java.adoc 里
        # 不止一处，按整文件核时相邻条目的字会兜住已消失的要求（本仓库实测复现）。
        rule_text = _java_interface_accessor_rule_text(text) or text
        for keys, desc in JAVA_INTERFACE_ACCESSOR_RULES:
            missing = [k for k in keys if k not in rule_text]
            if missing:
                err(f"字段接口访问器防线被破坏：{rel_java}「编码」缺失要点 {missing}——{desc}；"
                    "该条对应用户提出的真实要求（下游加 `@Accessors(chain = true)` 时"
                    "接口里的 setter 会让下游编译不过），不得删除、不得降级为建议、"
                    "不得把判定面放大到类上", rel_java)
    # 通用层不得另立第二真源：该条的判据只在技术栈层说得清（`interface`/lombok 都是 Java 专名），
    # 通用层若也写一份，两处必各自漂移（读者按通用层学到的与栈层不一致）。
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(CODING_FILE):
        ctext = open(CODING_FILE, encoding="utf-8").read()
        if "@Accessors" in ctext:
            err(f"字段接口访问器防线被破坏：{rel_coding} 出现框架专名 `@Accessors`——"
                "该条是 Java 栈专属，通用层再写一份即第二真源（替换主语测试）", rel_coding)
    # 调度器识别特征（缺则写字段接口时该条永不被触发加载、规则实际失效）
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(GENERIC_FILE):
        ct = open(GENERIC_FILE, encoding="utf-8").read()
        for keys, desc in (
            (("字段接口只加 get 不加 set", "@Accessors(chain = true)"),
             "Java 技术栈条目的识别特征：须含本条的识别特征与**下游可能加 "
             "`@Accessors(chain = true)`** 这一触发条件，否则写字段接口时不会加载本条"),
        ):
            missing = [k for k in keys if k not in ct]
            if missing:
                err(f"字段接口访问器防线被破坏：{rel_common} 缺失要点 {missing}——{desc}",
                    rel_common)
    # 公开说明同步（README 目录说明；缺则读者按 README 学习时无从知道有这条规则）
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE) and "字段接口只加 get" not in open(
            README_FILE, encoding="utf-8").read():
        err(f"{rel_readme} 的目录说明未同步『字段接口只加 get、不加 set』——"
            "本条新增了 Java 栈条文，读者按 README 学习时无从知道有这条规则", rel_readme)
    # 图书馆两处落点：① 取向登记（防读成标准规定）；② 依据段（防依据只存名称）
    for rel, keys, desc in (
        ("library/adoption.adoc",
         ("字段接口只加 get、不加 set", "本集合自己的判据化取舍", "是接口不是类",
          "主动声明", "存量不管"),
         "图书馆取向登记：须写明这是本集合更严的取舍、如实标注外部材料**未**规定，"
         "并记清『只约束接口』与用户原话口径——缺则读者会把它读成 lombok 或某标准的明文"),
        ("library/sources.adoc",
         ("字段接口的访问器与 lombok 链式风格", "@Accessors(chain = true)",
          "返回类型与接口签名不一致", "同义性"),
         "图书馆依据段：须有该主题段与机制要点（`@Accessors(chain = true)` 的返回类型与"
         "接口的 `void` 签名不一致 ⇒ 编译失败）及同义性标注——缺则依据只存名称、"
         "日后无从核对『它今天还成立吗』"),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少 {rel}——本条取舍的依据无处核对", rel)
            continue
        ltext = open(path, encoding="utf-8").read()
        missing = [k for k in keys if k not in ltext]
        if missing:
            err(f"字段接口访问器防线被破坏：{rel} 缺失要点 {missing}——{desc}", rel)
    phase_done()


# 枚举查找的空 `catch`（`specs/stack/java.adoc`「健壮性」 + 通用层判据本体）：
# **用户点名**的规范调整——"java 下 `Enum.valueOf` 例外，这里的异常只有可能是值没匹配上，
# 还有其他自己写的枚举工具，允许空 catch"。
# 这是 L1「不得吞异常」的**唯一放宽口**，故失效形态不是"没写例外"，而是**例外被读宽**：
#   ① 「允许空 `catch`」被抄成通用豁免，把 L1 的其余部分（不得吞异常、对外输入一律校验）顶掉；
#   ② 准入条件（异常语义单一 + 取默认值即业务语义）与判定标准被压成一句口号——
#      此后任何 `catch (Exception) {}` 都能自证"我这是枚举查询"；
#   ③ **扩大的两个方向**没被排除：写成 `catch (Throwable)`/`catch (Exception)` 的**类级空
#      `catch`**（把同一个 `try` 里其他语句的异常一并吞掉）、给"本身已返回默认值"的调用点
#      再补一个空 `catch`。
# 故防线钉**判据本体**（准入三条、判定标准、两类扩大的排除、仍须写理由注释），不钉轴名
# （只核"「健壮性」这一节在不在"属防线空转）。锚点与分组见
# `script/specs-rules/java.toml` 的 `check_java_enum_valueof_catch_guard`；接线处须写字面量
# （`run_rule_guard("check_java_enum_valueof_catch_guard")`）——规则接线完整性由
# `script/rules_engine_test.py` 按字面量核对，抽成常量时它核不到（本轮实测）。


def check_java_enum_valueof_catch_guard():
    """『Java 枚举查找空 catch 防线』：条件例外不得被删、被读宽或被压成口号。

    用户口径：`Enum.valueOf` 的异常**只有可能是值没匹配上**，另有"自己写的枚举工具"，
    故 Java 下允许空 `catch`——但要紧的是**例外只此一种形态**：判据本体（三条准入 +
    判定标准 + 两类扩大方向的排除）落在通用层 `specs/general/coding.adoc`「代码质量
    （新产出即高质）」的「显式处理失败与边界」，Java 侧只给落点与反面清单
    （`specs/stack/java.adoc`「健壮性」）。两处**互为落点、不得各写一份判据**。

    "某个 `catch` 块今天算不算命中例外"属**语义判断**（该 API 的异常是不是只有一种原因、
    该调用点的失败是否另有出口），机械只能核对"判据本体在不在"——交人/子 agent 复核。
    """
    phase("Java 枚举查找空 catch 防线检查")
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——『枚举查找空 catch』的 Java 落点丢失"
            "（`Enum.valueOf` 与自写枚举工具都是 Java 侧概念，须落在技术栈层）", rel_java)
    else:
        run_rule_guard("check_java_enum_valueof_catch_guard")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——『显式处理失败与边界』的通用层落点丢失"
            "（条件例外的准入判据跨语言，须收在通用编码规范）", rel_coding)
    else:
        run_rule_guard("check_java_enum_valueof_catch_guard")
    # 图书馆侧：本集合更严/更宽的取舍须登记（防读者把"允许空 catch"读成 JDK 或某标准的规定），
    # 且依据段须如实标注外部材料**只给机制**、未规定准入条件。
    for rel, keys, desc in (
        ("library/adoption.adoc",
         # 锚点只取"是本集合自己的判据化取舍"这一句**不带标记**的形态：真实文件里加粗标记的
         # 位置在本条与邻居处**不一致**（本条写「...（条件例外，L2）是本集合的...」、邻居写
         # 「...取舍**：」），带 `**` 的锚点会因"锚点与正文不同形"恒缺（本轮实测）。
         ("Enum.valueOf", "是本集合自己的判据化取舍", "唯一放宽口"),
         "图书馆取向登记：须写明这是本集合自己的取值、外部材料只给机制，"
         "并点明它是「不得吞异常」这条 L1 的唯一放宽口——缺则该例外会被读成 JDK 或某标准的规定"),
        ("library/sources.adoc",
         ("Enum.valueOf", "同义性", "未逐字取回"),
         "图书馆依据段：须有该主题段、机制要点与同义性标注（API 文档给的是"
         "「什么条件下抛哪个异常」，不是「该不该吞」）——缺则依据只存名称、日后无从核对"),
    ):
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            err(f"缺少 {rel}——本条取舍的依据无处核对", rel)
            continue
        ltext = open(path, encoding="utf-8").read()
        missing = [k for k in keys if k not in ltext]
        if missing:
            err(f"Java 枚举查找空 catch 防线被破坏：{rel} 缺失要点 {missing}——{desc}", rel)
    # 加载门：调度器的 Java 技术栈条须给出识别特征（缺则该条永远不会被加载——
    # 写规则与登记是同一个动作，与 `check_java_object_template_guard` 同口径）。
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少 {rel_common}——『枚举查找空 catch』的加载门丢失"
            "（识别特征不登记时本条永不被加载）", rel_common)
    else:
        if "枚举查找的失败处理" not in open(GENERIC_FILE, encoding="utf-8").read():
            err(f"Java 枚举查找空 catch 防线被破坏：{rel_common} 未登记识别特征"
                "（`Enum.valueOf` 一类查找式调用）——缺则写这类调用时该条永不被加载，"
                "例外形同不存在", rel_common)
    phase_done()


def check_doc_type_notation_guard():
    """『文档类型指代（类名 + import）防线』：文档里写类名、不写类全名。

"""
    phase("文档类型指代（类名 + import）防线检查")
    rel_doc = os.path.relpath(DOC_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(DOC_FILE):
        err(f"缺少文件 {rel_doc}——『文档中类型指代写类名 + import』的通用层落点丢失"
            "（该条跨语言，须收在通用文档规范而非某一技术栈）", rel_doc)
    else:
        text = open(DOC_FILE, encoding="utf-8").read()
        run_rule_guard("check_doc_type_notation_guard")
    # Java 栈落点
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——『类名 + import』的 Java 落点丢失"
            "（javadoc 里的具体写法与 {@link} 成员引用须全限定这条边界只在栈层说得清）",
            rel_java)
    else:
        jt = open(JAVA_STACK_FILE, encoding="utf-8").read()
        missing = [k for k in ("全限定类名", "{@link", "import",
                               "com.c332030.ctool4j.core.exception.CUnauthorizedException",
                               "不在本仓库的 classpath 内")
                   if k not in jt]
        if missing:
            err(f"文档类型指代防线被破坏：{rel_java} 缺失要点 {missing}——"
                "Java 栈须给出具体写法（短类名 + import 语句）、用户给出的类全名实例，"
                "并写明 {@link}/@see 的成员引用与配置/反射按名加载照常全限定",
                rel_java)
    # 加载调度器两处识别特征（缺则该条永远不会被加载）
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(GENERIC_FILE):
        ct = open(GENERIC_FILE, encoding="utf-8").read()
        run_rule_guard("check_doc_type_notation_guard")
    phase_done()


def check_conversion_guard():
    """『对象转换防线』：多层嵌套对象的转换保持"首选声明式映射 + 手写须备注原因"的口径。

"""
    phase("对象转换（多层嵌套对象优先声明式映射）防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「对象转换（多层嵌套对象的转换）」的通用层落点丢失"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    else:
        text = open(CODING_FILE, encoding="utf-8").read()
        run_rule_guard("check_conversion_guard")
        # 建议层口径：条文与判据不得被写成强制面（用户明确要求不做强制性限制）
        for token in ("不允许手写转换代码", "不得手写转换代码", "一律用既有转换库"):
            if token in text:
                err(f"对象转换防线被破坏：{rel_coding} 出现强制措辞 `{token}`——"
                    "用户口径是「优先用、建议不手写」（不是强制，但是建议）；"
                    "写成硬约束即与用户「不做强制性限制」相抵，且与判据的目标式口径不一致",
                    rel_coding)
        # 范围不得被抄窄成按字段数判（无嵌套＝本条不管，与字段数量无关）
        if re.search(r"三(两|个)字段|两三个字段|字段数(量)?(少于|以内|不超过)", text):
            err(f"对象转换防线被破坏：{rel_coding} 把取值范围写成了**按字段数判**——"
                "用户口径是「无嵌套（单层）不管」，与字段数量无关；"
                "按字段数判会把「扁平但字段多」的对象误判进范围、也会把「嵌套但字段少」的漏掉",
                rel_coding)
        # 通用层不得出现框架专名（替换主语测试：本文件适用于所有编程语言）
        for token, desc in (
            ("MapStruct",
             "通用层不得点名 `MapStruct`——它是具体库名，充当规则主语时该规则对非 JVM 项目"
             "不成立（替换主语测试），且会被无条件随「编写代码」带进非 JVM 项目的上下文"),
            ("@Mapper",
             "通用层不得点名 `@Mapper` 一类注解——具体框架写法归技术栈层"),
            ("@Mapping",
             "通用层不得点名 `@Mapping` 一类注解——具体框架写法归技术栈层"),
        ):
            if token in text:
                err(f"对象转换防线被破坏：{rel_coding} 出现框架专名 `{token}`——{desc}；"
                    "通用层只留跨语言抽象，框架专名与写法下沉到 `specs/stack/` 对应文件",
                    rel_coding)
    # Java 栈落点：优先 MapStruct（建议）+ 嵌套/集合表达 + 不并存两套 + 非强制 + 例外 + 存量
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——对象转换的 Java 技术栈落点丢失（框架专名的唯一落点）",
            rel_java)
    else:
        jtext = open(JAVA_STACK_FILE, encoding="utf-8").read()
        run_rule_guard("check_conversion_guard")
        for token in ("不允许手写转换代码", "不得手写转换代码"):
            if token in jtext:
                err(f"对象转换防线被破坏：{rel_java} 出现强制措辞 `{token}`——"
                    "本集合口径是「优先用、建议不手写」（不是强制，但是建议）",
                    rel_java)
    # 加载调度器：通用层（去框架专名）+ Java 栈（含 MapStruct 与建议口径）
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少加载调度器 {rel_common}", rel_common)
    else:
        ctext = open(GENERIC_FILE, encoding="utf-8").read()
        run_rule_guard("check_conversion_guard")
        # 通用层调度条目不得带框架专名（识别特征要触发"写转换代码"而不是"Java 项目"）
        start = ctext.find("  ** 编写代码 →")
        end = ctext.find("\n  ** ", start + 1)
        if start != -1 and end != -1:
            entry = ctext[start:end]
            for token in ("MapStruct", "@Mapper", "@Mapping"):
                if token in entry:
                    err(f"对象转换防线被破坏：{rel_common} 的通用层『编写代码』调度条目"
                        f"出现框架专名 `{token}`——通用层识别特征不得点名具体库/注解"
                        "（否则非 JVM 项目也被带入该库术语、且与归属层冲突）",
                        rel_common)
    # 公开面：README 目录说明（读者按 README 学习时须能看到这条存在、且两层口径一致）
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE):
        rtext = open(README_FILE, encoding="utf-8").read()
        missing = [k for k in ("对象转换", "优先", "建议不手写") if k not in rtext]
        if missing:
            err(f"{rel_readme} 的目录说明未同步对象转换条（缺 {missing}）——"
                "公开面看不到这条，或口径与条文不一致（如仍写「不允许手写」）", rel_readme)
    # 图书馆侧：依据落点（引文/同义性/实证须可查到，且如实标注取样状态）
    rel_sources = "library/sources.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_sources)):
        stext = open(os.path.join(REPO_ROOT, rel_sources), encoding="utf-8").read()
        missing = [k for k in ("多层嵌套对象转换用声明式映射", "同义性", "未逐字取回")
                   if k not in stext]
        if missing:
            err(f"对象转换防线被破坏：{rel_sources} 缺失要点 {missing}——"
                "依据落点须有该条并写明同义性差异（标准只给方向与下限、"
                "判据化取值属本集合取舍）与如实取样状态，不得让依据只剩名称",
                rel_sources)
    rel_adoption = "library/adoption.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_adoption)):
        atext = open(os.path.join(REPO_ROOT, rel_adoption), encoding="utf-8").read()
        missing = [k for k in ("多层嵌套对象转换", "mapstruct", "建议") if k not in atext]
        if missing:
            err(f"对象转换防线被破坏：{rel_adoption} 缺失要点 {missing}——"
                "「本集合自己承认的取向」一节须登记该条（防读者把它读成标准规定，"
                "也防口径回退成强制面）",
                rel_adoption)
    phase_done()


def check_entity_dto_guard():
    """『数据契约的载体（数据库实体类不进对外契约）』防线。

    钉住用户在本轮要求里点名的这件事：**除非用户主动声明，否则不将数据库实体类作为
    接口请求、响应参数（已经用了不管），适用任何语言**。该条此前**不存在**——
    「跨服务/对外调用的请求响应类优先移动复用」的例外① 只写"数据库实体类不移动"，
    管的是"搬不搬类"，与"能不能当接口参数"是两件事；技术栈层的「对象转换」把
    `Entity ↔ DTO ↔ VO` 并列，也没有任何禁止。

    **本条钉的是判据本体、不是轴名**（见 `specs-project-maintainer/priority.adoc`
    「机械防线的核对对象是判据本体，不是轴名」）：只核『这一节在不在』属防线空转
    （判据被抽走、只剩标题与口号时仍会全绿）。故逐条核**能拿去核对的那句话**——
    『不得作为对外契约的请求参数与响应值』『不得在入参/返回值里嵌套』
    『识别判据（先判对象，再判规则）』『不看类名』『纯内部调用』『持久化自身的出口』
    『已经用了不管』『不视为违规』『除非用户主动声明』『不得泛化』。

    **四类易被静默破坏的形态**：
      * **整节被删** —— 规则消失，实体类继续当契约（最直接的破坏）；
      * **判据被压成口号** —— 只剩"尽尽量用 DTO"，判定标准与边界全丢；
      * **边界被删** —— 纯内部调用/持久化出口两条一丢，本条就被读宽成"任何函数都不得
        出现实体类"，把正常持久化层与内部调用大面积判红；
      * **"存量不管"被删** —— 用户点名的"已经用了不管"丢字，L1 被扩到存量接口上。

    归属：**通用层（跨语言）**——写进技术栈层会被替换主语测试判为放错层
    （"对外契约不得以库表结构为载体"对非 Java 项目同样成立）。故同时**反向钉住**：
    技术栈层不得出现该条的专条（防两处各写一份判据的第二真源）。

    语义判断（某次实际接口参数是不是实体类、某接口算不算"对外"）见 `GUARD_CHECK_LIMITS`。
    """
    phase("数据契约的载体防线检查（数据库实体类不进对外契约）")
    rel_coding = _rel_of(CODING_FILE)

    def _sections_of(path, missing_msg):
        if not os.path.isfile(path):
            err(missing_msg, _rel_of(path))
            return None
        with open(path, encoding="utf-8") as fh:
            return _split_adoc_sections(fh.read())

    def _section_by(sections, keyword, rel, what):
        for title, body in sections or ():
            if keyword in title:
                return body
        err(f"数据契约的载体防线被破坏：{rel} 缺少「{what}」节——本条判据失去落点"
            "（要点散在别处时，读者按节找规则找不到，等于规则不在）", rel)
        return ""

    coding_sections = _sections_of(
        CODING_FILE,
        f"缺少文件 {rel_coding}——「数据契约的载体（数据库实体类不进对外契约）」"
        "的通用层落点丢失（该条跨语言，须收在通用编码规范而非某一技术栈）")
    body = _section_by(coding_sections, ENTITY_CONTRACT_SECTION, rel_coding,
                       ENTITY_CONTRACT_SECTION)
    for keys, desc in (
        (("不得作为对外契约的请求参数与响应值（L1）",),
         "条文：须有该条并标 L1（防被降级成建议、退回「实体类最省事」）——"
         "级别须标在**这一条**上（写在别处等于没标）"),
        (("请求参数", "返回值"),
         "靶心：须点名**请求参数与响应返回值**——只写「接口参数」会被读成只管入参、"
         "不管响应，而响应侧才是字段外露的主要来源"),
        (("入参/返回值里**嵌套**它", "集合元素", "分页包装体内"),
         "**嵌套面**：须写明入参/返回值里**不得嵌套**实体类（集合元素、对象字段、"
         "分页包装体内）——只写「不得作入参/返回类型」时，"
         "`Result<List<UserEntity>>` 一类会被读成合法（正是本条要拦的常见形态）"),
        (("识别判据", "表结构"),
         "**识别判据**：须写明按「以表结构为来源」判对象、**不看类名**——"
         "缺则执行者按类名判（`UserDTO` 里逐字段对应表结构就漏判、`UserEntity` 名但"
         "与表无关的被误判）"),
        (("不看类名",),
         "**不看类名**这一句须在：它是「先判对象再判规则」的可核对形态"),
        (("载体取该接口自己的请求/响应类",),
         "**给出去路**：须写明对外接口用该接口自己的请求/响应类——只写禁令不给出路，"
         "执行者只能绕开，本条会被读成「这也不能写」"),
        (("纯内部调用", "不在本条范围内"),
         "**边界一**：须写明纯内部调用（不经跨进程/跨网络边界）不在范围内——"
         "缺则本条被读宽成「任何函数都不得出现实体类」，把正常内部编排大面积判红"),
        (("持久化自身的出口",),
         "**边界二**：须写明持久化自身的出口（仓库/DAO/Mapper 的返回）不受约束——"
         "缺则数据访问层与「持久化访问」节直接冲突（那边要求返回实体、这边禁止出现）"),
        (("项目自身规范", "为准"),
         "**冲突次序**：须写明项目自身规范可加严/收窄、冲突时以项目自身规范为准"
         "（公共内容被未知项目加载时不得静默推翻其既有约定）"),
        (("存量边界", "已经用了不管", "不视为违规"),
         "**存量口径（用户点名要件）**：须写明已有接口不视违规、不告警、不要求整改"
         "（「已经用了不管」）——缺则 L1 被扩到存量接口上，存量项目大面积命中"),
        (("随动迁移", "全库改造"),
         "存量动作：须写明随动迁移、不得据此发动全库改造（批量换参数类型、批量补 DTO）"),
        (("除非用户主动声明",),
         "**豁免面（用户原话要件）**：须写明除非用户主动声明否则一律适用——"
         "少了这句即把用户点名的那一层豁免删掉，声明过的场景会被判红"),
        (("不得泛化",),
         "**豁免的范围**：须写明声明仅对本次、该处生效、不得泛化"
         "（与「改动范围边界」的已知例外同口径）"),
        (("依据", "ISO/IEC 25010"),
         "依据行：须标标准名/编号（防依据被整段删后无从追溯）"),
    ):
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"数据契约的载体防线被破坏：{rel_coding} 的「{ENTITY_CONTRACT_SECTION}」"
                f"节缺失要点 {missing}——{desc}；该条对应用户提出的真实要求"
                "（实体类不得作为接口请求/响应参数），不得删除、不得降级、不得放开边界",
                rel_coding)

    # 归属层：该节必须在通用层（上面已按 CODING_FILE 取节）；技术栈层不得另立第二真源
    # 见下文检查。**不核"与哪一节相邻"**——相邻关系随文档重排而变，用户口径里没有这一条，
    # 拿它当判据只会让一次无关的节序调整把防线判红（实测：把「对象转换」与「持久化访问」
    # 互换即报"防线被破坏"），属机械核到了语义没核到的东西。

    # 通用层不得把该条写成框架专条/框架形态（本条跨语言：替换主语测试）
    for token, desc in (
        ("@Entity", "通用层不得点名 `@Entity` 一类映射注解——具体框架写法归技术栈层"),
        ("MyBatis", "通用层不得点名 `MyBatis`——它是具体框架名，通用层只留跨语言抽象"),
    ):
        if token in body:
            err(f"数据契约的载体防线被破坏：{rel_coding} 出现框架专名 `{token}`——{desc}",
                rel_coding)

    # 技术栈层不得另立第二真源（判据的唯一落点在通用层）
    for path, key in ((JAVA_STACK_FILE, "java.adoc"), (SPRING_STACK_FILE, "spring.adoc")):
        if not os.path.isfile(path):
            continue
        rel = _rel_of(path)
        text = open(path, encoding="utf-8").read()
        if "不进对外契约" in text or "不得作为对外契约" in text:
            err(f"数据契约的载体防线被破坏：{rel} 出现该条的专条——判据的唯一落点在"
                f"{rel_coding}（该条跨语言），技术栈层再写一份即第二真源"
                "（两处各自漂移、读者按栈文件学到的与通用层不一致）", rel)

    # 加载调度器：识别特征须落在"要判定对外接口的请求/响应参数用什么类承载"这一
    # 可判读的触发条件上（只写"数据契约"这类口号不可判读即漏加载）
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少加载调度器 {_rel_of(GENERIC_FILE)}", _rel_of(GENERIC_FILE))
    else:
        rel_common = _rel_of(GENERIC_FILE)
        with open(GENERIC_FILE, encoding="utf-8") as fh:
            gtext = fh.read()
        # 定位该行**不靠条目名**（`数据库实体类不进对外契约` 是 `coding.adoc` 的判据正文，
        # 抄进调度器即第二真源）——按「加载项是 coding.adoc + 带到对外接口的触发特征」定位。
        hit = next((l for l in gtext.split("\n")
                    if "specs/general/coding.adoc" in l and "对外接口" in l), "")
        if not hit:
            err(f"数据契约的载体防线被破坏：{rel_common} 的加载调度器里找不到带"
                "「对外接口」触发特征的 `coding.adoc` 条目——缺则写对外接口参数时"
                "不会触发加载这条（等于没写）", rel_common)
        else:
            for keys, desc in (
                (("coding.adoc",),
                 "登记须指向 `specs/general/coding.adoc`（该条跨语言，落点在通用层）"),
                (("请求/响应参数", "返回值", "用什么类承载"),
                 "识别特征须落在判据本身（要判定对外接口的请求/响应参数与返回值用什么类承载），"
                 "不是「数据契约」这类口号（识别特征不可判读即漏加载）"),
            ):
                missing = [k for k in keys if k not in hit]
                if missing:
                    err(f"数据契约的载体防线被破坏：{rel_common} 的调度条目缺失要点 "
                        f"{missing}——{desc}", rel_common)

    # 图书馆侧：本集合更严取舍须登记（防读者把本站口径读成标准规定），并如实标注
    rel_adoption = "library/adoption.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_adoption)):
        atext = open(os.path.join(REPO_ROOT, rel_adoption), encoding="utf-8").read()
        for keys, desc in (
            (("数据库实体类不得作为接口的请求/响应参数", "本集合自己的判据化取舍"),
             "「本集合自己承认的更严取舍」一节须登记该条（防读者把它读成标准规定）"),
            (("没有任何材料规定",),
             "同义性：须写明外部材料**未**规定这一层（标准只给方向与下限）"
             "——缺则该条会被读成某标准的规定"),
        ):
            missing = [k for k in keys if k not in atext]
            if missing:
                err(f"数据契约的载体防线被破坏：{rel_adoption} 缺失要点 {missing}——{desc}",
                    rel_adoption)
    phase_done()

def check_pagination_guard():
    """『分页查询返回类型与转换』防线：判据本体不得被删或降级。

    用户要求（Issue #180，原话）："调整 mybatis plus 规范，如果是普通接口，分页查询时返回
    `Result<IPage<Rsp>>`，如果是 feign 接口（`Result<自定义Page<Rsp>>`），字段转换时，
    使用 `page.convert` 而不是新建 page"。

    落点：本条属**框架专名与禁止清单**（`IPage`/Feign 的分页容器/`convert` 都是具体框架与
    声明式客户端的概念），故唯一落点为 `specs/stack/java.adoc`「持久化访问
    （MyBatis-Plus / JPA 等）」——通用层不写框架专名（`specs/general/coding.adoc` 的
    「持久化访问」只留跨语言抽象）。

    本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "有没有这一条"属防线空转——**两侧各自的返回类型**、`convert` 的**禁止面**
    （新建 page 再逐个搬运）、**保留分页元数据**这一理由、判定标准与存量边界任一被抽走时
    照样全绿。故逐组核 `script/specs-rules/coding.toml` 里的锚点。
    「某个分页接口算不算普通接口 / 该处该不该用自定义 page」属语义判断（见 `GUARD_CHECK_LIMITS`），
    交人/子 agent 复核。
    """
    phase("分页查询返回类型与转换防线检查")
    rel = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel}——「分页查询的返回类型与转换方式」的判据无处承载"
            "（该条是框架专名，落点只能在技术栈层）", rel)
    else:
        run_rule_guard("check_pagination_guard")
    phase_done()


def check_logical_delete_naming_guard():
    """『方法名与逻辑删除的对应』防线：判据本体不得被删或降级。

    用户要求（Issue #184，原话）："未使用 mybatis plus 逻辑删除时，没有前缀后缀的方法名
    默认查询且不带删除标志，如果要查询已删除/未删除……要带特征；使用 mybatis plus 逻辑删除
    时（因为会默认带删除标志），没有前缀后缀的方法名默认查询逻辑删除数据，如果要查询已删除
    和忽略删除标志的数据时，要带特征。不仅限 mybatis plus，其他类似的也生效（自己实现的
    逻辑删除逻辑和框架也算），适用所有语言"。

    落点：判据跨语言、不写框架专名，故唯一落点是 `specs/general/coding.adoc`「持久化访问
    （数据库/缓存等）」下的三级小节「方法名与逻辑删除的对应（查询方法名即删隐面）」；
    框架专名（`@TableLogic`/`@SQLDelete`）落在 `specs/stack/java.adoc`「持久化访问」。

    本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "有没有这一条"属防线空转——**默认面怎么定**、非默认面须带特征、理由、判定标准、
    边界与存量边界任一被抽走时照样全绿。故逐组核 `script/specs-rules/coding.toml`
    里的锚点；"某个方法算不算按实体查询、这个名字算不算带了特征"属语义判断
    （见 `GUARD_CHECK_LIMITS`），交人/子 agent 复核。
    """
    phase("方法名与逻辑删除的对应防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「方法名与逻辑删除的对应」的判据无处承载"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    run_rule_guard("check_logical_delete_naming_guard")
    phase_done()


def check_deprecated_api_guard():
    """『弃用类/API 防线』：不得使用被弃用的类/API、改用替代者；默认不动依赖与版本。

    用户点名的口径（本 PR 内）：**不用被弃用的类，使用其他类代替（升级类/同名新类最好），
    默认不调整依赖，也不动依赖版本**。要治的失效是「旧写法也能跑」「新写法不熟」留下的裁量点——
    裁量点一留，同一项目里就并存弃用者与其替代者两条路径，读代码的人无法预期。
    故本条钉**判据本体**（禁止面 + 替代者取向 + 默认不动依赖面），不钉轴名：只核
    「警告与弃用」这一节在不在属防线空转——把「替代者优先取升级后的新类/同名新类」
    「不得顺带改依赖清单或依赖版本」「存量条不构成对新代码的豁免」这几句可核对的话抽走时照样全绿。
    依赖侧落点在 `specs/general/dependency.adoc`「升级与废弃」，同向、须同步。
    「某个类算不算被弃用」「替代者是否等价」属语义判断，交人/子 agent 复核。
    """
    phase("弃用类/API 防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    rel_dep = os.path.relpath(DEPENDENCY_FILE, REPO_ROOT).replace("\\", "/")
    # 两处落点各自只做"文件在不在"的核对；规则（两处落点的判据本体）**跑一次**
    # ——`run_rule_guard` 按阶段去重，分开调用只会让第二次成为死代码，且任一侧文件
    # 缺失时会连另一侧的判据一起跳过（规则步骤自带"文件缺失"的报错，无需在调用侧再判）。
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「警告与弃用」的通用层落点丢失"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    if not os.path.isfile(DEPENDENCY_FILE):
        err(f"缺少文件 {rel_dep}——「升级与废弃」的通用层落点丢失"
            "（弃用迁移默认不动依赖面这条须与 `coding.adoc` 同向）", rel_dep)
    run_rule_guard("check_deprecated_api_guard")
    # 防误读（替换主语测试的邻接）：存量条（内部弃用不迁移）与新代码禁止面同处一节，
    # 后条极易被读成覆盖前条——若存量条没有「不构成对新代码的豁免」这一句即报红。
    if os.path.isfile(CODING_FILE):
        ctext = open(CODING_FILE, encoding="utf-8").read()
        section = _section_text(ctext, "警告与弃用")
        if section:
            if "不构成" not in section or "豁免" not in section:
                err(f"弃用类/API 防线被破坏：{rel_coding}「警告与弃用」的存量条未写明"
                    "「本条只管既有调用点、不构成对新代码的豁免」——两条同处一节，"
                    "缺这句话会把新代码的禁止面整段抵消（读者会以为新代码也照存量写）",
                    rel_coding)
    phase_done()


def check_readonly_landing_guard():
    """『落点只读防线』：取规范副本的落点取完即**只读**，任何项目不得改动它。

    用户口径（本 PR 新增，原话）："~/.cache/agent-specs 里的内容应该设置为只读，**不仅仅是
    规范里定义，文件本身下载后要变成只读**，并严禁项目修改此文件夹内容"。

    本条的重点正是**"不止是规范里写一条"**：两处都要核、互不替代——
      * **脚本侧**（`script/fetch-specs.py`）：真的算权限位、真的调 `chmod` 把落点收紧成只读
        （目录去掉写位＝不能在其中增删改名、文件只留读位）、落盘前只恢复本脚本所需的最小写位、
        **`--keep` 下同样收紧**、**收紧失败不得静默**（只读挂载/Windows/非属主时权限位改不动，
        那时须如实警告而不是照旧打「落点已设为只读」）；
      * **规范侧**（`AGENTS_COMMON.adoc`「取规范到本地副本」+ 入口模板）：写明"落点只读"与
        "严禁任何项目改动它"，并写明**只读由本机文件系统保证**（新实例是从复制到项目里的
        入口文档读到这件事的）。

    只核规范文本时落点仍可写、项目照旧能就地改规范副本——那正是用户点名要补的那一半
    （"不仅仅是规范里定义"）；只核脚本时读者不知道这件事、会把落点当成自己可写的便利目录。
    规则与锚点在 `script/specs-rules/readonly-landing.toml`，本函数只留接线。
    "某个项目到底有没有改过落点"属运行时事实（本仓库看不到引用方的工作区），
    交本机文件系统与实测复核（只读位让这件事从"看不出来"变成"当场失败"）。
    """
    phase("落点只读防线检查")
    rel_py = os.path.relpath(os.path.join(REPO_ROOT, "script", "fetch-specs.py"),
                             REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(os.path.join(REPO_ROOT, "script", "fetch-specs.py")):
        err(f"缺失 {rel_py}——取文件的抓手不在，「落点取完即只读」这件事无处执行"
            "（规范里写一条只读不改本机权限，落点仍是可写的）", rel_py)
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺失 {os.path.relpath(GENERIC_FILE, REPO_ROOT)}——"
            "落点只读与「严禁项目改动」的判据无处承载", INSTALL_REL)
    run_rule_guard("check_readonly_landing_guard")
    phase_done()


def check_method_placement_guard():
    """『成员与方法次序』防线：判据本体不得被删、不得降级、不得被读成「一律追加到末尾」。

    用户要求（Issue #195，原话）："新增方法/函数时，按照业务流程的先后顺序进行排序，越底层
    流程越靠后越在后面（即允许按照流程前后顺序，把新增方法加在已有方法的前面（包括最前面）
    或者中间），如果有重载方法，直接加在重载方法的附近（重载方法的排序同样按照先后顺序），
    先初始化的在前面，先用到的在前面，后面的依赖前面的……例外：接口查询数据时，要对数据库
    实体和返回模型做转换，转换方法默认写在查询接口后面。此规范只适用于新增方法/函数，不对
    已有方法生效，review 时不算问题不提出"。

    落点：判据跨语言，故判据本体唯一落点在 `specs/general/coding.adoc`「命名与代码质量」；
    Java 的成员载体（字段/方法/重载）落在 `specs/stack/java.adoc`「编码」并回指本体。

    本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "有没有这一条"属防线空转——**允许插前面或中间**、**重载相邻**、**转换跟随查询**、
    **只对新增成员生效**任一被抽走时照样全绿（只在台账里报"这一条在不在"）。故逐组核
    `script/specs-rules/coding.toml` 里的锚点；"某个方法的调用方与被调用方各是哪一个""某次
    改动算不算新增"属语义判断（见 `GUARD_CHECK_LIMITS`），交人/子 agent 复核。
    """
    phase("成员与方法次序防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「成员与方法次序」的判据无处承载"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——「成员与方法次序」的 Java 落点（字段/方法/重载）无处承载",
            rel_java)
    run_rule_guard("check_method_placement_guard")
    phase_done()


def check_chain_assignment_order_guard():
    """『链式赋值顺序随字段顺序』防线：判据本体不得被删、不得降级、不得自成第二真源。

    用户要求（Issue #190，原话）："链式调用时，比如赋值，顺序 和字段、数据库顺序保持一致"。

    落点：判据跨语言（链式 setter、builder 链、具名参数都属"赋值环节"），故判据本体唯一
    落点在 `specs/general/coding.adoc`「命名与代码质量」；Java 的赋值载体（`@Accessors
    (chain = true)` 的链式 setter、`@SuperBuilder` 的 builder 链）与模板文件的照抄约定
    各自落点。

    本函数**钉判据本体、不钉轴名**（与 `check_criteria_not_axis_guard` 同口径）：只核
    "有没有这一条"属防线空转——**字段顺序取哪两处**（回指既有两条、不另定）、赋值再排一次
    序即第二真源这一理由、判定标准、语义例外、边界与存量边界任一被抽走时照样全绿。
    故逐组核 `script/specs-rules/coding.toml` 里的锚点；"这次构建算不算同一处 / 某两次赋值
    的先后算不算语义相关"属语义判断（见 `GUARD_CHECK_LIMITS`），交人/子 agent 复核。
    """
    phase("链式赋值顺序防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「链式赋值顺序随字段顺序」的判据无处承载"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——「链式赋值顺序随字段顺序」的 Java 落点（链式 setter 与 "
            "builder 链）无处承载", rel_java)
    run_rule_guard("check_chain_assignment_order_guard")
    phase_done()


def check_persistence_access_guard():
    """『持久化访问防线』：通用层只留跨语言抽象、框架专名与禁止清单下沉到技术栈层。

"""
    phase("持久化访问（类型安全查询构造）防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「持久化访问（数据库/缓存等）」的通用层落点丢失"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    else:
        text = open(CODING_FILE, encoding="utf-8").read()
        run_rule_guard("check_persistence_access_guard")
        # 通用层不得出现具体框架专名（替换主语测试：本文件适用于所有编程语言）
        for token, desc in (
            ("IService",
             "通用层不得点名 `IService`——它是 MyBatis-Plus 专名，充当规则主语时该规则对"
             "非 Java 项目不成立（替换主语测试），且会被无条件随「编写代码」带进非 Java 项目"),
            ("QueryWrapper",
             "通用层不得点名 `QueryWrapper`/`LambdaQueryWrapper` 一族——具体禁止清单归技术栈层"),
            ("ServiceImpl",
             "通用层不得点名 `ServiceImpl`——框架专名归技术栈层"),
            ("RedisTemplate",
             "通用层不得点名 `RedisTemplate`——框架专名归技术栈层"),
        ):
            if token in text:
                err(f"持久化访问防线被破坏：{rel_coding} 出现框架专名 `{token}`——{desc}；"
                    "通用层只留跨语言抽象，框架专名与禁止清单下沉到 `specs/stack/` 对应文件",
                    rel_coding)
    # Java 栈落点：MyBatis-Plus 的四个成员方法 + IService 之外的落点 + 例外 + 判定标准 + 存量
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——持久化访问的 Java 技术栈落点丢失（框架专名的唯一落点）",
            rel_java)
    else:
        jtext = open(JAVA_STACK_FILE, encoding="utf-8").read()
        run_rule_guard("check_persistence_access_guard")
    # 加载调度器：通用层去框架专名 + Java 栈含四个成员方法与禁止面
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少加载调度器 {rel_common}", rel_common)
    else:
        ctext = open(GENERIC_FILE, encoding="utf-8").read()
        run_rule_guard("check_persistence_access_guard")
        # 通用层调度条目不得带框架专名（识别特征要触发'写持久化代码'而不是'Java 项目'）
        dispatcher_coding_start = ctext.find("  ** 编写代码 →")
        dispatcher_coding_end = ctext.find("\n  ** ", dispatcher_coding_start + 1)
        if dispatcher_coding_start != -1 and dispatcher_coding_end != -1:
            coding_entry = ctext[dispatcher_coding_start:dispatcher_coding_end]
            for token in ("IService", "QueryWrapper", "LambdaQueryWrapper"):
                if token in coding_entry:
                    err(f"持久化访问防线被破坏：{rel_common} 的通用层『编写代码』调度条目"
                        f"出现框架专名 `{token}`——通用层识别特征不得点名框架类名"
                        "（否则非 Java 项目也被带入 MyBatis-Plus 术语、且与归属层冲突）",
                        rel_common)
        # 两处调度条目须带**触发特征**（何时命中）：`查/改库`。只核这一点，不要求抄
        # 条目本体的成员方法名与禁止面（那是 `java.adoc` 的取值，抄进调度器即第二真源）。
        coding_line = next((ln for ln in ctext.splitlines()
                            if "specs/general/coding.adoc" in ln), "")
        if not coding_line or "查/改库" not in coding_line:
            err(f"持久化访问防线被破坏：{rel_common} 的通用层『编写代码』条目缺少触发特征"
                "（要写持久化访问代码——在哪个类里调持久化 API、要查/改库时即命中）——"
                "缺则读到它的场景（写持久化访问代码）不会触发加载", rel_common)
        java_line = next((ln for ln in ctext.splitlines()
                          if "specs/stack/java.adoc" in ln), "")
        if not java_line or "查/改库" not in java_line:
            err(f"持久化访问防线被破坏：{rel_common} 的 Java 技术栈登记缺少触发特征"
                "（要查/改库时即命中）——缺则 Java 项目按栈登记加载时看不到这条", rel_common)
    # 公开面：README 目录说明（读者按 README 学习时须能看到这条存在、且两处分层一致）
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE) and "持久化访问" not in open(
            README_FILE, encoding="utf-8").read():
        err(f"{rel_readme} 的目录说明未同步持久化访问条——"
            "公开面看不到这条，引用方按 README 学习时会漏掉", rel_readme)
    phase_done()


def check_api_contract_reuse_guard():
    """『请求/响应类优先移动复用 + HTTP 接口路径优先中划线』防线。

"""
    phase("请求/响应类复用与接口路径中划线防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「请求/响应类优先移动复用」的通用层落点丢失"
            "（该条跨语言，须收在通用编码规范而非某一技术栈）", rel_coding)
    else:
        text = open(CODING_FILE, encoding="utf-8").read()
        run_rule_guard("check_api_contract_reuse_guard")
    # 技术栈层：HTTP 接口路径优先中划线（唯一落点）
    rel_spring = os.path.relpath(SPRING_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(SPRING_STACK_FILE):
        err(f"缺少文件 {rel_spring}——「HTTP 接口路径优先中划线」的技术栈落点丢失"
            "（该条只在 Web 框架语境下有定义、不得写进通用层）", rel_spring)
    else:
        stext = open(SPRING_STACK_FILE, encoding="utf-8").read()
        run_rule_guard("check_api_contract_reuse_guard")
    # 通用层不得出现路径命名专条（归属：HTTP 路径只在 Web 框架语境下有定义）
    if os.path.isfile(CODING_FILE):
        ctext = open(CODING_FILE, encoding="utf-8").read()
        if "接口路径优先用中划线" in ctext or "接口路径优先使用中划线" in ctext:
            err(f"接口路径防线被破坏：{rel_coding} 出现「HTTP 接口路径」专条——"
                "该条的判据只在 Web 框架/HTTP 语境下有定义，归技术栈层；通用层写具体协议专名会"
                "把非 Web 项目也带进 HTTP 术语（与「持久化访问」的归属口径一致）", rel_coding)
    # 加载调度器：通用层与 Spring 技术栈两处识别特征（否则该条永远不会被触发加载）
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少加载调度器 {rel_common}", rel_common)
    else:
        gtext = open(GENERIC_FILE, encoding="utf-8").read()
        run_rule_guard("check_api_contract_reuse_guard")
    # 公开面：README 目录说明（读者按 README 学习时须能看到这两条存在）
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE):
        rtext = open(README_FILE, encoding="utf-8").read()
        missing = [k for k in ("请求响应类优先移动复用", "接口路径优先用中划线") if k not in rtext]
        if missing:
            err(f"{rel_readme} 的目录说明未同步要点 {missing}——"
                "公开面看不到这两条，引用方按 README 学习时会漏掉", rel_readme)
    # 图书馆侧：依据落点（引文/同义性/实证须可查到，且如实标注取样状态）
    rel_sources = "library/sources.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_sources)):
        sctext = open(os.path.join(REPO_ROOT, rel_sources), encoding="utf-8").read()
        missing = [k for k in ("HTTP 接口路径的命名风格", "请求/响应类的复用与跨模块移动",
                               "同义性") if k not in sctext]
        if missing:
            err(f"接口路径/契约复用防线被破坏：{rel_sources} 缺失要点 {missing}——"
                "依据落点须有这两条并写明同义性差异（标准只给方向与下限，"
                "判据化取值与例外清单属本集合取舍），不得让依据只剩名称", rel_sources)
    rel_adoption = "library/adoption.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_adoption)):
        atext = open(os.path.join(REPO_ROOT, rel_adoption), encoding="utf-8").read()
        missing = [k for k in ("请求/响应类优先移动复用、HTTP 接口路径优先中划线",
                               "本集合自己的判据化取舍") if k not in atext]
        if missing:
            err(f"接口路径/契约复用防线被破坏：{rel_adoption} 缺失要点 {missing}——"
                "「本集合自己承认的更严取舍」一节须登记这两条（防读者把它们读成标准规定）",
                rel_adoption)
    phase_done()


def check_api_naming_guard():
    """『Feign 接口命名带所属域/项目前缀防线』：Feign 接口的命名前缀不得退回"随手取名"。

"""
    phase("Feign 接口命名带所属域前缀防线检查")
    rel_coding = os.path.relpath(CODING_FILE, REPO_ROOT).replace(chr(92), "/")
    if not os.path.isfile(CODING_FILE):
        err(f"缺少文件 {rel_coding}——「Feign 接口命名带所属域/项目前缀」的通用层落点丢失",
            rel_coding)
    else:
        text = open(CODING_FILE, encoding="utf-8").read()
        run_rule_guard("check_api_naming_guard")
        for wide in ("对外提供或跨服务/跨项目调用的接口", "RPC/服务契约接口"):
            if wide in text:
                err(f"接口命名防线被破坏：{rel_coding} 出现被用户排除的宽口径「{wide}」——"
                    "用户要求目前只考虑 Feign，判定面不得自行放大到其他对外接口", rel_coding)
    # 技术栈层：Java（Feign 的实际落点）引用通用条
    rel_java = os.path.relpath(JAVA_STACK_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(JAVA_STACK_FILE):
        err(f"缺少文件 {rel_java}——Feign 接口命名的技术栈落点丢失", rel_java)
    else:
        jtext = open(JAVA_STACK_FILE, encoding="utf-8").read()
        missing = [k for k in ("Feign", "UcUserApi", "OucUserApi", "coding.adoc")
                   if k not in jtext]
        if missing:
            err(f"接口命名防线被破坏：{rel_java} 缺失要点 {missing}——"
                "Java 栈须写明 Feign 接口的命名前缀（含实例）并指向通用条"
                "（只让通用层有、技术栈层没有，Java 执行者按栈文件学仍会随手取名）",
                rel_java)
    # 加载调度器：两处识别特征（否则规则永远不会被加载）
    rel_common = os.path.relpath(GENERIC_FILE, REPO_ROOT).replace(chr(92), "/")
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少加载调度器 {rel_common}", rel_common)
    else:
        ctext = open(GENERIC_FILE, encoding="utf-8").read()
        missing = [k for k in ("Feign 接口命名", "只此一类") if k not in ctext]
        if missing:
            err(f"接口命名防线被破坏：{rel_common} 缺失要点 {missing}——"
                "加载调度器须在通用层（编写代码）与 Java 技术栈两处带上识别特征"
                "（含只约束 Feign 的范围标注），否则该条永远不会被触发加载"
                "或会被读成适用于所有接口", rel_common)
    # 公开面：README 目录说明（读者按 README 学习时须能看到这条存在）
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace(chr(92), "/")
    if os.path.isfile(README_FILE) and "接口命名" not in open(
            README_FILE, encoding="utf-8").read():
        err(f"{rel_readme} 的目录说明未同步接口命名前缀条——"
            "公开面看不到这条，引用方按 README 学习时会漏掉", rel_readme)
    # 图书馆侧：依据落点（引用与说明须可查到）
    rel_sources = "library/sources.adoc"
    if os.path.isfile(os.path.join(REPO_ROOT, rel_sources)):
        stext = open(os.path.join(REPO_ROOT, rel_sources), encoding="utf-8").read()
        missing = [k for k in ("Feign 接口命名带所属域前缀", "未逐字取回", "只需要考虑 feign")
                   if k not in stext]
        if missing:
            err(f"接口命名防线被破坏：{rel_sources} 缺失要点 {missing}——"
                "依据落点须有该条并如实标注取样状态（未逐字取回须写明）与范围限定"
                "（只取 Feign 这一类比标准更窄的取舍），不得让依据只剩名称", rel_sources)
    phase_done()


def check_prompts_primary():
    """『提示词主侧重与优先级防线』：侧重方向与分级规则不得被删或降级。

"""
    phase("提示词主侧重与优先级防线检查")
    rel_prompts = os.path.relpath(PROMPTS_FILE, REPO_ROOT).replace("\\", "/")

    if not os.path.isfile(PROMPTS_FILE):
        err(f"缺少提示词登记入口 {rel_prompts}——提示词的主侧重与优先级无处登记",
            rel_prompts)
        phase_done()
        return
    with open(PROMPTS_FILE, encoding="utf-8") as fh:
        registry_text = fh.read()

    # 登记表须用「主侧重片段 primary」明确标出侧重列（防登记表被改成无方向信息的清单）
    if "主侧重片段 `primary`" not in registry_text:
        err(f"提示词登记表未标注主侧重（缺少『主侧重片段 `primary`』）——"
            "侧重点属方向性内容，登记时不得省略", rel_prompts)

    registered = {}
    for name in PRIMARY_ADOC.findall(registry_text):
        registered[_normalize_primary(name)] = True

    files = _iter_prompt_files()
    if not files:
        err("prompts/ 下未找到任何任务提示词文档（除 `_` 前缀公共片段外）",
            "prompts/")

    primaries = []
    for f in files:
        rel = os.path.relpath(f, REPO_ROOT).replace("\\", "/")
        with open(f, encoding="utf-8") as fh:
            text = fh.read()
        # 1) 侧重方向须显式声明（放在正文最前，含"方向"字样）
        m = PRIMARY_LINE.search(text)
        if not m:
            err("提示词未显式声明『主侧重（方向前提）』——侧重点是最核心、方向性的内容，"
                "不得省去（须形如 `**主侧重（…）**：**<侧重>**——…方向…`）", rel)
            primary = None
        else:
            primary = m.group(1).strip()
            primaries.append(_normalize_primary(primary))
            # 正文说明段的侧重值须与方向性声明一致（防两处侧重写成两个＝方向自相矛盾）
            for other in PRIMARY_ANY.findall(text):
                if _normalize_primary(other) != _normalize_primary(primary) \
                        and _normalize_primary(other) != "本任务唯一主侧重":
                    err(f"提示词内主侧重写法不一致（『{primary}』与『{other.strip()}』）——"
                        "侧重须独此一个方向、不得自相矛盾", rel)
        # 2) 登记表须登记该提示词的侧重，且与正文一致（防同名/防侧重被复制混用）
        if primary is not None and _normalize_primary(primary) not in registered:
            err(f"提示词主侧重『{primary}』未在 {rel_prompts} 登记表中标注"
                "（登记表与正文须一致）", rel_prompts)
        # 3) 代码块内须注入 primary 与 priority-rules 两个公共片段
        for tag in ("primary", "priority-rules"):
            if f"include::_common.txt[tag={tag}]" not in text:
                err(f"提示词代码块未注入公共片段 `{tag}`——"
                    f"{'主侧重（方向）' if tag == 'primary' else '优先级规则'}缺失，"
                    "AI 无法据此判断重点", rel)

    # 4) 侧重方向不得雷同：两个提示词侧重不同（review=检查修复、refactor=重构），
    #    复制成同一个即方向混用。判定用**实际读到的侧重集合**，而非登记表条目数
    #    （登记表有两行、侧重却写成同一个时，条数相同但方向已混用）。
    if len(set(primaries)) < len(primaries):
        err(f"提示词主侧重出现重复：{sorted(set(primaries))}——"
            "各提示词侧重不同、须独立声明，复制成同一个即方向混用", rel_prompts)

    # 5) 公共片段 priority-rules 须仍在，且含三级分级与业界依据
    rel_common = os.path.relpath(COMMON_PROMPT_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(COMMON_PROMPT_FILE):
        err(f"缺少提示词公共片段 {rel_common}——优先级规则（L1/L2/L3）无处定义", rel_common)
    else:
        with open(COMMON_PROMPT_FILE, encoding="utf-8") as fh:
            common = fh.read()
        if "tag=priority-rules" not in common.replace("::", "=") and "tag::priority-rules" not in common:
            err(f"公共片段 {rel_common} 缺少 `priority-rules` 片段——"
                "提示词无法引入业界共识的优先级规则", rel_common)
        else:
            block = common.split("tag::priority-rules[]", 1)[-1].split("end::priority-rules[]", 1)[0]
            for level in ("L1 强制", "L2 建议", "L3 允许"):
                if level not in block:
                    err(f"公共片段 `priority-rules` 缺失分级定义『{level}』——"
                        "优先级被删/降级后 AI 无法判断哪里是重点", rel_common)
            for level, terms in PRIORITY_TERMS.items():
                if not any(t in block for t in terms):
                    err(f"公共片段 `priority-rules` 缺失 {level} 的判定用语（{'/'.join(terms)}）", rel_common)
            if "RFC 2119" not in block or "ISO" not in block:
                err("公共片段 `priority-rules` 未给业界共识依据（RFC 2119 / ISO）——"
                    "提示词要求按业界共识加载优先级规则，依据须保留", rel_common)
            if "不可降级" not in block:
                err("公共片段 `priority-rules` 缺失『不可降级』要求——"
                    "L1 须不可协商、不得被降级", rel_common)
    phase_done()


def check_env_marker_guard():
    """『环境标志与专用口径防线』：环境专用口径不得脱离标志、也不得漏掉中性口径。

"""
    phase("环境标志与专用口径防线检查")
    rel_common = os.path.relpath(COMMON_PROMPT_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(COMMON_PROMPT_FILE):
        err(f"缺少提示词公共片段 {rel_common}——环境标志与专用口径无处承载", rel_common)
        phase_done()
        return
    common = open(COMMON_PROMPT_FILE, encoding="utf-8").read()
    if "tag::env-guard[]" not in common.replace("::", "=") and "tag::env-guard[]" not in common:
        err(f"公共片段 {rel_common} 缺少 `env-guard`——环境专用口径失去开关与中性口径", rel_common)
    else:
        block = common.split("tag::env-guard[]", 1)[-1].split("end::env-guard[]", 1)[0]
        for key, desc in (("printenv", "标志须是可实测的命令，不得只写‘某环境’这类无法判定的描述"),
                          ("@<Agent名>", "标志的触发条件（NPC 唤起评论）须写清"),
                          ("中性口径", "未命中标志时的口径须写清，防环境专用做法被当通用要求")):
            if key not in block:
                err(f"公共片段 `env-guard` 缺失『{key}』——{desc}", rel_common)
    rel_prompts = os.path.relpath(PROMPTS_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(PROMPTS_FILE) or "env-guard" not in open(
            PROMPTS_FILE, encoding="utf-8").read():
        err(f"{rel_prompts} 未登记 `env-guard` 及其标志——新增环境专用口径须在登记处写明"
            "何时生效，否则后来者无从判断", rel_prompts)
    for f in _iter_prompt_files():
        rel = os.path.relpath(f, REPO_ROOT).replace("\\", "/")
        if "include::_common.txt[tag=env-guard]" not in open(f, encoding="utf-8").read():
            err(f"提示词 {rel} 未注入公共片段 `env-guard`——"
                "环境判断不会被执行（环境专用口径会在错误的环境里生效）", rel)
    phase_done()


def check_scope_boundary_guard():
    """『改动范围边界防线』：未声明即拒绝越界改动的边界不得被删或降级。

"""
    phase("改动范围边界防线检查")
    # ① 通用层：工作空间边界 + 平台上的仓库边界两节都在、要点齐备
    rel_g = "specs/general/scope.adoc"
    path_g = os.path.join(REPO_ROOT, *rel_g.split("/"))
    if not os.path.isfile(path_g):
        err(f"缺少文件 {rel_g}——『改动范围边界』要求无处承载"
            "（本地/服务器场景下『不得改入口工作空间以外的文件』这条通用规则缺失）", rel_g)
    else:
        text = open(path_g, encoding="utf-8").read()
        run_rule_guard("check_scope_boundary_guard")
    # ② 平台层：CNB 口径仍在（引用方按平台加载时读得到），且明写通用口径在通用层
    rel_p = "specs/platform/cnb.adoc"
    path_p = os.path.join(REPO_ROOT, *rel_p.split("/"))
    if not os.path.isfile(path_p):
        err(f"缺少文件 {rel_p}——『变更范围只限当前项目』的平台侧口径无处承载", rel_p)
    else:
        text = open(path_p, encoding="utf-8").read()
        run_rule_guard("check_scope_boundary_guard")
    # ③ 提示词侧：prompts/_common.txt 的 scope-boundary 片段 + 两个提示词代码块内引入
    rel_common = os.path.relpath(COMMON_PROMPT_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(COMMON_PROMPT_FILE):
        err(f"缺少提示词公共片段 {rel_common}——『改动范围边界』无处承载", rel_common)
    else:
        common = open(COMMON_PROMPT_FILE, encoding="utf-8").read()
        block = common.split("tag::scope-boundary[]", 1)[-1].split(
            "end::scope-boundary[]", 1)[0] if "tag::scope-boundary[]" in common else ""
        if not block:
            err(f"{rel_common} 缺少 `scope-boundary` 片段——提示词会被未知项目复制执行，"
                "漏了这层则复制出去的那份没有这条边界", rel_common)
        else:
            run_rule_guard("check_scope_boundary_guard")
    # 两个提示词代码块内都须引入该片段（少一处则该提示词复制出去后没有这条边界）
    files = _iter_prompt_files()
    if not files:
        err("prompts/ 下未找到任何任务提示词文档（除 `_` 前缀公共片段外）", "prompts/")
    for f in files:
        rel_pf = os.path.relpath(f, REPO_ROOT).replace("\\", "/")
        if "include::_common.txt[tag=scope-boundary]" not in open(f, encoding="utf-8").read():
            err(f"提示词未引入公共片段 `scope-boundary`——"
                "『改动范围边界』是该提示词复制到未知项目执行时唯一的边界来源，"
                "缺了则越界改动无人拦", rel_pf)
    phase_done()


