def check_self_dispatch_guard():
    """『不得自行发评论唤起自己防线』：执行者不得把任务在执行中重新发起一次。

"""
    phase("不得自行发评论唤起自己防线检查")
    # ① 平台层：入口一节内的同节 L1 条
    rel = "specs/platform/cnb.adoc"
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"缺少文件 {rel}——『不得自行发评论唤起自己』的平台侧口径无处承载", rel)
    else:
        text = open(path, encoding="utf-8").read()
        run_rule_guard("check_self_dispatch_guard")
    # ② 通用层：派发入口一节的同口径条
    rel_c = "specs/general/collab.adoc"
    path_c = os.path.join(REPO_ROOT, *rel_c.split("/"))
    if not os.path.isfile(path_c):
        err(f"缺少文件 {rel_c}——『派发入口』的通用侧自派禁令无处承载", rel_c)
    else:
        ctext = open(path_c, encoding="utf-8").read()
        run_rule_guard("check_self_dispatch_guard")
    # ②' 三视角复核落点：执行者选择须带适用面（防被当成平台无关的强制前提）
    rel_v = "specs/general/verify.adoc"
    path_v = os.path.join(REPO_ROOT, *rel_v.split("/"))
    if not os.path.isfile(path_v):
        err(f"缺少文件 {rel_v}——三视角复核的执行者选择无落点", rel_v)
    else:
        vtext = open(path_v, encoding="utf-8").read()
        run_rule_guard("check_self_dispatch_guard")
    # ③ 题面侧：两个提示词各须有一条同口径步骤
    files = _iter_prompt_files()
    if not files:
        err("prompts/ 下未找到任何任务提示词文档（除 `_` 前缀公共片段外）", "prompts/")
    for f in files:
        rel_f = os.path.relpath(f, REPO_ROOT).replace("\\", "/")
        ftext = open(f, encoding="utf-8").read()
        run_rule_guard("check_self_dispatch_guard")
    # ④ 登记处：公开面
    rel_prompts = os.path.relpath(PROMPTS_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(PROMPTS_FILE):
        ptext = open(PROMPTS_FILE, encoding="utf-8").read()
        missing = [k for k in ("不得自行发评论唤起自己", "分两步更清楚")
                   if k not in ptext]
        if missing:
            err(f"不得自行发评论唤起自己防线被破坏：{rel_prompts} 缺失要点 {missing}——"
                "公共约定须登记该边界（提示词会被未知项目复制执行，漏了这层"
                "则复制出去的那份没有这条禁令）", rel_prompts)
    else:
        err(f"缺少公开提示词入口 {rel_prompts}——自派禁令无处登记", rel_prompts)
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE):
        rtext = open(README_FILE, encoding="utf-8").read()
        if "唤起自己" not in rtext or "分两步更清楚" not in rtext:
            err(f"不得自行发评论唤起自己防线被破坏：{rel_readme} 的使用要点未同步——"
                "公开面只看得见'可以评论派活'、看不到'执行者不得自己唤自己'", rel_readme)
    else:
        err(f"缺少 {rel_readme}——自派禁令的公开面说明无处承载", rel_readme)
    # ⑤ 调度器两处识别特征
    a_path = os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc")
    if os.path.isfile(a_path):
        atext = open(a_path, encoding="utf-8").read()
        # 只核**触发特征**（要发评论 / 按评论派发时即命中），不核条目本体句
        # （`执行者不得自行发评论唤起自己` 是 `collab.adoc`/`cnb.adoc` 的判据正文，
        # 抄进调度器即第二真源）：两处（多 agent 协作 + CNB 平台）都要能触发本条。
        collab_disp = next((ln for ln in atext.splitlines()
                            if "specs/general/collab.adoc" in ln), "")
        cnb_disp = next((ln for ln in atext.splitlines()
                         if "specs/platform/cnb.adoc" in ln), "")
        if not collab_disp or "评论" not in collab_disp:
            err("不得自行发评论唤起自己防线被破坏：AGENTS_COMMON.adoc 的『多 agent 协作』"
                "条目须含触发特征（要发评论/按评论派发即命中，缺则该 L1 永远不会被触发加载）",
                "AGENTS_COMMON.adoc")
        if not cnb_disp or "评论" not in cnb_disp:
            err("不得自行发评论唤起自己防线被破坏：AGENTS_COMMON.adoc 的『CNB 平台』"
                "条目须含触发特征（要发评论/按评论派发即命中，缺则该 L1 永远不会被触发加载）",
                "AGENTS_COMMON.adoc")
    else:
        err("缺少 AGENTS_COMMON.adoc——加载调度器无处登记该识别特征", "AGENTS_COMMON.adoc")
    phase_done()


