def check_delivery_guard():
    """『交付形态与报告落点防线』：不得中途冒过程性叙述、不得只交付不汇报。

"""
    phase("交付形态与报告落点防线检查")
    rel_common = os.path.relpath(COMMON_PROMPT_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(COMMON_PROMPT_FILE):
        err(f"缺少提示词公共片段 {rel_common}——『交付形态与报告落点』无处承载", rel_common)
        phase_done()
        return
    common = open(COMMON_PROMPT_FILE, encoding="utf-8").read()
    block = common.split("tag::delivery[]", 1)[-1].split("end::delivery[]", 1)[0] \
        if "tag::delivery[]" in common else ""
    if not block:
        err(f"{rel_common} 缺少 `delivery` 片段——交付形态与报告落点失去落点", rel_common)
    else:
        run_rule_guard("check_delivery_guard")
    # 题面侧：两个提示词各须有"交付即汇报"步骤（片段证不了题面）
    files = _iter_prompt_files()
    if not files:
        err("prompts/ 下未找到任何任务提示词文档（除 `_` 前缀公共片段外）", "prompts/")
    for f in files:
        rel = os.path.relpath(f, REPO_ROOT).replace("\\", "/")
        text = open(f, encoding="utf-8").read()
        run_rule_guard("check_delivery_guard")
    # 登记处：公开面（提示词入口与 README 使用要点）
    rel_prompts = os.path.relpath(PROMPTS_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(PROMPTS_FILE):
        err(f"缺少公开提示词入口 {rel_prompts}——公共约定无处登记", rel_prompts)
    else:
        ptext = open(PROMPTS_FILE, encoding="utf-8").read()
        run_rule_guard("check_delivery_guard")
    rel_readme = os.path.relpath(README_FILE, REPO_ROOT).replace("\\", "/")
    if os.path.isfile(README_FILE):
        rtext = open(README_FILE, encoding="utf-8").read()
        missing = [k for k in ("过程性叙述", "不得作为独立评论发出去", "却没有任何提交",
                               "输出通道只有两条", "除这两条之外的任何中间话一律不发")
                   if k not in rtext]
        if missing:
            err(f"交付形态与报告落点防线被破坏：{rel_readme} 的使用要点缺失 {missing}——"
                "公开面看不到『不得只冒一句话、不得只交付不汇报』这条边界", rel_readme)
    # 片段**被装配**面（L1，防"定义了但没人 include"）：`_common.txt` 里的每个 `tag::<name>[]`
    # 都须被**某一份提示词**以 `include::_common.txt[tag=<name>]` 取用。缺则片段是**死内容**——
    # 它不进任何提示词正文（题面末句即便复述其大意也无判据强度），维护者以为"已经写了"，
    # 实际每一次执行都拿不到它。本轮实证：`no-self-dispatch` 片段写好、两个提示词却只在末句
    # 复述一句「完整口径见 `_common.txt` 的 `no-self-dispatch` 片段」，include 一次都没有
    # ——"防无限派发"这条 L1 在装配层就是空的。
    if common:
        wired = set(re.findall(r"include::_common\.txt\[tag=([a-z][a-z0-9-]*)\]",
                               "".join(open(f, encoding="utf-8").read() for f in files)))
        for tag in re.findall(r"^// tag::([a-z][a-z0-9-]*)\[\]$", common, re.M):
            if tag not in wired:
                err(f"交付形态与报告落点防线被破坏：{rel_common} 的 `{tag}` 片段没有任何提示词"
                    f"`include`（现有接线：{sorted(wired)}）——片段未被装配即等于没写："
                    "题面末句复述其大意时不具判据强度，执行者拿不到该条正文", rel_common)
    phase_done()


def check_changelog_timing_guard():
    """『变更日志声明优先防线』：changelog **除非主动声明，否则不新增、不修改**（本仓库特有）。

"""
    phase("变更日志登记时机防线检查")
    rel_agents = "AGENTS.adoc"
    path_agents = os.path.join(REPO_ROOT, rel_agents)
    if not os.path.isfile(path_agents):
        err(f"缺少项目规范入口 {rel_agents}——changelog 登记时机条无处承载", rel_agents)
    else:
        atext = open(path_agents, encoding="utf-8").read()
        run_rule_guard("check_changelog_timing_guard")
    rel_eff = os.path.join("script", "check_effective.py")
    if os.path.isfile(os.path.join(REPO_ROOT, rel_eff)):
        etext = open(os.path.join(REPO_ROOT, rel_eff), encoding="utf-8").read()
        run_rule_guard("check_changelog_timing_guard")
    else:
        err(f"缺少 {rel_eff}——『定义未执行』登记处缺失，本条成为无抓手条款", rel_eff)
    phase_done()


